export type DownloadStatus =
  | 'unavailable'
  | 'queued'
  | 'downloading'
  | 'downloaded'
  | 'failed'
  | 'interrupted';

export type Folder = {
  id: number;
  name: string;
  createdAt: number;
  videoCount: number;
};

export type SavedVideo = {
  youtubeId: string;
  title: string;
  thumbnailUrl: string;
  channelName: string;
  durationSeconds: number | null;
  publishedAt: string | null;
  description: string | null;
  folderId: number | null;
  folderName: string | null;
  addedAt: number;
  metadataFetchedAt: number;
  downloadStatus: DownloadStatus;
  downloadProgress: number;
  downloadedFileUri: string | null;
};

export type ChannelVideo = {
  youtubeId: string;
  title: string;
  thumbnailUrl: string;
  channelName: string;
  channelHandle: string;
  durationSeconds: number | null;
  publishedAt: string;
  description: string | null;
  fetchedAt: number;
};

export type ChannelPlaylist = {
  playlistId: string;
  title: string;
  description: string | null;
  thumbnailUrl: string;
  channelName: string;
  channelHandle: string;
  itemCount: number;
  publishedAt: string;
};

export type PageResult<T> = {
  items: T[];
  nextPageToken: string | null;
};

export type PlayableVideo = Pick<
  SavedVideo,
  | 'youtubeId'
  | 'title'
  | 'thumbnailUrl'
  | 'channelName'
  | 'durationSeconds'
  | 'publishedAt'
  | 'description'
>;

