import type { HardcodedChannel } from '@/config/channels';
import type {
  ChannelPlaylist,
  ChannelVideo,
  PageResult,
  PlayableVideo,
} from '@/types';

const YOUTUBE_API_BASE = 'https://www.googleapis.com/youtube/v3';
const OEMBED_ENDPOINT = 'https://www.youtube.com/oembed';
const VIDEO_ID_PATTERN = /^[A-Za-z0-9_-]{11}$/;
const REQUEST_TIMEOUT_MS = 15_000;
const PAGE_SIZE = '20';

type OEmbedResponse = {
  title: string;
  author_name: string;
  thumbnail_url: string;
};

type ApiThumbnail = { url: string };
type ApiThumbnails = {
  maxres?: ApiThumbnail;
  standard?: ApiThumbnail;
  high?: ApiThumbnail;
  medium?: ApiThumbnail;
  default?: ApiThumbnail;
};

type VideoApiItem = {
  id: string;
  snippet: {
    title: string;
    description?: string;
    channelTitle: string;
    publishedAt: string;
    thumbnails: ApiThumbnails;
  };
  contentDetails: { duration: string };
};

type VideosApiResponse = { items: VideoApiItem[] };

type ChannelsApiResponse = {
  items: Array<{
    id: string;
    contentDetails: { relatedPlaylists: { uploads: string } };
  }>;
};

type PlaylistItemsApiResponse = {
  nextPageToken?: string;
  items: Array<{ contentDetails: { videoId: string; videoPublishedAt?: string } }>;
};

type PlaylistsApiResponse = {
  nextPageToken?: string;
  items: Array<{
    id: string;
    snippet: {
      title: string;
      description?: string;
      channelTitle: string;
      publishedAt: string;
      thumbnails: ApiThumbnails;
    };
    contentDetails: { itemCount: number };
  }>;
};

export class YouTubeServiceError extends Error {
  constructor(
    message: string,
    readonly kind: 'invalid-url' | 'not-found' | 'api-key' | 'network' | 'api',
  ) {
    super(message);
  }
}

async function fetchJson<T>(url: string): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok) {
      if (response.status === 404) {
        throw new YouTubeServiceError('This YouTube item is unavailable or private.', 'not-found');
      }
      throw new YouTubeServiceError(
        `YouTube returned an error (${response.status}). Try again later.`,
        'api',
      );
    }
    return (await response.json()) as T;
  } catch (error) {
    if (error instanceof YouTubeServiceError) {
      throw error;
    }
    throw new YouTubeServiceError(
      'Could not reach YouTube. Check your connection and try again.',
      'network',
    );
  } finally {
    clearTimeout(timeout);
  }
}

function chooseThumbnail(thumbnails: ApiThumbnails): string {
  return (
    thumbnails.maxres ??
    thumbnails.standard ??
    thumbnails.high ??
    thumbnails.medium ??
    thumbnails.default
  )?.url ?? '';
}

function requireApiKey(apiKey: string): string {
  const key = apiKey.trim();
  if (key.length === 0) {
    throw new YouTubeServiceError(
      'Add EXPO_PUBLIC_YOUTUBE_API_KEY to .env to load channels and playlists.',
      'api-key',
    );
  }
  return key;
}

export function parseYouTubeVideoId(input: string): string {
  let url: URL;
  try {
    url = new URL(input.trim());
  } catch {
    throw new YouTubeServiceError(
      'Paste a complete YouTube video URL, such as https://youtu.be/...',
      'invalid-url',
    );
  }

  if (url.protocol !== 'https:' && url.protocol !== 'http:') {
    throw new YouTubeServiceError('Only web links are supported.', 'invalid-url');
  }

  const hostname = url.hostname.toLowerCase().replace(/^www\./, '');
  let videoId: string | null = null;
  if (hostname === 'youtu.be') {
    videoId = url.pathname.split('/').filter(Boolean)[0] ?? null;
  } else if (
    hostname === 'youtube.com' ||
    hostname === 'm.youtube.com' ||
    hostname === 'music.youtube.com' ||
    hostname === 'youtube-nocookie.com'
  ) {
    if (url.pathname === '/watch') {
      videoId = url.searchParams.get('v');
    } else {
      const [kind, candidate] = url.pathname.split('/').filter(Boolean);
      if (kind === 'shorts' || kind === 'embed' || kind === 'live') {
        videoId = candidate ?? null;
      }
    }
  }

  if (videoId === null || !VIDEO_ID_PATTERN.test(videoId)) {
    throw new YouTubeServiceError('This is not a supported YouTube video URL.', 'invalid-url');
  }
  return videoId;
}

export function parseIsoDuration(value: string): number | null {
  const match = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(value);
  if (match === null) {
    return null;
  }
  return Number(match[1] ?? 0) * 3600 + Number(match[2] ?? 0) * 60 + Number(match[3] ?? 0);
}

function videosUrl(ids: readonly string[], apiKey: string): string {
  return `${YOUTUBE_API_BASE}/videos?${new URLSearchParams({
    part: 'snippet,contentDetails',
    id: ids.join(','),
    key: apiKey,
  }).toString()}`;
}

async function getVideoFromDataApi(youtubeId: string, apiKey: string): Promise<VideoApiItem | null> {
  if (apiKey.length === 0) {
    return null;
  }
  const response = await fetchJson<VideosApiResponse>(videosUrl([youtubeId], apiKey));
  return response.items[0] ?? null;
}

export async function fetchVideoMetadata(
  urlOrVideoId: string,
  apiKey: string,
): Promise<PlayableVideo> {
  const youtubeId = VIDEO_ID_PATTERN.test(urlOrVideoId)
    ? urlOrVideoId
    : parseYouTubeVideoId(urlOrVideoId);
  const canonicalUrl = `https://www.youtube.com/watch?v=${youtubeId}`;
  const oembedUrl = `${OEMBED_ENDPOINT}?${new URLSearchParams({
    url: canonicalUrl,
    format: 'json',
  }).toString()}`;

  const [oembedResult, apiResult] = await Promise.allSettled([
    fetchJson<OEmbedResponse>(oembedUrl),
    getVideoFromDataApi(youtubeId, apiKey),
  ]);
  const oembed = oembedResult.status === 'fulfilled' ? oembedResult.value : null;
  const apiItem = apiResult.status === 'fulfilled' ? apiResult.value : null;

  if (oembed === null && apiItem === null) {
    if (oembedResult.status === 'rejected') {
      throw oembedResult.reason;
    }
    throw new YouTubeServiceError('Video metadata could not be loaded.', 'api');
  }

  return {
    youtubeId,
    title: apiItem?.snippet.title ?? oembed!.title,
    thumbnailUrl: apiItem ? chooseThumbnail(apiItem.snippet.thumbnails) : oembed!.thumbnail_url,
    channelName: apiItem?.snippet.channelTitle ?? oembed!.author_name,
    durationSeconds: apiItem ? parseIsoDuration(apiItem.contentDetails.duration) : null,
    publishedAt: apiItem?.snippet.publishedAt ?? null,
    description: apiItem?.snippet.description?.trim() || null,
  };
}

async function resolveChannel(
  channel: HardcodedChannel,
  apiKey: string,
): Promise<{ channelId: string; uploadsPlaylistId: string }> {
  const params = new URLSearchParams({
    part: 'contentDetails',
    forHandle: channel.channelHandle.slice(1),
    key: requireApiKey(apiKey),
  });
  const response = await fetchJson<ChannelsApiResponse>(
    `${YOUTUBE_API_BASE}/channels?${params.toString()}`,
  );
  const item = response.items[0];
  if (!item) {
    throw new YouTubeServiceError(
      `${channel.name} could not be found. Check its handle in src/config/channels.ts.`,
      'not-found',
    );
  }
  return { channelId: item.id, uploadsPlaylistId: item.contentDetails.relatedPlaylists.uploads };
}

async function hydrateVideoPage(
  videoIds: readonly string[],
  channelHandle: string,
  apiKey: string,
): Promise<ChannelVideo[]> {
  if (videoIds.length === 0) {
    return [];
  }
  const response = await fetchJson<VideosApiResponse>(videosUrl(videoIds, apiKey));
  const byId = new Map(response.items.map((item) => [item.id, item]));
  const fetchedAt = Date.now();
  return videoIds.flatMap((youtubeId) => {
    const item = byId.get(youtubeId);
    if (!item) {
      return [];
    }
    return [{
      youtubeId: item.id,
      title: item.snippet.title,
      thumbnailUrl: chooseThumbnail(item.snippet.thumbnails),
      channelName: item.snippet.channelTitle,
      channelHandle,
      durationSeconds: parseIsoDuration(item.contentDetails.duration),
      publishedAt: item.snippet.publishedAt,
      description: item.snippet.description?.trim() || null,
      fetchedAt,
    }];
  });
}

async function fetchVideoPageFromPlaylist(
  playlistId: string,
  channelHandle: string,
  apiKey: string,
  pageToken?: string | null,
): Promise<PageResult<ChannelVideo>> {
  const key = requireApiKey(apiKey);
  const params = new URLSearchParams({
    part: 'contentDetails',
    playlistId,
    maxResults: PAGE_SIZE,
    key,
  });
  if (pageToken) {
    params.set('pageToken', pageToken);
  }
  const response = await fetchJson<PlaylistItemsApiResponse>(
    `${YOUTUBE_API_BASE}/playlistItems?${params.toString()}`,
  );
  const ids = response.items.map((item) => item.contentDetails.videoId);
  return {
    items: await hydrateVideoPage(ids, channelHandle, key),
    nextPageToken: response.nextPageToken ?? null,
  };
}

export async function fetchChannelVideoPage(
  channel: HardcodedChannel,
  apiKey: string,
  pageToken?: string | null,
): Promise<PageResult<ChannelVideo>> {
  const resolved = await resolveChannel(channel, apiKey);
  return fetchVideoPageFromPlaylist(
    resolved.uploadsPlaylistId,
    channel.channelHandle,
    apiKey,
    pageToken,
  );
}

export async function fetchChannelPlaylistPage(
  channel: HardcodedChannel,
  apiKey: string,
  pageToken?: string | null,
): Promise<PageResult<ChannelPlaylist>> {
  const key = requireApiKey(apiKey);
  const { channelId } = await resolveChannel(channel, key);
  const params = new URLSearchParams({
    part: 'snippet,contentDetails',
    channelId,
    maxResults: PAGE_SIZE,
    key,
  });
  if (pageToken) {
    params.set('pageToken', pageToken);
  }
  const response = await fetchJson<PlaylistsApiResponse>(
    `${YOUTUBE_API_BASE}/playlists?${params.toString()}`,
  );
  return {
    items: response.items.map((item) => ({
      playlistId: item.id,
      title: item.snippet.title,
      description: item.snippet.description?.trim() || null,
      thumbnailUrl: chooseThumbnail(item.snippet.thumbnails),
      channelName: item.snippet.channelTitle,
      channelHandle: channel.channelHandle,
      itemCount: item.contentDetails.itemCount,
      publishedAt: item.snippet.publishedAt,
    })),
    nextPageToken: response.nextPageToken ?? null,
  };
}

export async function fetchPlaylistVideoPage(
  playlist: ChannelPlaylist,
  apiKey: string,
  pageToken?: string | null,
): Promise<PageResult<ChannelVideo>> {
  return fetchVideoPageFromPlaylist(
    playlist.playlistId,
    playlist.channelHandle,
    apiKey,
    pageToken,
  );
}

export async function fetchConfiguredChannelVideos(
  channels: readonly HardcodedChannel[],
  apiKey: string,
): Promise<ChannelVideo[]> {
  requireApiKey(apiKey);
  const results = await Promise.all(
    channels.map((channel) => fetchChannelVideoPage(channel, apiKey)),
  );
  return results.flatMap((result) => result.items);
}

