import { Pressable, StyleSheet, Text, View } from 'react-native';
import Ionicons from '@expo/vector-icons/Ionicons';

import { BottomSheet } from '@/components/BottomSheet';
import { colors, radius, spacing } from '@/constants/theme';
import type { SavedVideo } from '@/types';

type VideoActionsModalProps = {
  video: SavedVideo | null;
  onClose: () => void;
  onMove: () => void;
  onOfflineInfo: () => void;
  onDelete: () => void;
};

export function VideoActionsModal({
  video,
  onClose,
  onMove,
  onOfflineInfo,
  onDelete,
}: VideoActionsModalProps) {
  return (
    <BottomSheet onClose={onClose} visible={video !== null}>
      <Text numberOfLines={2} style={styles.title}>
        {video?.title}
      </Text>
      <View style={styles.list}>
        <ActionRow icon="folder-outline" label="Move to folder" onPress={onMove} />
        <ActionRow icon="cloud-outline" label="Offline availability" onPress={onOfflineInfo} />
        <ActionRow danger icon="trash-outline" label="Delete from library" onPress={onDelete} />
      </View>
    </BottomSheet>
  );
}

function ActionRow({
  icon,
  label,
  onPress,
  danger = false,
}: {
  icon: 'folder-outline' | 'cloud-outline' | 'trash-outline';
  label: string;
  onPress: () => void;
  danger?: boolean;
}) {
  const color = danger ? colors.danger : colors.ink;
  return (
    <Pressable
      accessibilityRole="button"
      onPress={onPress}
      style={({ pressed }) => [styles.row, pressed && styles.pressed]}
    >
      <Ionicons color={color} name={icon} size={21} />
      <Text style={[styles.rowLabel, { color }]}>{label}</Text>
      <Ionicons color={colors.inkMuted} name="chevron-forward" size={18} />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  title: {
    color: colors.ink,
    fontFamily: 'serif',
    fontSize: 20,
    lineHeight: 26,
    fontWeight: '600',
    marginBottom: spacing.lg,
  },
  list: {
    gap: spacing.sm,
  },
  row: {
    minHeight: 52,
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.md,
    paddingHorizontal: spacing.md,
    borderRadius: radius.md,
    backgroundColor: colors.surface,
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: colors.border,
  },
  rowLabel: {
    flex: 1,
    fontSize: 15,
    fontFamily: 'sans-serif-medium',
  },
  pressed: {
    opacity: 0.65,
  },
});

