import type { SQLiteDatabase } from 'expo-sqlite';

const DATABASE_VERSION = 4;

export async function migrateDatabase(db: SQLiteDatabase): Promise<void> {
  await db.execAsync('PRAGMA journal_mode = WAL;');
  const versionRow = await db.getFirstAsync<{ user_version: number }>('PRAGMA user_version');
  const currentVersion = versionRow?.user_version ?? 0;

  if (currentVersion >= DATABASE_VERSION) {
    await db.execAsync('PRAGMA foreign_keys = ON;');
    return;
  }

  if (currentVersion < 1) {
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS folders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL COLLATE NOCASE UNIQUE,
        created_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS saved_videos (
        youtube_id TEXT PRIMARY KEY NOT NULL,
        title TEXT NOT NULL,
        thumbnail_url TEXT NOT NULL,
        channel_name TEXT NOT NULL,
        duration_seconds INTEGER,
        published_at TEXT,
        description TEXT,
        folder_id INTEGER REFERENCES folders(id) ON DELETE SET NULL,
        added_at INTEGER NOT NULL,
        metadata_fetched_at INTEGER NOT NULL,
        download_status TEXT NOT NULL DEFAULT 'unavailable',
        download_progress REAL NOT NULL DEFAULT 0,
        downloaded_file_uri TEXT
      );

      CREATE INDEX IF NOT EXISTS saved_videos_folder_id_idx
        ON saved_videos(folder_id);

      CREATE TABLE IF NOT EXISTS channel_videos (
        youtube_id TEXT NOT NULL,
        channel_handle TEXT NOT NULL,
        title TEXT NOT NULL,
        thumbnail_url TEXT NOT NULL,
        channel_name TEXT NOT NULL,
        duration_seconds INTEGER,
        published_at TEXT NOT NULL,
        description TEXT,
        fetched_at INTEGER NOT NULL,
        PRIMARY KEY (youtube_id, channel_handle)
      );
    `);
  }

  if (currentVersion < 2) {
    const savedColumns = await db.getAllAsync<{ name: string }>('PRAGMA table_info(saved_videos)');
    if (!savedColumns.some((column) => column.name === 'description')) {
      await db.execAsync('ALTER TABLE saved_videos ADD COLUMN description TEXT;');
    }

    const channelColumns = await db.getAllAsync<{ name: string }>('PRAGMA table_info(channel_videos)');
    if (!channelColumns.some((column) => column.name === 'description')) {
      await db.execAsync('ALTER TABLE channel_videos ADD COLUMN description TEXT;');
    }
  }

  if (currentVersion > 0 && currentVersion < 3) {
    await db.execAsync('PRAGMA foreign_keys = OFF;');
    try {
      await db.withTransactionAsync(async () => {
        await db.execAsync(`
          CREATE TABLE saved_videos_v3 (
            youtube_id TEXT PRIMARY KEY NOT NULL,
            title TEXT NOT NULL,
            thumbnail_url TEXT NOT NULL,
            channel_name TEXT NOT NULL,
            duration_seconds INTEGER,
            published_at TEXT,
            description TEXT,
            folder_id INTEGER REFERENCES folders(id) ON DELETE SET NULL,
            added_at INTEGER NOT NULL,
            metadata_fetched_at INTEGER NOT NULL
          );

          INSERT INTO saved_videos_v3 (
            youtube_id, title, thumbnail_url, channel_name, duration_seconds,
            published_at, description, folder_id, added_at, metadata_fetched_at
          )
          SELECT
            youtube_id, title, thumbnail_url, channel_name, duration_seconds,
            published_at, description, folder_id, added_at, metadata_fetched_at
          FROM saved_videos;

          DROP TABLE saved_videos;
          ALTER TABLE saved_videos_v3 RENAME TO saved_videos;
          CREATE INDEX saved_videos_folder_id_idx ON saved_videos(folder_id);
        `);
      });
    } finally {
      await db.execAsync('PRAGMA foreign_keys = ON;');
    }
  }

  if (currentVersion < 4) {
    const savedColumns = await db.getAllAsync<{ name: string }>('PRAGMA table_info(saved_videos)');
    if (!savedColumns.some((column) => column.name === 'download_status')) {
      await db.execAsync(
        "ALTER TABLE saved_videos ADD COLUMN download_status TEXT NOT NULL DEFAULT 'unavailable';",
      );
    }
    if (!savedColumns.some((column) => column.name === 'download_progress')) {
      await db.execAsync(
        'ALTER TABLE saved_videos ADD COLUMN download_progress REAL NOT NULL DEFAULT 0;',
      );
    }
    if (!savedColumns.some((column) => column.name === 'downloaded_file_uri')) {
      await db.execAsync('ALTER TABLE saved_videos ADD COLUMN downloaded_file_uri TEXT;');
    }
  }

  await db.execAsync(`PRAGMA user_version = ${DATABASE_VERSION}; PRAGMA foreign_keys = ON;`);
}

