1	import Ionicons from '@expo/vector-icons/Ionicons';
2	import { Image } from 'expo-image';
3	import { useEffect, useState } from 'react';
4	import { Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
5	
6	import { AppButton } from '@/components/AppButton';
7	import { FolderPickerModal } from '@/components/FolderPickerModal';
8	import { ScreenHeader } from '@/components/ScreenHeader';
9	import { YouTubePlayer } from '@/components/YouTubePlayer';
10	import { colors, radius, spacing } from '@/constants/theme';
11	import { useLibrary } from '@/context/LibraryContext';
12	import { useAppNavigation } from '@/context/NavigationContext';
13	import { fetchVideoMetadata } from '@/services/youtube';
14	import type { PlayableVideo } from '@/types';
15	import { formatDuration, formatPublishedDate } from '@/utils/format';
16	
17	type PlayerScreenProps = { video: PlayableVideo };
18	
19	export function PlayerScreen({ video }: PlayerScreenProps) {
20	  const { goBack } = useAppNavigation();
21	  const { folders, saveVideo, videos } = useLibrary();
22	  const [playerError, setPlayerError] = useState<string | null>(null);
23	  const [ended, setEnded] = useState(false);
24	  const [playerSession, setPlayerSession] = useState(0);
25	  const [descriptionExpanded, setDescriptionExpanded] = useState(false);
26	  const [description, setDescription] = useState(video.description);
27	  const [saveVisible, setSaveVisible] = useState(false);
28	  const saved = videos.some((savedVideo) => savedVideo.youtubeId === video.youtubeId);
29	  const duration = formatDuration(video.durationSeconds);
30	  const published = formatPublishedDate(video.publishedAt);
31	
32	  useEffect(() => {
33	    if (description) {
34	      return;
35	    }
36	    let active = true;
37	    void fetchVideoMetadata(
38	      video.youtubeId,
39	      process.env.EXPO_PUBLIC_YOUTUBE_API_KEY?.trim() ?? '',
40	    ).then((metadata) => {
41	      if (active) {
42	        setDescription(metadata.description);
43	      }
44	    }).catch(() => undefined);
45	    return () => {
46	      active = false;
47	    };
48	  }, [description, video.youtubeId]);
49	
50	  const replay = () => {
51	    setEnded(false);
52	    setPlayerError(null);
53	    setPlayerSession((session) => session + 1);
54	  };
55	
56	  return (
57	    <View style={styles.screen}>
58	      <ScreenHeader onBack={goBack} subtitle="Focused playback" title="Now playing" />
59	      <ScrollView contentContainerStyle={styles.content}>
60	        {playerError ? (
61	          <View style={styles.errorPanel}>
62	            <Ionicons color={colors.danger} name="alert-circle-outline" size={28} />
63	            <Text style={styles.errorTitle}>Playback unavailable</Text>
64	            <Text style={styles.errorMessage}>{playerError}</Text>
65	          </View>
66	        ) : ended ? (
67	          <View style={styles.endedPanel}>
68	            <Image contentFit="cover" source={{ uri: video.thumbnailUrl }} style={styles.endedImage} />
69	            <View style={styles.endedShade} />
70	            <Pressable
71	              accessibilityLabel="Replay video"
72	              accessibilityRole="button"
73	              onPress={replay}
74	              style={({ pressed }) => [styles.replay, pressed && styles.pressed]}
75	            >
76	              <Ionicons color={colors.black} name="refresh" size={22} />
77	              <Text style={styles.replayText}>Replay</Text>
78	            </Pressable>
79	          </View>
80	        ) : (
81	          <YouTubePlayer
82	            key={playerSession}
83	            onEnded={() => setEnded(true)}
84	            onError={setPlayerError}
85	            youtubeId={video.youtubeId}
86	          />
87	        )}
88	        <View style={styles.details}>
89	          <Text style={styles.attribution}>YOUTUBE PLAYBACK</Text>
90	          <Text style={styles.title}>{video.title}</Text>
91	          <Text style={styles.channel}>{video.channelName}</Text>
92	          {duration || published ? (
93	            <Text style={styles.metadata}>{[duration, published].filter(Boolean).join('  ·  ')}</Text>
94	          ) : null}
95	          <AppButton
96	            disabled={saved}
97	            icon={saved ? 'checkmark-circle' : 'bookmark-outline'}
98	            label={saved ? 'Saved to library' : 'Save video'}
99	            onPress={() => setSaveVisible(true)}
100	            style={styles.saveButton}
101	            variant={saved ? 'secondary' : 'primary'}
102	          />
103	          {description ? (
104	            <View style={styles.descriptionBlock}>
105	              <Text style={styles.descriptionLabel}>DESCRIPTION</Text>
106	              <Text
107	                numberOfLines={descriptionExpanded ? undefined : 5}
108	                style={styles.description}
109	              >
110	                {description}
111	              </Text>
112	              <Pressable
113	                accessibilityRole="button"
114	                onPress={() => setDescriptionExpanded((expanded) => !expanded)}
115	                style={({ pressed }) => pressed && styles.pressed}
116	              >
117	                <Text style={styles.more}>{descriptionExpanded ? 'Show less' : 'Show more'}</Text>
118	              </Pressable>
119	            </View>
120	          ) : null}
121	        </View>
122	      </ScrollView>
123	      <FolderPickerModal
124	        currentFolderId={null}
125	        folders={folders}
126	        onClose={() => setSaveVisible(false)}
127	        onSelect={(folderId) => {
128	          setSaveVisible(false);
129	          void saveVideo({ ...video, description }, folderId).catch((error: unknown) => {
130	            Alert.alert(
131	              'Could not save video',
132	              error instanceof Error ? error.message : 'Try again.',
133	            );
134	          });
135	        }}
136	        title="Save to folder"
137	        visible={saveVisible}
138	      />
139	    </View>
140	  );
141	}
142	
143	const styles = StyleSheet.create({
144	  screen: { flex: 1, backgroundColor: colors.background },
145	  content: { paddingBottom: spacing.xxl },
146	  errorPanel: {
147	    minHeight: 240,
148	    alignItems: 'center',
149	    justifyContent: 'center',
150	    paddingHorizontal: spacing.xl,
151	  },
152	  errorTitle: { color: colors.ink, fontSize: 18, marginTop: spacing.md },
153	  errorMessage: {
154	    color: colors.inkMuted,
155	    fontSize: 13,
156	    lineHeight: 19,
157	    marginTop: spacing.sm,
158	    textAlign: 'center',
159	  },
160	  endedPanel: {
161	    width: '100%',
162	    aspectRatio: 16 / 9,
163	    minHeight: 200,
164	    alignItems: 'center',
165	    justifyContent: 'center',
166	    overflow: 'hidden',
167	    backgroundColor: colors.black,
168	  },
169	  endedImage: { position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 },
170	  endedShade: {
171	    position: 'absolute',
172	    top: 0,
173	    right: 0,
174	    bottom: 0,
175	    left: 0,
176	    backgroundColor: 'rgba(5, 6, 5, 0.62)',
177	  },
