    if (match) {
      job.progress = Math.min(1, Number(match[1]) / 100);
      job.updatedAt = Date.now();
    }
  });

  let stderr = '';
  child.stderr.on('data', (chunk) => {
    stderr += chunk.toString();
  });

  child.on('error', (error) => {
    job.status = 'failed';
    job.error = `Could not start yt-dlp: ${error.message}`;
    job.updatedAt = Date.now();
  });

  child.on('close', (code) => {
    if (job.status === 'failed') {
      return;
    }
    if (code === 0 && fs.existsSync(outputPath)) {
      job.status = 'ready';
      job.progress = 1;
    } else {
      job.status = 'failed';
      job.error = stderr.trim().split('\n').pop() ?? `yt-dlp exited with code ${code}`;
      fs.rmSync(partialPath, { force: true });
    }
    job.updatedAt = Date.now();
  });

  return job;
}

function jobResponse(job) {
  return {
    videoId: job.videoId,
    status: job.status,
    progress: job.progress,
    error: job.error,
    fileUrl: job.status === 'ready' ? fileUrlFor(job.videoId) : null,
  };
}

setInterval(() => {
  const cutoff = Date.now() - JOB_TTL_MS;
  for (const [videoId, job] of jobs) {
    if (job.status !== 'processing' && job.updatedAt < cutoff) {
      jobs.delete(videoId);
    }
  }
}, 10 * 60 * 1000).unref();

const app = express();
app.use(express.json());

app.post('/api/downloads', (req, res) => {
  const videoId = typeof req.body?.videoId === 'string' ? req.body.videoId.trim() : '';
  if (!VIDEO_ID_PATTERN.test(videoId)) {
    res.status(400).json({ error: 'Provide a valid 11-character YouTube video id.' });
    return;
  }

  const existing = jobs.get(videoId);
  if (existing && existing.status !== 'failed') {
    res.json(jobResponse(existing));
    return;
  }

  if (fs.existsSync(filePathFor(videoId))) {
    const job = { videoId, status: 'ready', progress: 1, error: null, updatedAt: Date.now() };
    jobs.set(videoId, job);
    res.json(jobResponse(job));
    return;
  }

  res.json(jobResponse(startJob(videoId)));
});

app.get('/api/downloads/:videoId', (req, res) => {
  const job = jobs.get(req.params.videoId);
  if (!job) {
    res.status(404).json({ error: 'Unknown download job.' });
    return;
  }
  res.json(jobResponse(job));
});

app.use('/files', express.static(FILES_DIR));

app.listen(PORT, () => {
  console.log(`Quiet Library download server listening on port ${PORT}`);
  console.log(`Requires yt-dlp and ffmpeg on PATH (yt-dlp: ${YT_DLP}).`);
});

