import * as FileSystem from 'expo-file-system/legacy';

const SERVER_URL = (process.env.EXPO_PUBLIC_DOWNLOAD_SERVER_URL ?? '').trim().replace(/\/+$/, '');
const POLL_INTERVAL_MS = 2_000;
const PREPARE_TIMEOUT_MS = 15 * 60 * 1000;
const DOWNLOADS_DIR = `${FileSystem.documentDirectory}downloads/`;

type ServerJob = {
  videoId: string;
  status: 'processing' | 'ready' | 'failed';
  progress: number;
  error: string | null;
  fileUrl: string | null;
};

export class DownloadServiceError extends Error {}

export function isDownloadServerConfigured(): boolean {
  return SERVER_URL.length > 0;
}

function requireServerUrl(): string {
  if (SERVER_URL.length === 0) {
    throw new DownloadServiceError(
      'Add EXPO_PUBLIC_DOWNLOAD_SERVER_URL to .env to enable downloads.',
    );
  }
  return SERVER_URL;
}

async function fetchJob(input: RequestInfo, init?: RequestInit): Promise<ServerJob> {
  let response: Response;
  try {
    response = await fetch(input, init);
  } catch {
    throw new DownloadServiceError('Could not reach the download server.');
  }
  const body = (await response.json().catch(() => null)) as (ServerJob & { error?: string }) | null;
  if (!response.ok || body === null) {
    throw new DownloadServiceError(body?.error ?? 'The download server returned an error.');
  }
  return body;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function prepareServerFile(
  youtubeId: string,
  onProgress: (progress: number) => void,
): Promise<string> {
  const serverUrl = requireServerUrl();
  let job = await fetchJob(`${serverUrl}/api/downloads`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ videoId: youtubeId }),
  });

  const deadline = Date.now() + PREPARE_TIMEOUT_MS;
  while (job.status === 'processing') {
    onProgress(job.progress);
    if (Date.now() > deadline) {
      throw new DownloadServiceError('The server took too long to prepare this video.');
    }
    await sleep(POLL_INTERVAL_MS);
    job = await fetchJob(`${serverUrl}/api/downloads/${youtubeId}`);
  }

  if (job.status === 'failed' || job.fileUrl === null) {
    throw new DownloadServiceError(job.error ?? 'The server could not prepare this video.');
  }
  onProgress(1);
  return `${serverUrl}${job.fileUrl}`;
}

export async function downloadToDevice(
  fileUrl: string,
  youtubeId: string,
  onProgress: (progress: number) => void,
): Promise<string> {
  await FileSystem.makeDirectoryAsync(DOWNLOADS_DIR, { intermediates: true });
  const destination = `${DOWNLOADS_DIR}${youtubeId}.mp4`;

  const resumable = FileSystem.createDownloadResumable(fileUrl, destination, {}, (progress) => {
    if (progress.totalBytesExpectedToWrite > 0) {
      onProgress(progress.totalBytesWritten / progress.totalBytesExpectedToWrite);
    }
  });

  let result;
  try {
    result = await resumable.downloadAsync();
  } catch {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be transferred to this device.');
  }
  if (result === undefined || result.status < 200 || result.status >= 300) {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be transferred to this device.');
  }
  onProgress(1);
  return result.uri;
}

export async function deleteDeviceFile(fileUri: string | null): Promise<void> {
  if (fileUri) {
    await FileSystem.deleteAsync(fileUri, { idempotent: true }).catch(() => undefined);
  }
}

