import Ionicons from '@expo/vector-icons/Ionicons';
import { StyleSheet, Text, View } from 'react-native';

import { AppButton } from '@/components/AppButton';
import { BottomSheet } from '@/components/BottomSheet';
import { colors, radius, spacing } from '@/constants/theme';
import type { DownloadStatus, SavedVideo } from '@/types';

type OfflineAvailabilityModalProps = {
  video: SavedVideo | null;
  onClose: () => void;
};

const statusCopy: Record<DownloadStatus, { label: string; message: string; icon: 'cloud-outline' | 'time-outline' | 'arrow-down-circle-outline' | 'checkmark-circle-outline' | 'alert-circle-outline' | 'pause-circle-outline' }> = {
  unavailable: {
    label: 'Not available locally',
    message: 'No local copy is recorded for this video.',
    icon: 'cloud-outline',
  },
  queued: {
    label: 'Queued',
    message: 'This video is waiting for its transfer to start.',
    icon: 'time-outline',
  },
  downloading: {
    label: 'Transferring',
    message: 'The local copy is currently being prepared.',
    icon: 'arrow-down-circle-outline',
  },
  downloaded: {
    label: 'Available locally',
    message: 'A completed local copy is recorded on this device.',
    icon: 'checkmark-circle-outline',
  },
  failed: {
    label: 'Transfer failed',
    message: 'The last transfer did not finish successfully.',
    icon: 'alert-circle-outline',
  },
  interrupted: {
    label: 'Transfer interrupted',
    message: 'The transfer stopped before it completed.',
    icon: 'pause-circle-outline',
  },
};

export function OfflineAvailabilityModal({ video, onClose }: OfflineAvailabilityModalProps) {
  const status = video ? statusCopy[video.downloadStatus] : statusCopy.unavailable;
  const progress = video?.downloadStatus === 'downloading'
    ? Math.max(0, Math.min(100, Math.round(video.downloadProgress * 100)))
    : null;

  return (
    <BottomSheet onClose={onClose} visible={video !== null}>
      <Text style={styles.eyebrow}>OFFLINE AVAILABILITY</Text>
      <Text numberOfLines={2} style={styles.title}>{video?.title}</Text>
      <View style={styles.statusCard}>
        <Ionicons color={colors.accent} name={status.icon} size={28} />
        <View style={styles.statusCopy}>
          <Text style={styles.statusLabel}>{status.label}</Text>
          <Text style={styles.message}>{status.message}</Text>
          {progress !== null ? <Text style={styles.progress}>{progress}% complete</Text> : null}
        </View>
      </View>
      <AppButton label="Close" onPress={onClose} style={styles.close} variant="secondary" />
    </BottomSheet>
  );
}

const styles = StyleSheet.create({
  eyebrow: {
    color: colors.accent,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
    letterSpacing: 1.1,
  },
  title: {
    color: colors.ink,
    fontFamily: 'serif',
    fontSize: 21,
    fontWeight: '600',
    lineHeight: 27,
    marginTop: spacing.xs,
  },
  statusCard: {
    flexDirection: 'row',
    gap: spacing.md,
    marginTop: spacing.lg,
    padding: spacing.lg,
    borderRadius: radius.md,
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: colors.border,
    backgroundColor: colors.surface,
  },
  statusCopy: { flex: 1 },
  statusLabel: { color: colors.ink, fontFamily: 'sans-serif-medium', fontSize: 15 },
  message: { color: colors.inkMuted, fontSize: 13, lineHeight: 19, marginTop: spacing.xs },
  progress: { color: colors.accent, fontSize: 12, marginTop: spacing.sm },
  close: { marginTop: spacing.lg },
});

