import * as FileSystem from 'expo-file-system/legacy';

const INNERTUBE_PLAYER_URL = 'https://www.youtube.com/youtubei/v1/player?prettyPrint=false';
const ANDROID_CLIENT_VERSION = '19.44.38';
const ANDROID_USER_AGENT = `com.google.android.youtube/${ANDROID_CLIENT_VERSION} (Linux; U; Android 14) gzip`;
const REQUEST_TIMEOUT_MS = 20_000;
const DOWNLOADS_DIR = `${FileSystem.documentDirectory}downloads/`;

type PlayerFormat = {
  itag: number;
  url?: string;
  mimeType?: string;
  height?: number;
  bitrate?: number;
};

type PlayerResponse = {
  playabilityStatus?: { status?: string; reason?: string };
  streamingData?: { formats?: PlayerFormat[] };
};

export class DownloadServiceError extends Error {}

export async function resolveStreamUrl(youtubeId: string): Promise<string> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  let data: PlayerResponse;
  try {
    const response = await fetch(INNERTUBE_PLAYER_URL, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': ANDROID_USER_AGENT,
      },
      body: JSON.stringify({
        videoId: youtubeId,
        context: {
          client: {
            clientName: 'ANDROID',
            clientVersion: ANDROID_CLIENT_VERSION,
            androidSdkVersion: 34,
            hl: 'en',
            gl: 'US',
          },
        },
      }),
    });
    if (!response.ok) {
      throw new DownloadServiceError(`YouTube returned an error (${response.status}).`);
    }
    data = (await response.json()) as PlayerResponse;
  } catch (error) {
    if (error instanceof DownloadServiceError) {
      throw error;
    }
    throw new DownloadServiceError('Could not reach YouTube. Check your connection and try again.');
  } finally {
    clearTimeout(timeout);
  }

  const playability = data.playabilityStatus?.status ?? 'ERROR';
  if (playability !== 'OK') {
    throw new DownloadServiceError(
      data.playabilityStatus?.reason ?? 'This video cannot be downloaded.',
    );
  }

  const candidates = (data.streamingData?.formats ?? []).filter(
    (format): format is PlayerFormat & { url: string } =>
      typeof format.url === 'string' && (format.mimeType?.startsWith('video/mp4') ?? false),
  );
  if (candidates.length === 0) {
    throw new DownloadServiceError('No downloadable MP4 stream is available for this video.');
  }

  candidates.sort((a, b) => (b.height ?? 0) - (a.height ?? 0) || (b.bitrate ?? 0) - (a.bitrate ?? 0));
  return candidates[0].url;
}

export async function downloadToDevice(
  streamUrl: string,
  youtubeId: string,
  onProgress: (progress: number) => void,
): Promise<string> {
  await FileSystem.makeDirectoryAsync(DOWNLOADS_DIR, { intermediates: true });
  const destination = `${DOWNLOADS_DIR}${youtubeId}.mp4`;

  const resumable = FileSystem.createDownloadResumable(
    streamUrl,
    destination,
    { headers: { 'User-Agent': ANDROID_USER_AGENT } },
    (progress) => {
      if (progress.totalBytesExpectedToWrite > 0) {
        onProgress(progress.totalBytesWritten / progress.totalBytesExpectedToWrite);
      }
    },
  );

  let result;
  try {
    result = await resumable.downloadAsync();
  } catch {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be saved to this device.');
