  candidates.sort((a, b) => (b.height ?? 0) - (a.height ?? 0) || (b.bitrate ?? 0) - (a.bitrate ?? 0));
  return candidates[0]!.url;
}

export async function downloadToDevice(
  streamUrl: string,
  youtubeId: string,
  onProgress: (progress: number) => void,
): Promise<string> {
  await FileSystem.makeDirectoryAsync(DOWNLOADS_DIR, { intermediates: true });
  const destination = `${DOWNLOADS_DIR}${youtubeId}.mp4`;

  const resumable = FileSystem.createDownloadResumable(
    streamUrl,
    destination,
    { headers: { 'User-Agent': USER_AGENT } },
    (progress) => {
      if (progress.totalBytesExpectedToWrite > 0) {
        onProgress(progress.totalBytesWritten / progress.totalBytesExpectedToWrite);
      }
    },
  );

  let result;
  try {
    result = await resumable.downloadAsync();
  } catch {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be saved to this device.');
  }
  if (result === undefined || result.status < 200 || result.status >= 300) {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be saved to this device.');
  }
  onProgress(1);
  return result.uri;
}

export async function deleteDeviceFile(fileUri: string | null): Promise<void> {
  if (fileUri) {
    await FileSystem.deleteAsync(fileUri, { idempotent: true }).catch(() => undefined);
  }
}

