import type { ExpoConfig } from 'expo/config';

const config: ExpoConfig = {
  name: 'Quiet Library',
  slug: 'quiet-library',
  version: '1.2.0',
  icon: './assets/icon.png',
  orientation: 'portrait',
  userInterfaceStyle: 'dark',
  backgroundColor: '#0D0F0D',
  scheme: 'quietlibrary',
  android: {
    package: 'com.omen6.quietlibrary',
    versionCode: 3,
    softwareKeyboardLayoutMode: 'resize',
    adaptiveIcon: {
      backgroundColor: '#0D0F0D',
      foregroundImage: './assets/adaptive-icon.png',
    },
    intentFilters: [
      {
        action: 'VIEW',
        category: ['BROWSABLE', 'DEFAULT'],
        data: [
          { scheme: 'https', host: 'youtu.be' },
          { scheme: 'http', host: 'youtu.be' },
        ],
      },
      {
        action: 'VIEW',
        category: ['BROWSABLE', 'DEFAULT'],
        data: [
          { scheme: 'https' },
          { scheme: 'http' },
          { scheme: 'https', host: 'www.youtube.com', pathPrefix: '/watch' },
          { scheme: 'https', host: 'youtube.com', pathPrefix: '/watch' },
          { scheme: 'https', host: 'm.youtube.com', pathPrefix: '/watch' },
        ],
      },
      {
        action: 'VIEW',
        category: ['BROWSABLE', 'DEFAULT'],
        data: [
          { scheme: 'https' },
          { scheme: 'http' },
          { scheme: 'https', host: 'www.youtube.com', pathPrefix: '/shorts' },
          { scheme: 'https', host: 'youtube.com', pathPrefix: '/shorts' },
          { scheme: 'https', host: 'm.youtube.com', pathPrefix: '/shorts' },
        ],
      },
      {
        action: 'VIEW',
        category: ['BROWSABLE', 'DEFAULT'],
        data: [
          { scheme: 'https' },
          { scheme: 'http' },
          { scheme: 'https', host: 'www.youtube.com', pathPrefix: '/live' },
          { scheme: 'https', host: 'youtube.com', pathPrefix: '/live' },
          { scheme: 'https', host: 'm.youtube.com', pathPrefix: '/live' },
        ],
      },
    ],
  },
  plugins: [
    'expo-sqlite',
    'expo-font',
    'expo-video',
    [
      'expo-splash-screen',
      {
        backgroundColor: '#0D0F0D',
        image: './assets/icon.png',
        imageWidth: 160,
        resizeMode: 'contain',
      },
    ],
  ],
  extra: {
    youtubeApiKey: process.env.EXPO_PUBLIC_YOUTUBE_API_KEY ?? '',
  },
};

export default config;

import * as FileSystem from 'expo-file-system/legacy';

import { resolveStream } from '../../modules/newpipe';

// Matches the User-Agent the native NewPipe Extractor module sends, so the
// googlevideo URL it resolves stays valid for the file transfer.
const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; rv:91.0) Gecko/20100101 Firefox/91.0';
const DOWNLOADS_DIR = `${FileSystem.documentDirectory}downloads/`;

export class DownloadServiceError extends Error {}

export async function resolveStreamUrl(youtubeId: string): Promise<string> {
  try {
    const stream = await resolveStream(youtubeId);
    return stream.url;
  } catch (error) {
    throw new DownloadServiceError(
      error instanceof Error && error.message.length > 0
        ? error.message
        : 'This video cannot be downloaded.',
    );
  }
}

export async function downloadToDevice(
  streamUrl: string,
  youtubeId: string,
  onProgress: (progress: number) => void,
): Promise<string> {
  await FileSystem.makeDirectoryAsync(DOWNLOADS_DIR, { intermediates: true });
  const destination = `${DOWNLOADS_DIR}${youtubeId}.mp4`;

  const resumable = FileSystem.createDownloadResumable(
    streamUrl,
    destination,
    { headers: { 'User-Agent': USER_AGENT } },
    (progress) => {
      if (progress.totalBytesExpectedToWrite > 0) {
        onProgress(progress.totalBytesWritten / progress.totalBytesExpectedToWrite);
      }
    },
  );

  let result;
  try {
    result = await resumable.downloadAsync();
  } catch {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be saved to this device.');
  }
  if (result === undefined || result.status < 200 || result.status >= 300) {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The video file could not be saved to this device.');
  }
  onProgress(1);
  return result.uri;
}

export async function deleteDeviceFile(fileUri: string | null): Promise<void> {
  if (fileUri) {
    await FileSystem.deleteAsync(fileUri, { idempotent: true }).catch(() => undefined);
  }
}

import { requireNativeModule } from 'expo-modules-core';

export type ResolvedStream = {
  url: string;
  resolution: string;
  title: string;
};

type NewPipeNativeModule = {
  resolveStream: (videoId: string) => Promise<ResolvedStream>;
};

const NewPipe = requireNativeModule<NewPipeNativeModule>('NewPipe');

export function resolveStream(videoId: string): Promise<ResolvedStream> {
  return NewPipe.resolveStream(videoId);
}

