import Ionicons from '@expo/vector-icons/Ionicons';
import { useMemo, useState } from 'react';
import {
  Alert,
  FlatList,
  Pressable,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { AddVideoModal } from '@/components/AddVideoModal';
import { AppButton } from '@/components/AppButton';
import { EmptyState } from '@/components/EmptyState';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { IconButton } from '@/components/IconButton';
import { OfflineAvailabilityModal } from '@/components/OfflineAvailabilityModal';
import { VideoActionsModal } from '@/components/VideoActionsModal';
import { VideoCard } from '@/components/VideoCard';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { SavedVideo } from '@/types';

export function LibraryView() {
  const {
    videos,
    folders,
    isLoading,
    addVideo,
    deleteVideo,
    deleteVideos,
    moveVideo,
    moveVideos,
  } = useLibrary();
  const { push } = useAppNavigation();
  const [selectedFolderId, setSelectedFolderId] = useState<
    number | null | 'unfiled' | 'downloaded'
  >(null);
  const [addVisible, setAddVisible] = useState(false);
  const [actionVideo, setActionVideo] = useState<SavedVideo | null>(null);
  const [moveVideoTarget, setMoveVideoTarget] = useState<SavedVideo | null>(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedVideoIds, setSelectedVideoIds] = useState<Set<string>>(() => new Set());
  const [bulkMoveVisible, setBulkMoveVisible] = useState(false);
  const [availabilityVideo, setAvailabilityVideo] = useState<SavedVideo | null>(null);

  const visibleVideos = useMemo(() => {
    if (selectedFolderId === null) {
      return videos;
    }
    if (selectedFolderId === 'unfiled') {
      return videos.filter((video) => video.folderId === null);
    }
    if (selectedFolderId === 'downloaded') {
      return videos.filter(
        (video) => video.downloadStatus === 'downloaded' && video.downloadedFileUri !== null,
      );
    }
    return videos.filter((video) => video.folderId === selectedFolderId);
  }, [selectedFolderId, videos]);

  const endSelection = () => {
    setSelectionMode(false);
    setSelectedVideoIds(new Set());
    setBulkMoveVisible(false);
  };

  const toggleSelected = (youtubeId: string) => {
    setSelectedVideoIds((current) => {
      const next = new Set(current);
      if (next.has(youtubeId)) {
        next.delete(youtubeId);
      } else {
        next.add(youtubeId);
      }
      return next;
    });
  };

  const enterSelection = (youtubeId?: string) => {
    setSelectionMode(true);
    if (youtubeId) {
      setSelectedVideoIds((current) => new Set(current).add(youtubeId));
    }
  };

  const toggleSelectAll = () => {
    const visibleIds = visibleVideos.map((video) => video.youtubeId);
    const allVisibleSelected = visibleIds.length > 0 && visibleIds.every((id) => selectedVideoIds.has(id));
    setSelectedVideoIds((current) => {
      const next = new Set(current);
      for (const id of visibleIds) {
        if (allVisibleSelected) {
          next.delete(id);
        } else {
          next.add(id);
        }
      }
      return next;
    });
  };

  const deleteSelectedVideo = (video: SavedVideo) => {
    setActionVideo(null);
    Alert.alert(
      'Delete saved video?',
      'This removes the entry from Quiet Library. It does not affect YouTube.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => void deleteVideo(video.youtubeId),
        },
      ],
    );
  };

  const deleteSelection = () => {
    const ids = [...selectedVideoIds];
    if (ids.length === 0) {
      return;
    }
    Alert.alert(
      `Delete ${ids.length} saved ${ids.length === 1 ? 'video' : 'videos'}?`,
      'This removes the selected entries from Quiet Library. It does not affect YouTube.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => {
            void deleteVideos(ids).then(endSelection);
          },
        },
      ],
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.toolbar}>
        <View>
          <Text style={styles.eyebrow}>{selectionMode ? 'SELECTED' : 'YOUR VIDEOS'}</Text>
          <Text style={styles.count}>
            {selectionMode
              ? `${selectedVideoIds.size} ${selectedVideoIds.size === 1 ? 'video' : 'videos'}`
              : `${videos.length} ${videos.length === 1 ? 'video' : 'videos'}`}
          </Text>
        </View>
        {selectionMode ? (
          <View style={styles.selectionActions}>
            <SelectionAction
              disabled={visibleVideos.length === 0}
              icon="checkmark-done-outline"
              label="Select all"
              onPress={toggleSelectAll}
            />
            <SelectionAction
              disabled={selectedVideoIds.size === 0}
              icon="folder-outline"
              label="Move selected"
              onPress={() => setBulkMoveVisible(true)}
            />
            <SelectionAction
              danger
              disabled={selectedVideoIds.size === 0}
              icon="trash-outline"
              label="Delete selected"
              onPress={deleteSelection}
            />
            <IconButton icon="close" label="Cancel selection" onPress={endSelection} />
          </View>
        ) : (
          <View style={styles.defaultActions}>
            {videos.length > 0 ? (
              <IconButton filled icon="checkmark-circle-outline" label="Select videos" onPress={() => enterSelection()} />
            ) : null}
            <AppButton icon="add" label="Add video" onPress={() => setAddVisible(true)} />
          </View>
        )}
      </View>

      {folders.length > 0 || videos.some((video) => video.folderId === null) ? (
        <FlatList
          contentContainerStyle={styles.filters}
          data={[
            { id: null, name: 'All' },
            { id: 'downloaded' as const, name: 'Downloaded' },
            { id: 'unfiled' as const, name: 'Unfiled' },
            ...folders.map((folder) => ({ id: folder.id, name: folder.name })),
          ]}
          horizontal
          keyExtractor={(item) => String(item.id)}
          renderItem={({ item }) => (
            <Pressable
              accessibilityRole="button"
              onPress={() => setSelectedFolderId(item.id)}
              style={({ pressed }) => [
                styles.filter,
                selectedFolderId === item.id && styles.filterSelected,
                pressed && styles.pressed,
              ]}
            >
              <Text
                style={[
                  styles.filterLabel,
                  selectedFolderId === item.id && styles.filterLabelSelected,
                ]}
              >
                {item.name}
              </Text>
            </Pressable>
          )}
          showsHorizontalScrollIndicator={false}
          style={styles.filtersList}
        />
      ) : null}

      <FlatList
        contentContainerStyle={visibleVideos.length === 0 ? styles.emptyList : styles.list}
        data={visibleVideos}
        keyExtractor={(item) => item.youtubeId}
        ListEmptyComponent={
          !isLoading ? (
            <EmptyState
              action={
                <AppButton icon="add" label="Add your first video" onPress={() => setAddVisible(true)} />
              }
              icon="leaf-outline"
              message={
                selectedFolderId === null
                  ? 'Paste a video link to build a library without opening YouTube’s feed.'
                  : selectedFolderId === 'downloaded'
                    ? 'Downloaded videos will appear here for quick local playback.'
                    : 'There are no saved videos in this view.'
              }
              title={selectedFolderId === null
                ? 'A quieter place to watch'
                : selectedFolderId === 'downloaded'
                  ? 'No downloaded videos'
                  : 'Nothing here yet'}
            />
          ) : null
        }
        renderItem={({ item }) => (
          <VideoCard
            downloaded={
              item.downloadStatus === 'downloaded' && item.downloadedFileUri !== null
            }
            folderName={item.folderName}
            onLongPress={() => enterSelection(item.youtubeId)}
            onMore={() => setActionVideo(item)}
            onPress={() => push({ name: 'player', video: item })}
            onToggleSelect={() => toggleSelected(item.youtubeId)}
            selected={selectedVideoIds.has(item.youtubeId)}
            selecting={selectionMode}
            video={item}
          />
        )}
        removeClippedSubviews
      />

      <AddVideoModal
        folders={folders}
        onAdd={async (url, folderId) => {
          await addVideo(url, folderId);
        }}
        onClose={() => setAddVisible(false)}
        visible={addVisible}
      />
      <VideoActionsModal
        onClose={() => setActionVideo(null)}
        onDelete={() => {
          if (actionVideo) {
            deleteSelectedVideo(actionVideo);
          }
        }}
        onMove={() => {
          setMoveVideoTarget(actionVideo);
          setActionVideo(null);
        }}
        onOfflineInfo={() => {
          setAvailabilityVideo(actionVideo);
          setActionVideo(null);
        }}
        video={actionVideo}
      />
      <FolderPickerModal
        currentFolderId={moveVideoTarget?.folderId ?? null}
        folders={folders}
        onClose={() => setMoveVideoTarget(null)}
        onSelect={(folderId) => {
          if (moveVideoTarget) {
            void moveVideo(moveVideoTarget.youtubeId, folderId);
          }
          setMoveVideoTarget(null);
        }}
        visible={moveVideoTarget !== null}
      />
      <FolderPickerModal
        currentFolderId={null}
        folders={folders}
        onClose={() => setBulkMoveVisible(false)}
        onSelect={(folderId) => {
          const ids = [...selectedVideoIds];
          void moveVideos(ids, folderId).then(endSelection);
        }}
        title={`Move ${selectedVideoIds.size} ${selectedVideoIds.size === 1 ? 'video' : 'videos'}`}
        visible={bulkMoveVisible}
      />
      <OfflineAvailabilityModal
        onClose={() => setAvailabilityVideo(null)}
        video={availabilityVideo}
      />
    </View>
  );
}

function SelectionAction({
  icon,
  label,
  onPress,
  disabled = false,
  danger = false,
}: {
  icon: 'checkmark-done-outline' | 'folder-outline' | 'trash-outline';
  label: string;
  onPress: () => void;
  disabled?: boolean;
  danger?: boolean;
}) {
  return (
    <Pressable
      accessibilityLabel={label}
      accessibilityRole="button"
      disabled={disabled}
      hitSlop={6}
      onPress={onPress}
      style={({ pressed }) => [
        styles.selectionAction,
        pressed && styles.pressed,
        disabled && styles.disabled,
      ]}
    >
      <Ionicons color={danger ? colors.danger : colors.ink} name={icon} size={20} />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  toolbar: {
    minHeight: 70,
    paddingHorizontal: spacing.lg,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: spacing.md,
  },
  defaultActions: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.xs,
  },
  selectionActions: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 2,
  },
  selectionAction: {
    width: 38,
    height: 42,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: radius.round,
  },
  disabled: { opacity: 0.32 },
  eyebrow: {
    color: colors.inkMuted,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
    letterSpacing: 1.1,
  },
  count: {
    color: colors.ink,
    fontSize: 14,
    marginTop: 3,
  },
  filters: {
    paddingHorizontal: spacing.lg,
    paddingBottom: spacing.md,
    gap: spacing.sm,
  },
  filtersList: {
    flexGrow: 0,
    maxHeight: 50,
  },
  filter: {
    height: 34,
    justifyContent: 'center',
    paddingHorizontal: spacing.md,
    borderRadius: radius.round,
    borderWidth: 1,
    borderColor: colors.border,
    backgroundColor: colors.surface,
  },
  filterSelected: {
    backgroundColor: colors.accentSoft,
    borderColor: colors.accent,
  },
  filterLabel: {
    color: colors.inkMuted,
    fontSize: 12,
  },
  filterLabelSelected: {
    color: colors.ink,
    fontFamily: 'sans-serif-medium',
  },
  pressed: {
    opacity: 0.64,
  },
  list: {
    paddingHorizontal: spacing.lg,
    paddingBottom: spacing.xxl,
    gap: spacing.md,
  },
  emptyList: {
    flexGrow: 1,
    justifyContent: 'center',
  },
});

