import Ionicons from '@expo/vector-icons/Ionicons';
import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { HARDCODED_CHANNELS } from '@/config/channels';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';

export function ChannelsView() {
  const { channelVideos } = useLibrary();
  const { push } = useAppNavigation();

  return (
    <View style={styles.container}>
      <View style={styles.intro}>
        <Text style={styles.eyebrow}>CURATED CHANNELS</Text>
        <Text style={styles.message}>Open a channel to browse its videos and playlists.</Text>
      </View>
      <FlatList
        contentContainerStyle={styles.list}
        data={HARDCODED_CHANNELS}
        keyExtractor={(channel) => channel.channelHandle}
        renderItem={({ item }) => {
          const cachedCount = channelVideos.filter(
            (video) => video.channelHandle === item.channelHandle,
          ).length;
          return (
            <Pressable
              accessibilityLabel={`Open ${item.name}`}
              accessibilityRole="button"
