import Ionicons from '@expo/vector-icons/Ionicons';
import { Image } from 'expo-image';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { colors, radius, spacing } from '@/constants/theme';
import type { PlayableVideo } from '@/types';
import { formatDuration, formatPublishedDate } from '@/utils/format';

type VideoCardProps = {
  video: PlayableVideo;
  folderName?: string | null;
  onPress: () => void;
  onMore?: () => void;
  onSave?: () => void;
  saved?: boolean;
  selecting?: boolean;
  selected?: boolean;
  onToggleSelect?: () => void;
  onLongPress?: () => void;
  downloaded?: boolean;
};

export function VideoCard({
  video,
  folderName,
  onPress,
  onMore,
  onSave,
  saved = false,
  selecting = false,
  selected = false,
  onToggleSelect,
  onLongPress,
  downloaded = false,
}: VideoCardProps) {
  const duration = formatDuration(video.durationSeconds);
  const publicationDate = formatPublishedDate(video.publishedAt);

  return (
    <Pressable
      accessibilityLabel={selecting
        ? `${selected ? 'Deselect' : 'Select'} ${video.title}`
        : `Play ${downloaded ? 'downloaded ' : ''}${video.title}`}
      accessibilityRole="button"
      accessibilityState={selecting ? { selected } : undefined}
      onLongPress={onLongPress}
      onPress={selecting && onToggleSelect ? onToggleSelect : onPress}
      style={({ pressed }) => [
        styles.card,
        selected && styles.cardSelected,
        pressed && styles.pressed,
      ]}
    >
      <View style={styles.thumbnailWrap}>
        <Image
          cachePolicy="memory-disk"
          contentFit="cover"
          recyclingKey={video.youtubeId}
          source={{ uri: video.thumbnailUrl }}
          style={styles.thumbnail}
          transition={0}
        />
        <View style={[styles.playBadge, selecting && styles.selectionBadge]}>
          <Ionicons
            color={selecting ? colors.black : colors.white}
            name={selecting ? (selected ? 'checkmark' : 'ellipse-outline') : 'play'}
            size={selecting ? 17 : 13}
          />
        </View>
        {duration ? <Text style={styles.duration}>{duration}</Text> : null}
      </View>
      <View style={styles.body}>
        <Text numberOfLines={2} style={styles.title}>
          {video.title}
        </Text>
        <Text numberOfLines={1} style={styles.channel}>
          {video.channelName}
        </Text>
        {folderName || publicationDate || downloaded ? (
          <View style={styles.detailRow}>
            {folderName || publicationDate ? (
              <Text numberOfLines={1} style={styles.detail}>
                {folderName ?? publicationDate}
              </Text>
            ) : null}
            {downloaded ? (
              <View style={styles.downloadedBadge}>
                <Ionicons color={colors.accent} name="arrow-down-circle" size={13} />
                <Text style={styles.downloadedLabel}>Downloaded</Text>
              </View>
            ) : null}
          </View>
        ) : null}
      </View>
      {!selecting && onMore ? (
        <Pressable
          accessibilityLabel={`More actions for ${video.title}`}
          hitSlop={8}
          onPress={(event) => {
            event.stopPropagation();
            onMore();
          }}
          style={styles.action}
        >
          <Ionicons color={colors.inkMuted} name="ellipsis-vertical" size={20} />
        </Pressable>
      ) : onSave ? (
        <Pressable
          accessibilityLabel={saved ? 'Already saved' : `Save ${video.title}`}
          disabled={saved}
          hitSlop={8}
          onPress={(event) => {
            event.stopPropagation();
            onSave();
          }}
          style={styles.action}
        >
          <Ionicons
            color={saved ? colors.accent : colors.inkMuted}
            name={saved ? 'checkmark-circle' : 'add-circle-outline'}
            size={22}
          />
        </Pressable>
      ) : null}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  card: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 94,
    backgroundColor: colors.surface,
    borderRadius: radius.md,
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: colors.border,
    padding: spacing.sm,
    gap: spacing.md,
  },
  pressed: {
    opacity: 0.72,
  },
  cardSelected: {
    borderColor: colors.accent,
    borderWidth: 1.5,
    backgroundColor: colors.accentSoft,
  },
  thumbnailWrap: {
    width: 126,
    height: 72,
    borderRadius: radius.sm,
    overflow: 'hidden',
    backgroundColor: colors.surfaceMuted,
  },
  thumbnail: {
    width: '100%',
    height: '100%',
  },
  playBadge: {
    position: 'absolute',
    left: spacing.sm,
    top: spacing.sm,
    width: 28,
    height: 28,
    borderRadius: radius.round,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(8, 9, 8, 0.78)',
  },
  selectionBadge: {
    backgroundColor: colors.accent,
  },
  duration: {
    position: 'absolute',
    right: 5,
    bottom: 5,
    color: colors.white,
    backgroundColor: 'rgba(8, 9, 8, 0.82)',
    borderRadius: 4,
    overflow: 'hidden',
    paddingHorizontal: 5,
    paddingVertical: 2,
    fontSize: 11,
    fontFamily: 'sans-serif-medium',
  },
  body: {
    flex: 1,
    alignSelf: 'stretch',
    justifyContent: 'center',
    minWidth: 0,
  },
  title: {
    color: colors.ink,
    fontFamily: 'sans-serif-medium',
    fontSize: 14,
    lineHeight: 19,
  },
  channel: {
    color: colors.inkMuted,
    fontSize: 12,
    lineHeight: 17,
    marginTop: 3,
  },
  detail: {
    flex: 1,
    color: colors.accent,
    fontSize: 11,
    lineHeight: 15,
  },
  detailRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    minWidth: 0,
    marginTop: 1,
  },
  downloadedBadge: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 3,
    flexShrink: 0,
  },
  downloadedLabel: {
    color: colors.accent,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
  },
  action: {
    width: 30,
    minHeight: 48,
    alignItems: 'center',
    justifyContent: 'center',
  },
});

