import Ionicons from '@expo/vector-icons/Ionicons';
import { Image } from 'expo-image';
import { useEffect, useState } from 'react';
import { Alert, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { AppButton } from '@/components/AppButton';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { LocalVideoPlayer } from '@/components/LocalVideoPlayer';
import { ScreenHeader } from '@/components/ScreenHeader';
import { YouTubePlayer } from '@/components/YouTubePlayer';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import { fetchVideoMetadata } from '@/services/youtube';
import type { PlayableVideo } from '@/types';
import { formatDuration, formatPublishedDate } from '@/utils/format';

type PlayerScreenProps = { video: PlayableVideo };

export function PlayerScreen({ video }: PlayerScreenProps) {
  const { goBack } = useAppNavigation();
  const { folders, saveVideo, videos } = useLibrary();
  const [playerError, setPlayerError] = useState<string | null>(null);
  const [ended, setEnded] = useState(false);
  const [playerSession, setPlayerSession] = useState(0);
  const [descriptionExpanded, setDescriptionExpanded] = useState(false);
  const [description, setDescription] = useState(video.description);
  const [saveVisible, setSaveVisible] = useState(false);
  const savedVideo = videos.find((entry) => entry.youtubeId === video.youtubeId);
  const saved = savedVideo !== undefined;
  const localFileUri =
    savedVideo?.downloadStatus === 'downloaded' && savedVideo.downloadedFileUri
      ? savedVideo.downloadedFileUri
      : null;
  const isDownloaded = localFileUri !== null;
  const duration = formatDuration(video.durationSeconds);
  const published = formatPublishedDate(video.publishedAt);

  useEffect(() => {
    if (description || isDownloaded) {
      return;
    }
    let active = true;
    void fetchVideoMetadata(
      video.youtubeId,
      process.env.EXPO_PUBLIC_YOUTUBE_API_KEY?.trim() ?? '',
    ).then((metadata) => {
      if (active) {
        setDescription(metadata.description);
      }
    }).catch(() => undefined);
    return () => {
      active = false;
    };
  }, [description, isDownloaded, video.youtubeId]);

  useEffect(() => {
    setPlayerError(null);
  }, [localFileUri]);

  const replay = () => {
    setEnded(false);
    setPlayerError(null);
    setPlayerSession((session) => session + 1);
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        onBack={goBack}
        subtitle={isDownloaded ? 'Local playback' : 'Focused playback'}
        title="Now playing"
      />
      <ScrollView contentContainerStyle={styles.content}>
        {playerError ? (
          <View style={styles.errorPanel}>
            <Ionicons color={colors.danger} name="alert-circle-outline" size={28} />
            <Text style={styles.errorTitle}>
              {isDownloaded ? 'Local playback unavailable' : 'Playback unavailable'}
            </Text>
            <Text style={styles.errorMessage}>{playerError}</Text>
          </View>
        ) : isDownloaded ? (
          <LocalVideoPlayer onError={setPlayerError} uri={localFileUri} />
        ) : ended ? (
          <View style={styles.endedPanel}>
            <Image contentFit="cover" source={{ uri: video.thumbnailUrl }} style={styles.endedImage} />
            <View style={styles.endedShade} />
            <Pressable
              accessibilityLabel="Replay video"
              accessibilityRole="button"
              onPress={replay}
              style={({ pressed }) => [styles.replay, pressed && styles.pressed]}
            >
              <Ionicons color={colors.black} name="refresh" size={22} />
              <Text style={styles.replayText}>Replay</Text>
            </Pressable>
          </View>
        ) : (
          <YouTubePlayer
            key={playerSession}
            onEnded={() => setEnded(true)}
            onError={setPlayerError}
            youtubeId={video.youtubeId}
          />
        )}
        <View style={styles.details}>
          <Text style={styles.attribution}>
            {isDownloaded ? 'LOCAL PLAYBACK' : 'YOUTUBE PLAYBACK'}
          </Text>
          <Text style={styles.title}>{video.title}</Text>
          <Text style={styles.channel}>{video.channelName}</Text>
          {duration || published ? (
            <Text style={styles.metadata}>{[duration, published].filter(Boolean).join('  ·  ')}</Text>
          ) : null}
          <AppButton
            disabled={saved}
            icon={saved ? 'checkmark-circle' : 'bookmark-outline'}
            label={saved ? 'Saved to library' : 'Save video'}
            onPress={() => setSaveVisible(true)}
            style={styles.saveButton}
            variant={saved ? 'secondary' : 'primary'}
          />
          {description ? (
            <View style={styles.descriptionBlock}>
              <Text style={styles.descriptionLabel}>DESCRIPTION</Text>
              <Text
                numberOfLines={descriptionExpanded ? undefined : 5}
                style={styles.description}
              >
                {description}
              </Text>
              <Pressable
                accessibilityRole="button"
                onPress={() => setDescriptionExpanded((expanded) => !expanded)}
                style={({ pressed }) => pressed && styles.pressed}
              >
                <Text style={styles.more}>{descriptionExpanded ? 'Show less' : 'Show more'}</Text>
              </Pressable>
            </View>
          ) : null}
        </View>
      </ScrollView>
      <FolderPickerModal
        currentFolderId={null}
        folders={folders}
        onClose={() => setSaveVisible(false)}
        onSelect={(folderId) => {
          setSaveVisible(false);
          void saveVideo({ ...video, description }, folderId).catch((error: unknown) => {
            Alert.alert(
              'Could not save video',
              error instanceof Error ? error.message : 'Try again.',
            );
          });
        }}
        title="Save to folder"
        visible={saveVisible}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: colors.background },
  content: { paddingBottom: spacing.xxl },
  errorPanel: {
    minHeight: 240,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: spacing.xl,
  },
  errorTitle: { color: colors.ink, fontSize: 18, marginTop: spacing.md },
  errorMessage: {
    color: colors.inkMuted,
    fontSize: 13,
    lineHeight: 19,
    marginTop: spacing.sm,
    textAlign: 'center',
  },
  endedPanel: {
    width: '100%',
    aspectRatio: 16 / 9,
    minHeight: 200,
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
    backgroundColor: colors.black,
  },
  endedImage: { position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 },
  endedShade: {
    position: 'absolute',
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
    backgroundColor: 'rgba(5, 6, 5, 0.62)',
  },
  replay: {
    minHeight: 46,
    paddingHorizontal: spacing.lg,
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    borderRadius: radius.round,
    backgroundColor: colors.accent,
  },
  replayText: { color: colors.black, fontFamily: 'sans-serif-medium', fontSize: 14 },
  details: { paddingHorizontal: spacing.xl, paddingTop: spacing.xl },
  attribution: {
    color: colors.accent,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
    letterSpacing: 1.1,
  },
  title: {
    color: colors.ink,
    fontFamily: 'serif',
    fontSize: 24,
    lineHeight: 31,
    fontWeight: '600',
    marginTop: spacing.sm,
  },
  channel: { color: colors.ink, fontSize: 14, marginTop: spacing.md },
  metadata: { color: colors.inkMuted, fontSize: 12, marginTop: spacing.xs },
  saveButton: { alignSelf: 'flex-start', marginTop: spacing.lg },
  descriptionBlock: {
    marginTop: spacing.xl,
    paddingTop: spacing.lg,
    borderTopColor: colors.border,
    borderTopWidth: StyleSheet.hairlineWidth,
  },
  descriptionLabel: {
    color: colors.accent,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
    letterSpacing: 1,
  },
  description: {
    color: colors.inkMuted,
    fontSize: 13,
    lineHeight: 20,
    marginTop: spacing.sm,
  },
  more: { color: colors.accent, fontFamily: 'sans-serif-medium', fontSize: 12, marginTop: spacing.sm },
  pressed: { opacity: 0.64 },
});

