1	import type { HardcodedChannel } from '@/config/channels';
2	import type {
3	  ChannelPlaylist,
4	  ChannelVideo,
5	  PageResult,
6	  PlayableVideo,
7	} from '@/types';
8	
9	const YOUTUBE_API_BASE = 'https://www.googleapis.com/youtube/v3';
10	const OEMBED_ENDPOINT = 'https://www.youtube.com/oembed';
11	const VIDEO_ID_PATTERN = /^[A-Za-z0-9_-]{11}$/;
12	const REQUEST_TIMEOUT_MS = 15_000;
13	const PAGE_SIZE = '20';
14	
15	type OEmbedResponse = {
16	  title: string;
17	  author_name: string;
18	  thumbnail_url: string;
19	};
20	
21	type ApiThumbnail = { url: string };
22	type ApiThumbnails = {
23	  maxres?: ApiThumbnail;
24	  standard?: ApiThumbnail;
25	  high?: ApiThumbnail;
26	  medium?: ApiThumbnail;
27	  default?: ApiThumbnail;
28	};
29	
30	type VideoApiItem = {
31	  id: string;
32	  snippet: {
33	    title: string;
34	    description?: string;
35	    channelTitle: string;
36	    publishedAt: string;
37	    thumbnails: ApiThumbnails;
38	  };
39	  contentDetails: { duration: string };
40	};
41	
42	type VideosApiResponse = { items: VideoApiItem[] };
43	
44	type ChannelsApiResponse = {
45	  items: Array<{
46	    id: string;
47	    contentDetails: { relatedPlaylists: { uploads: string } };
48	  }>;
49	};
50	
51	type PlaylistItemsApiResponse = {
52	  nextPageToken?: string;
53	  items: Array<{ contentDetails: { videoId: string; videoPublishedAt?: string } }>;
54	};
55	
56	type PlaylistsApiResponse = {
57	  nextPageToken?: string;
58	  items: Array<{
59	    id: string;
60	    snippet: {
61	      title: string;
62	      description?: string;
63	      channelTitle: string;
64	      publishedAt: string;
65	      thumbnails: ApiThumbnails;
66	    };
67	    contentDetails: { itemCount: number };
68	  }>;
69	};
70	
71	export class YouTubeServiceError extends Error {
72	  constructor(
73	    message: string,
74	    readonly kind: 'invalid-url' | 'not-found' | 'api-key' | 'network' | 'api',
75	  ) {
76	    super(message);
77	  }
78	}
79	
80	async function fetchJson<T>(url: string): Promise<T> {
81	  const controller = new AbortController();
82	  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
83	
84	  try {
85	    const response = await fetch(url, { signal: controller.signal });
86	    if (!response.ok) {
87	      if (response.status === 404) {
88	        throw new YouTubeServiceError('This YouTube item is unavailable or private.', 'not-found');
89	      }
90	      throw new YouTubeServiceError(
91	        `YouTube returned an error (${response.status}). Try again later.`,
92	        'api',
93	      );
94	    }
95	    return (await response.json()) as T;
96	  } catch (error) {
97	    if (error instanceof YouTubeServiceError) {
98	      throw error;
99	    }
100	    throw new YouTubeServiceError(
101	      'Could not reach YouTube. Check your connection and try again.',
102	      'network',
103	    );
104	  } finally {
105	    clearTimeout(timeout);
106	  }
107	}
108	
109	function chooseThumbnail(thumbnails: ApiThumbnails): string {
110	  return (
111	    thumbnails.maxres ??
112	    thumbnails.standard ??
113	    thumbnails.high ??
114	    thumbnails.medium ??
115	    thumbnails.default
116	  )?.url ?? '';
117	}
118	
119	function requireApiKey(apiKey: string): string {
120	  const key = apiKey.trim();
121	  if (key.length === 0) {
122	    throw new YouTubeServiceError(
123	      'Add EXPO_PUBLIC_YOUTUBE_API_KEY to .env to load channels and playlists.',
124	      'api-key',
125	    );
126	  }
127	  return key;
128	}
129	
130	export function parseYouTubeVideoId(input: string): string {
131	  let url: URL;
132	  try {
133	    url = new URL(input.trim());
134	  } catch {
135	    throw new YouTubeServiceError(
136	      'Paste a complete YouTube video URL, such as https://youtu.be/...',
137	      'invalid-url',
138	    );
139	  }
140	
141	  if (url.protocol !== 'https:' && url.protocol !== 'http:') {
142	    throw new YouTubeServiceError('Only web links are supported.', 'invalid-url');
143	  }
144	
145	  const hostname = url.hostname.toLowerCase().replace(/^www\./, '');
146	  let videoId: string | null = null;
147	  if (hostname === 'youtu.be') {
148	    videoId = url.pathname.split('/').filter(Boolean)[0] ?? null;
149	  } else if (
150	    hostname === 'youtube.com' ||
151	    hostname === 'm.youtube.com' ||
152	    hostname === 'music.youtube.com' ||
153	    hostname === 'youtube-nocookie.com'
154	  ) {
155	    if (url.pathname === '/watch') {
156	      videoId = url.searchParams.get('v');
157	    } else {
158	      const [kind, candidate] = url.pathname.split('/').filter(Boolean);
159	      if (kind === 'shorts' || kind === 'embed' || kind === 'live') {
160	        videoId = candidate ?? null;
161	      }
162	    }
163	  }
164	
165	  if (videoId === null || !VIDEO_ID_PATTERN.test(videoId)) {
166	    throw new YouTubeServiceError('This is not a supported YouTube video URL.', 'invalid-url');
167	  }
168	  return videoId;
169	}
170	
171	export function parseIsoDuration(value: string): number | null {
172	  const match = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(value);
173	  if (match === null) {
174	    return null;
175	  }
176	  return Number(match[1] ?? 0) * 3600 + Number(match[2] ?? 0) * 60 + Number(match[3] ?? 0);
177	}
178	
179	function videosUrl(ids: readonly string[], apiKey: string): string {
180	  return `${YOUTUBE_API_BASE}/videos?${new URLSearchParams({
181	    part: 'snippet,contentDetails',
182	    id: ids.join(','),
183	    key: apiKey,
184	  }).toString()}`;
185	}
186	
187	async function getVideoFromDataApi(youtubeId: string, apiKey: string): Promise<VideoApiItem | null> {
188	  if (apiKey.length === 0) {
189	    return null;
190	  }
191	  const response = await fetchJson<VideosApiResponse>(videosUrl([youtubeId], apiKey));
192	  return response.items[0] ?? null;
193	}
194	
195	export async function fetchVideoMetadata(
196	  urlOrVideoId: string,
197	  apiKey: string,
198	): Promise<PlayableVideo> {
199	  const youtubeId = VIDEO_ID_PATTERN.test(urlOrVideoId)
200	    ? urlOrVideoId
201	    : parseYouTubeVideoId(urlOrVideoId);
202	  const canonicalUrl = `https://www.youtube.com/watch?v=${youtubeId}`;
203	  const oembedUrl = `${OEMBED_ENDPOINT}?${new URLSearchParams({
204	    url: canonicalUrl,
205	    format: 'json',
206	  }).toString()}`;
207	
208	  const [oembedResult, apiResult] = await Promise.allSettled([
209	    fetchJson<OEmbedResponse>(oembedUrl),
210	    getVideoFromDataApi(youtubeId, apiKey),
211	  ]);
212	  const oembed = oembedResult.status === 'fulfilled' ? oembedResult.value : null;
213	  const apiItem = apiResult.status === 'fulfilled' ? apiResult.value : null;
214	
215	  if (oembed === null && apiItem === null) {
216	    if (oembedResult.status === 'rejected') {
217	      throw oembedResult.reason;
218	    }
219	    throw new YouTubeServiceError('Video metadata could not be loaded.', 'api');
220	  }
221	
222	  return {
223	    youtubeId,
224	    title: apiItem?.snippet.title ?? oembed!.title,
225	    thumbnailUrl: apiItem ? chooseThumbnail(apiItem.snippet.thumbnails) : oembed!.thumbnail_url,
226	    channelName: apiItem?.snippet.channelTitle ?? oembed!.author_name,
227	    durationSeconds: apiItem ? parseIsoDuration(apiItem.contentDetails.duration) : null,
228	    publishedAt: apiItem?.snippet.publishedAt ?? null,
229	    description: apiItem?.snippet.description?.trim() || null,
230	  };
231	}
232	
233	async function resolveChannel(
234	  channel: HardcodedChannel,
235	  apiKey: string,
236	): Promise<{ channelId: string; uploadsPlaylistId: string }> {
237	  const params = new URLSearchParams({
238	    part: 'contentDetails',
239	    forHandle: channel.channelHandle.slice(1),
240	    key: requireApiKey(apiKey),
241	  });
242	  const response = await fetchJson<ChannelsApiResponse>(
243	    `${YOUTUBE_API_BASE}/channels?${params.toString()}`,
244	  );
245	  const item = response.items[0];
246	  if (!item) {
