import Ionicons from '@expo/vector-icons/Ionicons';
import { useEventListener } from 'expo';
import { useVideoPlayer, VideoView } from 'expo-video';
import { useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { colors, radius, spacing } from '@/constants/theme';

type LocalVideoPlayerProps = {
  uri: string;
  onError: (message: string) => void;
};

export function LocalVideoPlayer({ uri, onError }: LocalVideoPlayerProps) {
  const [ended, setEnded] = useState(false);
  const player = useVideoPlayer({ uri }, (instance) => {
    instance.loop = false;
    instance.play();
  });

  useEventListener(player, 'statusChange', ({ status, error }) => {
    if (status === 'error') {
      onError(error?.message ?? 'The downloaded file could not be played.');
    }
  });

  useEventListener(player, 'playToEnd', () => setEnded(true));

  const replay = () => {
    setEnded(false);
    player.currentTime = 0;
    player.play();
  };

  return (
    <View style={styles.container}>
      <VideoView
        contentFit="contain"
        fullscreenOptions={{ enable: true }}
        nativeControls={!ended}
        player={player}
        style={styles.video}
      />
      {ended ? (
        <View style={styles.endedOverlay}>
          <Pressable
            accessibilityLabel="Replay downloaded video"
            accessibilityRole="button"
            onPress={replay}
            style={({ pressed }) => [styles.replay, pressed && styles.pressed]}
          >
            <Ionicons color={colors.black} name="refresh" size={22} />
            <Text style={styles.replayText}>Replay</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    aspectRatio: 16 / 9,
    minHeight: 200,
    overflow: 'hidden',
    backgroundColor: colors.black,
  },
  video: { flex: 1 },
  endedOverlay: {
    position: 'absolute',
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(5, 6, 5, 0.72)',
  },
  replay: {
    minHeight: 46,
    paddingHorizontal: spacing.lg,
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    borderRadius: radius.round,
    backgroundColor: colors.accent,
  },
  replayText: { color: colors.black, fontFamily: 'sans-serif-medium', fontSize: 14 },
  pressed: { opacity: 0.64 },
});

