import {
  createContext,
  type PropsWithChildren,
  useCallback,
  useContext,
  useMemo,
  useState,
} from 'react';

import type { HardcodedChannel } from '@/config/channels';
import type { ChannelPlaylist, PlayableVideo } from '@/types';

export type AppRoute =
  | { name: 'home' }
  | { name: 'folders' }
  | { name: 'folder'; folderId: number; folderName: string }
  | { name: 'channel'; channel: HardcodedChannel }
  | { name: 'playlist'; playlist: ChannelPlaylist }
  | { name: 'player'; video: PlayableVideo };

type NavigationContextValue = {
  route: AppRoute;
  canGoBack: boolean;
  push: (route: AppRoute) => void;
  goBack: () => boolean;
  goHome: () => void;
};

const NavigationContext = createContext<NavigationContextValue | null>(null);

export function NavigationProvider({ children }: PropsWithChildren) {
  const [stack, setStack] = useState<AppRoute[]>([{ name: 'home' }]);
  const route = stack[stack.length - 1]!;

  const push = useCallback((nextRoute: AppRoute) => {
    setStack((current) => [...current, nextRoute]);
  }, []);

  const goBack = useCallback(() => {
    if (stack.length === 1) {
      return false;
    }
    setStack((current) => current.slice(0, -1));
    return true;
  }, [stack.length]);

  const goHome = useCallback(() => {
    setStack([{ name: 'home' }]);
  }, []);

  const value = useMemo(
    () => ({ route, canGoBack: stack.length > 1, push, goBack, goHome }),
    [goBack, goHome, push, route, stack.length],
  );

  return <NavigationContext.Provider value={value}>{children}</NavigationContext.Provider>;
}

export function useAppNavigation(): NavigationContextValue {
  const context = useContext(NavigationContext);
  if (context === null) {
    throw new Error('useAppNavigation must be used inside NavigationProvider.');
  }
  return context;
}

