import { SQLiteProvider } from 'expo-sqlite';
import { StatusBar } from 'expo-status-bar';
import { Suspense, useCallback, useEffect, useRef } from 'react';
import { ActivityIndicator, Alert, BackHandler, Linking, StyleSheet, Text, View } from 'react-native';
import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context';

import { colors, spacing } from '@/constants/theme';
import { LibraryProvider } from '@/context/LibraryContext';
import { useLibrary } from '@/context/LibraryContext';
import {
  NavigationProvider,
  useAppNavigation,
} from '@/context/NavigationContext';
import { migrateDatabase } from '@/data/database';
import { FoldersScreen } from '@/screens/FoldersScreen';
import { FolderVideosScreen } from '@/screens/FolderVideosScreen';
import { ChannelScreen } from '@/screens/ChannelScreen';
import { HomeScreen } from '@/screens/HomeScreen';
import { PlayerScreen } from '@/screens/PlayerScreen';
import { PlaylistScreen } from '@/screens/PlaylistScreen';

function AppNavigator() {
  const { route, goBack, push } = useAppNavigation();
  const { resolveVideo } = useLibrary();
  const lastHandledUrl = useRef<{ url: string; handledAt: number } | null>(null);

  const handleIncomingUrl = useCallback(async (url: string | null) => {
    if (!url || !url.toLowerCase().includes('youtu')) {
      return;
    }
    const now = Date.now();
    if (
      lastHandledUrl.current?.url === url &&
      now - lastHandledUrl.current.handledAt < 1_500
    ) {
      return;
    }
    lastHandledUrl.current = { url, handledAt: now };
    try {
      const video = await resolveVideo(url);
      push({ name: 'player', video });
    } catch (error) {
      Alert.alert(
        'Could not open YouTube link',
        error instanceof Error ? error.message : 'This link is not supported.',
      );
    }
  }, [push, resolveVideo]);

  useEffect(() => {
    const subscription = BackHandler.addEventListener('hardwareBackPress', goBack);
    return () => subscription.remove();
  }, [goBack]);

  useEffect(() => {
    void Linking.getInitialURL().then(handleIncomingUrl);
    const subscription = Linking.addEventListener('url', ({ url }) => {
      void handleIncomingUrl(url);
    });
    return () => subscription.remove();
  }, [handleIncomingUrl]);

  if (route.name === 'folders') {
    return <FoldersScreen />;
  }
  if (route.name === 'folder') {
    return <FolderVideosScreen folderId={route.folderId} folderName={route.folderName} />;
  }
  if (route.name === 'channel') {
    return <ChannelScreen channel={route.channel} />;
  }
  if (route.name === 'playlist') {
    return <PlaylistScreen playlist={route.playlist} />;
  }
  if (route.name === 'player') {
    return <PlayerScreen video={route.video} />;
  }
  return <HomeScreen />;
}

function LoadingScreen() {
  return (
    <View style={styles.loading}>
      <ActivityIndicator color={colors.accent} />
      <Text style={styles.loadingText}>Opening your library…</Text>
    </View>
  );
}

export default function App() {
  return (
    <SafeAreaProvider>
      <StatusBar style="light" />
      <SafeAreaView edges={['top', 'bottom']} style={styles.safeArea}>
        <Suspense fallback={<LoadingScreen />}>
          <SQLiteProvider databaseName="quiet-library.db" onInit={migrateDatabase} useSuspense>
            <LibraryProvider>
              <NavigationProvider>
                <AppNavigator />
              </NavigationProvider>
            </LibraryProvider>
          </SQLiteProvider>
        </Suspense>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: colors.background,
  },
  loading: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    gap: spacing.md,
    backgroundColor: colors.background,
  },
  loadingText: {
    color: colors.inkMuted,
    fontSize: 13,
  },
});

