import Ionicons from '@expo/vector-icons/Ionicons';
import { useState } from 'react';
import { Alert, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { EmptyState } from '@/components/EmptyState';
import { FolderNameModal } from '@/components/FolderNameModal';
import { IconButton } from '@/components/IconButton';
import { ScreenHeader } from '@/components/ScreenHeader';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { Folder } from '@/types';

export function FoldersScreen() {
  const { folders, createFolder, renameFolder, deleteFolder } = useLibrary();
  const { goBack, push } = useAppNavigation();
  const [createVisible, setCreateVisible] = useState(false);
  const [renameTarget, setRenameTarget] = useState<Folder | null>(null);

  const confirmDelete = (folder: Folder) => {
    Alert.alert(
      `Delete “${folder.name}”?`,
      folder.videoCount === 0
        ? 'The empty folder will be removed.'
        : `This folder contains ${folder.videoCount} ${folder.videoCount === 1 ? 'video' : 'videos'}. Choose what happens to them.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: folder.videoCount === 0 ? 'Delete folder' : 'Keep videos',
          onPress: () => void deleteFolder(folder.id, false),
        },
        ...(folder.videoCount > 0
          ? [
              {
                text: 'Delete folder and videos',
                style: 'destructive' as const,
                onPress: () => void deleteFolder(folder.id, true),
              },
            ]
          : []),
      ],
    );
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        action={{ icon: 'add', label: 'Create folder', onPress: () => setCreateVisible(true) }}
        onBack={goBack}
        subtitle="Organize without losing anything"
        title="Folders"
      />
      <FlatList
        contentContainerStyle={folders.length === 0 ? styles.emptyList : styles.list}
        data={folders}
        keyExtractor={(folder) => String(folder.id)}
        ListEmptyComponent={
          <EmptyState
            icon="folder-open-outline"
            message="Create folders for topics, courses, or anything you want to return to."
            title="No folders yet"
          />
        }
        renderItem={({ item }) => (
          <Pressable
            accessibilityRole="button"
            onPress={() => push({ name: 'folder', folderId: item.id, folderName: item.name })}
            style={({ pressed }) => [styles.row, pressed && styles.pressed]}
          >
            <View style={styles.folderIcon}>
              <Ionicons color={colors.accent} name="folder-outline" size={22} />
            </View>
            <View style={styles.copy}>
              <Text numberOfLines={1} style={styles.name}>{item.name}</Text>
              <Text style={styles.count}>
                {item.videoCount} {item.videoCount === 1 ? 'video' : 'videos'}
              </Text>
            </View>
            <IconButton icon="pencil-outline" label={`Rename ${item.name}`} onPress={() => setRenameTarget(item)} />
            <IconButton icon="trash-outline" label={`Delete ${item.name}`} onPress={() => confirmDelete(item)} />
          </Pressable>
        )}
      />
      <FolderNameModal
        onClose={() => setCreateVisible(false)}
        onSubmit={createFolder}
        submitLabel="Create"
        title="New folder"
        visible={createVisible}
      />
      <FolderNameModal
        initialName={renameTarget?.name}
        onClose={() => setRenameTarget(null)}
        onSubmit={async (name) => {
          if (renameTarget) {
            await renameFolder(renameTarget.id, name);
          }
        }}
        submitLabel="Rename"
        title="Rename folder"
        visible={renameTarget !== null}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
