import { useState } from 'react';
import { Alert, FlatList, StyleSheet, View } from 'react-native';

import { EmptyState } from '@/components/EmptyState';
import { AppButton } from '@/components/AppButton';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { OfflineAvailabilityModal } from '@/components/OfflineAvailabilityModal';
import { ScreenHeader } from '@/components/ScreenHeader';
import { VideoActionsModal } from '@/components/VideoActionsModal';
import { VideoCard } from '@/components/VideoCard';
import { colors, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { SavedVideo } from '@/types';

type FolderVideosScreenProps = {
  folderId: number;
  folderName: string;
};

export function FolderVideosScreen({ folderId, folderName }: FolderVideosScreenProps) {
  const { videos, folders, deleteVideo, deleteVideos, moveVideo, moveVideos } = useLibrary();
  const { goBack, push } = useAppNavigation();
  const [actionVideo, setActionVideo] = useState<SavedVideo | null>(null);
  const [moveTarget, setMoveTarget] = useState<SavedVideo | null>(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedVideoIds, setSelectedVideoIds] = useState<Set<string>>(() => new Set());
  const [bulkMoveVisible, setBulkMoveVisible] = useState(false);
  const [availabilityVideo, setAvailabilityVideo] = useState<SavedVideo | null>(null);
  const folderVideos = videos.filter((video) => video.folderId === folderId);

  const endSelection = () => {
    setSelectionMode(false);
    setSelectedVideoIds(new Set());
    setBulkMoveVisible(false);
  };

  const toggleSelected = (youtubeId: string) => {
    setSelectedVideoIds((current) => {
      const next = new Set(current);
      if (next.has(youtubeId)) {
        next.delete(youtubeId);
      } else {
        next.add(youtubeId);
      }
      return next;
    });
  };

  const deleteSelection = () => {
    const ids = [...selectedVideoIds];
    if (ids.length === 0) {
      return;
    }
    Alert.alert(
      `Delete ${ids.length} saved ${ids.length === 1 ? 'video' : 'videos'}?`,
      'This removes the selected entries from Quiet Library.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => void deleteVideos(ids).then(endSelection),
        },
      ],
    );
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        action={folderVideos.length > 0 ? {
          icon: selectionMode ? 'close' : 'checkmark-circle-outline',
          label: selectionMode ? 'Cancel selection' : 'Select videos',
          onPress: selectionMode ? endSelection : () => setSelectionMode(true),
        } : undefined}
        onBack={goBack}
        subtitle={selectionMode
          ? `${selectedVideoIds.size} selected`
          : `${folderVideos.length} ${folderVideos.length === 1 ? 'video' : 'videos'}`}
        title={folderName}
      />
      {selectionMode ? (
        <View style={styles.selectionBar}>
          <AppButton
            icon="checkmark-done-outline"
            label="All"
            onPress={() => setSelectedVideoIds(new Set(folderVideos.map((video) => video.youtubeId)))}
            style={styles.selectionButton}
            variant="secondary"
          />
          <AppButton
            disabled={selectedVideoIds.size === 0}
            icon="folder-outline"
            label="Move"
            onPress={() => setBulkMoveVisible(true)}
            style={styles.selectionButton}
            variant="secondary"
          />
          <AppButton
            disabled={selectedVideoIds.size === 0}
            icon="trash-outline"
            label="Delete"
            onPress={deleteSelection}
            style={styles.selectionButton}
            variant="danger"
          />
        </View>
      ) : null}
      <FlatList
        contentContainerStyle={folderVideos.length === 0 ? styles.emptyList : styles.list}
        data={folderVideos}
        keyExtractor={(video) => video.youtubeId}
        ListEmptyComponent={
          <EmptyState
            icon="folder-open-outline"
            message="Move a saved video here from its action menu."
            title="This folder is empty"
          />
        }
        renderItem={({ item }) => (
          <VideoCard
            downloaded={
              item.downloadStatus === 'downloaded' && item.downloadedFileUri !== null
            }
            onLongPress={() => {
              setSelectionMode(true);
              setSelectedVideoIds((current) => new Set(current).add(item.youtubeId));
            }}
            onMore={() => setActionVideo(item)}
            onPress={() => push({ name: 'player', video: item })}
            onToggleSelect={() => toggleSelected(item.youtubeId)}
            selected={selectedVideoIds.has(item.youtubeId)}
            selecting={selectionMode}
            video={item}
          />
        )}
        removeClippedSubviews
      />
      <VideoActionsModal
        onClose={() => setActionVideo(null)}
        onDelete={() => {
          if (!actionVideo) {
            return;
          }
          const target = actionVideo;
          setActionVideo(null);
          Alert.alert('Delete saved video?', 'This removes it from Quiet Library.', [
            { text: 'Cancel', style: 'cancel' },
            { text: 'Delete', style: 'destructive', onPress: () => void deleteVideo(target.youtubeId) },
          ]);
        }}
        onMove={() => {
          setMoveTarget(actionVideo);
          setActionVideo(null);
        }}
        onOfflineInfo={() => {
          setAvailabilityVideo(actionVideo);
          setActionVideo(null);
        }}
        video={actionVideo}
      />
      <FolderPickerModal
        currentFolderId={folderId}
        folders={folders}
        onClose={() => setMoveTarget(null)}
        onSelect={(nextFolderId) => {
          if (moveTarget) {
            void moveVideo(moveTarget.youtubeId, nextFolderId);
          }
          setMoveTarget(null);
        }}
        visible={moveTarget !== null}
      />
      <FolderPickerModal
        currentFolderId={folderId}
        folders={folders}
        onClose={() => setBulkMoveVisible(false)}
        onSelect={(nextFolderId) => {
          void moveVideos([...selectedVideoIds], nextFolderId).then(endSelection);
        }}
        title={`Move ${selectedVideoIds.size} ${selectedVideoIds.size === 1 ? 'video' : 'videos'}`}
        visible={bulkMoveVisible}
      />
      <OfflineAvailabilityModal
        onClose={() => setAvailabilityVideo(null)}
        video={availabilityVideo}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: colors.background,
  },
  list: {
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.md,
    paddingBottom: spacing.xxl,
    gap: spacing.md,
  },
  selectionBar: {
    flexDirection: 'row',
    gap: spacing.sm,
    paddingHorizontal: spacing.lg,
    paddingBottom: spacing.sm,
  },
  selectionButton: { flex: 1, paddingHorizontal: spacing.sm },
  emptyList: {
    flexGrow: 1,
    justifyContent: 'center',
  },
});

