import { useEffect, useState } from 'react';
import { StyleSheet, Text, TextInput, View } from 'react-native';

import { AppButton } from '@/components/AppButton';
import { BottomSheet } from '@/components/BottomSheet';
import { colors, radius, spacing } from '@/constants/theme';

type FolderNameModalProps = {
  visible: boolean;
  title: string;
  initialName?: string;
  submitLabel: string;
  onClose: () => void;
  onSubmit: (name: string) => Promise<void>;
};

export function FolderNameModal({
  visible,
  title,
  initialName = '',
  submitLabel,
  onClose,
  onSubmit,
}: FolderNameModalProps) {
  const [name, setName] = useState(initialName);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (visible) {
      setName(initialName);
      setError(null);
    }
  }, [initialName, visible]);

  const submit = async () => {
    setLoading(true);
    setError(null);
    try {
      await onSubmit(name);
      onClose();
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : 'The folder could not be saved.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <BottomSheet onClose={onClose} visible={visible}>
      <Text style={styles.title}>{title}</Text>
      <TextInput
        autoCapitalize="sentences"
        autoCorrect
        maxLength={60}
        onChangeText={(value) => {
          setName(value);
          setError(null);
        }}
        onSubmitEditing={() => void submit()}
        placeholder="Folder name"
        placeholderTextColor={colors.inkMuted}
        returnKeyType="done"
        selectTextOnFocus={initialName.length > 0}
        style={[styles.input, error && styles.inputError]}
        value={name}
      />
      {error ? <Text style={styles.error}>{error}</Text> : null}
      <View style={styles.actions}>
        <AppButton label="Cancel" onPress={onClose} style={styles.flex} variant="quiet" />
