import { useEffect, useRef, useState } from 'react';
import {
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { AppButton } from '@/components/AppButton';
import { BottomSheet } from '@/components/BottomSheet';
import { colors, radius, spacing } from '@/constants/theme';
import type { Folder } from '@/types';

type AddVideoModalProps = {
  visible: boolean;
  folders: readonly Folder[];
  onClose: () => void;
  onAdd: (url: string, folderId: number | null) => Promise<void>;
};

export function AddVideoModal({ visible, folders, onClose, onAdd }: AddVideoModalProps) {
  const inputRef = useRef<TextInput>(null);
  const [url, setUrl] = useState('');
  const [folderId, setFolderId] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!visible) {
      setUrl('');
      setFolderId(null);
      setError(null);
      setLoading(false);
    }
  }, [visible]);

  useEffect(() => {
    if (!visible) {
      return;
    }
    inputRef.current?.blur();
    const focusTimer = setTimeout(() => inputRef.current?.focus(), 500);
    return () => clearTimeout(focusTimer);
  }, [visible]);

  const submit = async () => {
    setError(null);
    setLoading(true);
    try {
      await onAdd(url, folderId);
      onClose();
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : 'The video could not be added.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <BottomSheet onClose={onClose} visible={visible}>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView keyboardShouldPersistTaps="handled">
          <Text style={styles.title}>Add a video</Text>
          <Text style={styles.message}>
