          </Text>
          <TextInput
            ref={inputRef}
            autoCapitalize="none"
            autoCorrect={false}
            keyboardType="url"
            onChangeText={(value) => {
              setUrl(value);
              setError(null);
            }}
            placeholder="https://youtu.be/…"
            placeholderTextColor={colors.inkMuted}
            returnKeyType="done"
            showSoftInputOnFocus
            style={[styles.input, error && styles.inputError]}
            value={url}
          />
          {error ? <Text style={styles.error}>{error}</Text> : null}
          <Text style={styles.label}>Folder</Text>
          <View style={styles.folderList}>
            <FolderChoice
              label="Unfiled"
              onPress={() => setFolderId(null)}
              selected={folderId === null}
            />
            {folders.map((folder) => (
              <FolderChoice
                key={folder.id}
                label={folder.name}
                onPress={() => setFolderId(folder.id)}
                selected={folderId === folder.id}
              />
            ))}
          </View>
          <View style={styles.actions}>
            <AppButton label="Cancel" onPress={onClose} style={styles.flex} variant="quiet" />
            <AppButton
              disabled={url.trim().length === 0}
              label="Save video"
              loading={loading}
              onPress={() => void submit()}
              style={styles.flex}
            />
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </BottomSheet>
  );
}

