import { useMemo } from 'react';
import { ActivityIndicator, StyleSheet, Text, View } from 'react-native';
import WebView, { type WebViewMessageEvent } from 'react-native-webview';

import { colors } from '@/constants/theme';

type YouTubePlayerProps = {
  youtubeId: string;
  onError: (message: string) => void;
  onEnded: () => void;
};

const APP_ORIGIN = 'https://com.omen6.quietlibrary';

function createPlayerHtml(youtubeId: string): string {
  return `<!doctype html>
<html>
  <head>
    <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1" />
    <style>
      html, body, #player { width: 100%; height: 100%; margin: 0; padding: 0; background: #080908; overflow: hidden; }
    </style>
  </head>
  <body>
    <div id="player"></div>
    <script src="https://www.youtube.com/iframe_api"></script>
    <script>
      const videoId = ${JSON.stringify(youtubeId)};
      let player;
      function onYouTubeIframeAPIReady() {
        player = new YT.Player('player', {
          host: 'https://www.youtube-nocookie.com',
          width: '100%',
          height: '100%',
          videoId,
          playerVars: {
            autoplay: 0,
            controls: 1,
            disablekb: 0,
            fs: 1,
            iv_load_policy: 3,
            playsinline: 1,
            rel: 0,
            origin: ${JSON.stringify(APP_ORIGIN)}
          },
          events: {
            onReady: () => window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'ready' })),
            onError: (event) => window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'error', code: event.data })),
            onStateChange: (event) => {
              if (event.data === YT.PlayerState.ENDED) {
                window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'ended' }));
              }
            }
          }
        });
      }
    </script>
  </body>
</html>`;
}

export function YouTubePlayer({ youtubeId, onError, onEnded }: YouTubePlayerProps) {
  const html = useMemo(() => createPlayerHtml(youtubeId), [youtubeId]);
  const allowedEmbedUrls = [
    `https://www.youtube.com/embed/${youtubeId}`,
    `https://www.youtube-nocookie.com/embed/${youtubeId}`,
  ];

  const handleMessage = (event: WebViewMessageEvent) => {
    try {
      const message = JSON.parse(event.nativeEvent.data) as { type: string; code?: number };
      if (message.type === 'error') {
        const description =
          message.code === 101 || message.code === 150
            ? 'The channel does not allow this video to be embedded.'
            : message.code === 100
              ? 'This video is unavailable or private.'
              : message.code === 153
                ? 'YouTube could not identify this app for embedded playback.'
                : 'YouTube could not play this video.';
        onError(description);
      } else if (message.type === 'ended') {
        onEnded();
      }
    } catch {
      onError('The player returned an unreadable response.');
    }
  };

  return (
    <View style={styles.container}>
      <WebView
        allowsFullscreenVideo
        allowsInlineMediaPlayback
        javaScriptEnabled
        mediaPlaybackRequiresUserAction
        onError={() => onError('The embedded player could not be loaded.')}
        onHttpError={() => onError('YouTube returned an error while loading the player.')}
        onMessage={handleMessage}
        onShouldStartLoadWithRequest={(request) =>
          request.url === 'about:blank' ||
          request.url.startsWith(APP_ORIGIN) ||
          allowedEmbedUrls.some((url) => request.url.startsWith(url))
        }
        originWhitelist={[
          APP_ORIGIN,
          'https://www.youtube.com',
          'https://www.youtube-nocookie.com',
          'about:blank',
        ]}
        renderLoading={() => (
          <View style={styles.loading}>
            <ActivityIndicator color={colors.white} />
            <Text style={styles.loadingText}>Loading player…</Text>
          </View>
        )}
        setSupportMultipleWindows={false}
        source={{ html, baseUrl: APP_ORIGIN }}
        startInLoadingState
        style={styles.webview}
        thirdPartyCookiesEnabled
      />
    </View>
  );
}

const styles = StyleSheet.create({
