export type DownloadStatus =
  | 'unavailable'
  | 'queued'
  | 'downloading'
  | 'downloaded'
  | 'failed'
  | 'interrupted';

export type DownloadKind = 'video' | 'audio';

export type Folder = {
  id: number;
  name: string;
  parentId: number | null;
  createdAt: number;
  videoCount: number;
};

/** A folder plus the position it occupies in the folder tree. */
export type FolderNode = Folder & {
  depth: number;
  path: string;
  totalVideoCount: number;
};

export type SavedVideo = {
  youtubeId: string;
  title: string;
  thumbnailUrl: string;
  channelName: string;
  durationSeconds: number | null;
  publishedAt: string | null;
  description: string | null;
  notes: string | null;
  folderId: number | null;
  folderName: string | null;
  addedAt: number;
  metadataFetchedAt: number;
  downloadStatus: DownloadStatus;
  downloadKind: DownloadKind;
  downloadProgress: number;
  downloadedFileUri: string | null;
};

export type ChannelVideo = {
  youtubeId: string;
  title: string;
  thumbnailUrl: string;
  channelName: string;
  channelHandle: string;
  durationSeconds: number | null;
  publishedAt: string;
  description: string | null;
  fetchedAt: number;
};

export type ChannelPlaylist = {
  playlistId: string;
  title: string;
  description: string | null;
  thumbnailUrl: string;
  channelName: string;
  channelHandle: string;
  itemCount: number;
  publishedAt: string;
};

export type PageResult<T> = {
  items: T[];
  nextPageToken: string | null;
};

export type PlayableVideo = Pick<
  SavedVideo,
  | 'youtubeId'
  | 'title'
  | 'thumbnailUrl'
  | 'channelName'
  | 'durationSeconds'
  | 'publishedAt'
  | 'description'
>;

export type VideoMetadataPatch = {
  youtubeId: string;
  title: string;
  thumbnailUrl: string;
  channelName: string;
  durationSeconds: number | null;
  publishedAt: string | null;
  description: string | null;
};

