import type { SQLiteDatabase } from 'expo-sqlite';

import type {
  ChannelPlaylist,
  ChannelVideo,
  DownloadKind,
  DownloadStatus,
  Folder,
  PlayableVideo,
  SavedVideo,
  VideoMetadataPatch,
} from '@/types';

export async function listFolders(db: SQLiteDatabase): Promise<Folder[]> {
  return db.getAllAsync<Folder>(`
    SELECT
      folders.id,
      folders.name,
      folders.parent_id AS parentId,
      folders.created_at AS createdAt,
      COUNT(saved_videos.youtube_id) AS videoCount
    FROM folders
    LEFT JOIN saved_videos ON saved_videos.folder_id = folders.id
    GROUP BY folders.id
    ORDER BY folders.name COLLATE NOCASE
  `);
}

export async function listSavedVideos(db: SQLiteDatabase): Promise<SavedVideo[]> {
  return db.getAllAsync<SavedVideo>(`
    SELECT
      saved_videos.youtube_id AS youtubeId,
      saved_videos.title,
      saved_videos.thumbnail_url AS thumbnailUrl,
      saved_videos.channel_name AS channelName,
      saved_videos.duration_seconds AS durationSeconds,
      saved_videos.published_at AS publishedAt,
      saved_videos.description,
      saved_videos.notes,
      saved_videos.folder_id AS folderId,
      folders.name AS folderName,
      saved_videos.added_at AS addedAt,
      saved_videos.metadata_fetched_at AS metadataFetchedAt,
      saved_videos.download_status AS downloadStatus,
      saved_videos.download_kind AS downloadKind,
      saved_videos.download_progress AS downloadProgress,
      saved_videos.downloaded_file_uri AS downloadedFileUri
    FROM saved_videos
    LEFT JOIN folders ON folders.id = saved_videos.folder_id
    ORDER BY saved_videos.added_at DESC
  `);
}

export async function hasSavedVideo(db: SQLiteDatabase, youtubeId: string): Promise<boolean> {
  const row = await db.getFirstAsync<{ found: number }>(
    'SELECT 1 AS found FROM saved_videos WHERE youtube_id = ? LIMIT 1',
    youtubeId,
  );
  return row !== null;
}

export async function insertSavedVideo(
  db: SQLiteDatabase,
  video: PlayableVideo,
  folderId: number | null,
): Promise<void> {
  const now = Date.now();
  await db.runAsync(
    `INSERT INTO saved_videos (
      youtube_id, title, thumbnail_url, channel_name, duration_seconds,
      published_at, description, folder_id, added_at, metadata_fetched_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    video.youtubeId,
    video.title,
    video.thumbnailUrl,
    video.channelName,
    video.durationSeconds,
    video.publishedAt,
    video.description,
    folderId,
    now,
    now,
  );
}

export async function updateDownloadState(
  db: SQLiteDatabase,
  youtubeId: string,
  status: DownloadStatus,
  kind: DownloadKind,
  progress: number,
  fileUri: string | null,
): Promise<void> {
  await db.runAsync(
    `UPDATE saved_videos
     SET download_status = ?, download_kind = ?, download_progress = ?, downloaded_file_uri = ?
     WHERE youtube_id = ?`,
    status,
    kind,
    progress,
    fileUri,
    youtubeId,
  );
}

export async function markStaleDownloadsInterrupted(db: SQLiteDatabase): Promise<boolean> {
  const result = await db.runAsync(
    `UPDATE saved_videos
     SET download_status = 'interrupted'
     WHERE download_status IN ('queued', 'downloading')`,
  );
  return result.changes > 0;
}

export async function updateVideoNotes(
  db: SQLiteDatabase,
  youtubeId: string,
  notes: string | null,
): Promise<void> {
  await db.runAsync('UPDATE saved_videos SET notes = ? WHERE youtube_id = ?', notes, youtubeId);
}

/** Fills in duration and publication date for entries saved before they were known. */
export async function updateVideoMetadata(
  db: SQLiteDatabase,
  patches: readonly VideoMetadataPatch[],
): Promise<void> {
  if (patches.length === 0) {
    return;
  }
  const now = Date.now();
  await db.withTransactionAsync(async () => {
    for (const patch of patches) {
      await db.runAsync(
        `UPDATE saved_videos
         SET title = ?,
             thumbnail_url = ?,
             channel_name = ?,
             duration_seconds = ?,
             published_at = ?,
             description = COALESCE(?, description),
             metadata_fetched_at = ?
         WHERE youtube_id = ?`,
        patch.title,
        patch.thumbnailUrl,
        patch.channelName,
        patch.durationSeconds,
        patch.publishedAt,
        patch.description,
        now,
        patch.youtubeId,
      );
    }
  });
}

export async function deleteSavedVideo(db: SQLiteDatabase, youtubeId: string): Promise<void> {
  await db.runAsync('DELETE FROM saved_videos WHERE youtube_id = ?', youtubeId);
}

export async function deleteSavedVideos(
  db: SQLiteDatabase,
  youtubeIds: readonly string[],
): Promise<void> {
  await db.withTransactionAsync(async () => {
    for (const youtubeId of youtubeIds) {
      await db.runAsync('DELETE FROM saved_videos WHERE youtube_id = ?', youtubeId);
    }
  });
}

export async function moveSavedVideo(
  db: SQLiteDatabase,
  youtubeId: string,
  folderId: number | null,
): Promise<void> {
  await db.runAsync(
    'UPDATE saved_videos SET folder_id = ? WHERE youtube_id = ?',
    folderId,
    youtubeId,
  );
}

export async function moveSavedVideos(
  db: SQLiteDatabase,
  youtubeIds: readonly string[],
  folderId: number | null,
): Promise<void> {
  await db.withTransactionAsync(async () => {
    for (const youtubeId of youtubeIds) {
      await db.runAsync(
        'UPDATE saved_videos SET folder_id = ? WHERE youtube_id = ?',
        folderId,
        youtubeId,
      );
    }
  });
}

export async function createFolder(
  db: SQLiteDatabase,
  name: string,
  parentId: number | null,
): Promise<number> {
  const result = await db.runAsync(
    'INSERT INTO folders (name, parent_id, created_at) VALUES (?, ?, ?)',
    name,
    parentId,
    Date.now(),
  );
  return result.lastInsertRowId;
}

export async function renameFolder(
  db: SQLiteDatabase,
  folderId: number,
  name: string,
): Promise<void> {
  await db.runAsync('UPDATE folders SET name = ? WHERE id = ?', name, folderId);
}

export async function moveFolder(
  db: SQLiteDatabase,
  folderId: number,
  parentId: number | null,
): Promise<void> {
  await db.runAsync('UPDATE folders SET parent_id = ? WHERE id = ?', parentId, folderId);
}

export async function deleteFolder(
  db: SQLiteDatabase,
  folderId: number,
  deleteVideos: boolean,
): Promise<void> {
  const parent = await db.getFirstAsync<{ parentId: number | null }>(
    'SELECT parent_id AS parentId FROM folders WHERE id = ?',
    folderId,
  );
  await db.withTransactionAsync(async () => {
    // Subfolders are lifted to the deleted folder's parent so nothing is lost.
    await db.runAsync(
      'UPDATE folders SET parent_id = ? WHERE parent_id = ?',
      parent?.parentId ?? null,
      folderId,
    );
    if (deleteVideos) {
      await db.runAsync('DELETE FROM saved_videos WHERE folder_id = ?', folderId);
    } else {
      await db.runAsync('UPDATE saved_videos SET folder_id = NULL WHERE folder_id = ?', folderId);
    }
    await db.runAsync('DELETE FROM folders WHERE id = ?', folderId);
  });
}

export async function listCachedChannelVideos(db: SQLiteDatabase): Promise<ChannelVideo[]> {
  return db.getAllAsync<ChannelVideo>(`
    SELECT
      youtube_id AS youtubeId,
      title,
      thumbnail_url AS thumbnailUrl,
      channel_name AS channelName,
      channel_handle AS channelHandle,
      duration_seconds AS durationSeconds,
      published_at AS publishedAt,
      description,
      fetched_at AS fetchedAt
    FROM channel_videos
    ORDER BY position ASC, published_at DESC
  `);
}

export async function replaceCachedChannelVideos(
  db: SQLiteDatabase,
  channelHandle: string,
  videos: readonly ChannelVideo[],
): Promise<void> {
  await db.withTransactionAsync(async () => {
    await db.runAsync('DELETE FROM channel_videos WHERE channel_handle = ?', channelHandle);
    let position = 0;
    for (const video of videos) {
      await insertChannelVideo(db, video, position);
      position += 1;
    }
  });
}

export async function appendCachedChannelVideos(
  db: SQLiteDatabase,
  videos: readonly ChannelVideo[],
  startPosition: number,
): Promise<void> {
  await db.withTransactionAsync(async () => {
    let position = startPosition;
    for (const video of videos) {
      await insertChannelVideo(db, video, position);
      position += 1;
    }
  });
}

async function insertChannelVideo(
  db: SQLiteDatabase,
  video: ChannelVideo,
  position: number,
): Promise<void> {
  await db.runAsync(
    `INSERT INTO channel_videos (
      youtube_id, channel_handle, title, thumbnail_url, channel_name,
      duration_seconds, published_at, description, position, fetched_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(youtube_id, channel_handle) DO UPDATE SET
      title = excluded.title,
      thumbnail_url = excluded.thumbnail_url,
      channel_name = excluded.channel_name,
      duration_seconds = excluded.duration_seconds,
      published_at = excluded.published_at,
      description = excluded.description,
      position = excluded.position,
      fetched_at = excluded.fetched_at`,
    video.youtubeId,
    video.channelHandle,
    video.title,
    video.thumbnailUrl,
    video.channelName,
    video.durationSeconds,
    video.publishedAt,
    video.description,
    position,
    video.fetchedAt,
  );
}

export async function countCachedChannelVideos(
  db: SQLiteDatabase,
  channelHandle: string,
): Promise<number> {
  const row = await db.getFirstAsync<{ total: number }>(
    'SELECT COUNT(*) AS total FROM channel_videos WHERE channel_handle = ?',
    channelHandle,
