}

export async function deleteFolder(
  db: SQLiteDatabase,
  folderId: number,
  deleteVideos: boolean,
): Promise<void> {
  const parent = await db.getFirstAsync<{ parentId: number | null }>(
    'SELECT parent_id AS parentId FROM folders WHERE id = ?',
    folderId,
  );
  await db.withTransactionAsync(async () => {
    // Subfolders are lifted to the deleted folder's parent so nothing is lost.
    await db.runAsync(
      'UPDATE folders SET parent_id = ? WHERE parent_id = ?',
      parent?.parentId ?? null,
      folderId,
    );
    if (deleteVideos) {
      await db.runAsync('DELETE FROM saved_videos WHERE folder_id = ?', folderId);
    } else {
      await db.runAsync('UPDATE saved_videos SET folder_id = NULL WHERE folder_id = ?', folderId);
    }
    await db.runAsync('DELETE FROM folders WHERE id = ?', folderId);
  });
}

