import type { Folder, FolderNode } from '@/types';

/**
 * Flattens the folder table into a depth-first list so a tree can be rendered
 * with a plain FlatList. Orphaned folders (a parent that no longer exists) are
 * treated as top level so nothing ever disappears from the UI.
 */
export function buildFolderTree(folders: readonly Folder[]): FolderNode[] {
  const byParent = new Map<number | null, Folder[]>();
  const known = new Set(folders.map((folder) => folder.id));

  for (const folder of folders) {
    const parentId =
      folder.parentId !== null && known.has(folder.parentId) ? folder.parentId : null;
    const siblings = byParent.get(parentId) ?? [];
    siblings.push(folder);
    byParent.set(parentId, siblings);
  }

  const nodes: FolderNode[] = [];

  const walk = (parentId: number | null, depth: number, prefix: string) => {
    const children = byParent.get(parentId) ?? [];
    for (const folder of children) {
      const path = prefix.length > 0 ? `${prefix} / ${folder.name}` : folder.name;
      const node: FolderNode = {
        ...folder,
        depth,
        path,
        totalVideoCount: folder.videoCount,
      };
      nodes.push(node);
      walk(folder.id, depth + 1, path);
    }
  };

  walk(null, 0, '');

  // Roll subfolder counts up into their ancestors.
  const byId = new Map(nodes.map((node) => [node.id, node]));
  for (const node of nodes) {
    let parentId = node.parentId;
    const seen = new Set<number>([node.id]);
    while (parentId !== null && !seen.has(parentId)) {
      seen.add(parentId);
      const parent = byId.get(parentId);
      if (parent === undefined) {
        break;
      }
      parent.totalVideoCount += node.videoCount;
      parentId = parent.parentId;
    }
  }

  return nodes;
}

/** The folder itself plus every folder nested below it. */
export function collectFolderIds(
  folders: readonly Folder[],
  folderId: number,
): Set<number> {
  const ids = new Set<number>([folderId]);
  let added = true;
  while (added) {
    added = false;
    for (const folder of folders) {
      if (folder.parentId !== null && ids.has(folder.parentId) && !ids.has(folder.id)) {
        ids.add(folder.id);
        added = true;
      }
    }
  }
  return ids;
}

/** Folders that may not become the parent of `folderId` without creating a cycle. */
export function forbiddenParentIds(
  folders: readonly Folder[],
  folderId: number,
): Set<number> {
  return collectFolderIds(folders, folderId);
}

