import * as FileSystem from 'expo-file-system/legacy';
import * as Sharing from 'expo-sharing';

import type { Folder, SavedVideo } from '@/types';

export type LibraryExport = {
  format: 'quiet-library-export';
  version: 1;
  exportedAt: string;
  folderCount: number;
  videoCount: number;
  folders: Array<{
    id: number;
    name: string;
    parentId: number | null;
    createdAt: string;
  }>;
  videos: Array<{
    youtubeId: string;
    url: string;
    title: string;
    channelName: string;
    durationSeconds: number | null;
    publishedAt: string | null;
    description: string | null;
    notes: string | null;
    folderId: number | null;
    folderName: string | null;
    addedAt: string;
    downloadStatus: string;
    downloadKind: string;
    hasLocalCopy: boolean;
  }>;
};

export function buildLibraryExport(
  folders: readonly Folder[],
  videos: readonly SavedVideo[],
): LibraryExport {
  return {
    format: 'quiet-library-export',
    version: 1,
    exportedAt: new Date().toISOString(),
    folderCount: folders.length,
    videoCount: videos.length,
    folders: folders.map((folder) => ({
      id: folder.id,
      name: folder.name,
      parentId: folder.parentId,
      createdAt: new Date(folder.createdAt).toISOString(),
    })),
    videos: videos.map((video) => ({
      youtubeId: video.youtubeId,
      url: `https://www.youtube.com/watch?v=${video.youtubeId}`,
      title: video.title,
      channelName: video.channelName,
      durationSeconds: video.durationSeconds,
      publishedAt: video.publishedAt,
      description: video.description,
      notes: video.notes,
      folderId: video.folderId,
      folderName: video.folderName,
      addedAt: new Date(video.addedAt).toISOString(),
      downloadStatus: video.downloadStatus,
      downloadKind: video.downloadKind,
      hasLocalCopy: video.downloadStatus === 'downloaded' && video.downloadedFileUri !== null,
    })),
  };
}

function timestampSlug(): string {
  return new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
}

/**
 * Writes the export to a file and opens the system share sheet so it can be
 * kept anywhere on the device (Files, Drive, email, ...).
 */
export async function exportLibraryToFile(payload: LibraryExport): Promise<string> {
  const directory = `${FileSystem.cacheDirectory}exports/`;
  await FileSystem.makeDirectoryAsync(directory, { intermediates: true });
  const fileUri = `${directory}quiet-library-${timestampSlug()}.json`;
  await FileSystem.writeAsStringAsync(fileUri, JSON.stringify(payload, null, 2));

  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(fileUri, {
      mimeType: 'application/json',
      dialogTitle: 'Export Quiet Library data',
      UTI: 'public.json',
    });
  }

  return fileUri;
}

