import { useSQLiteContext } from 'expo-sqlite';
import {
  createContext,
  type PropsWithChildren,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import { HARDCODED_CHANNELS, type HardcodedChannel } from '@/config/channels';
import {
  appendCachedChannelVideos,
  cacheChannelPlaylists,
  cachePlaylistVideos,
  countCachedChannelVideos,
  createFolder as createFolderRecord,
  deleteFolder as deleteFolderRecord,
  deleteSavedVideo as deleteSavedVideoRecord,
  deleteSavedVideos as deleteSavedVideosRecord,
  hasSavedVideo,
  insertSavedVideo,
  listCachedChannelPlaylists,
  listCachedChannelVideos,
  listCachedPlaylistVideos,
  listFolders,
  listSavedVideos,
  markStaleDownloadsInterrupted,
  moveFolder as moveFolderRecord,
  moveSavedVideo as moveSavedVideoRecord,
  moveSavedVideos as moveSavedVideosRecord,
  readPagingToken,
  renameFolder as renameFolderRecord,
  replaceCachedChannelVideos,
  updateDownloadState,
  updateVideoMetadata,
  updateVideoNotes,
  writePagingToken,
} from '@/data/repository';
import { buildLibraryExport, exportLibraryToFile } from '@/services/backup';
import {
  deleteAllDeviceFiles,
  deleteDeviceFile,
  downloadToDevice,
  resolveStreamUrl,
} from '@/services/downloads';
import {
  fetchChannelPlaylistPage,
  fetchChannelVideoPage,
  fetchPlaylistVideoPage,
  fetchVideoMetadata,
  fetchVideosMetadata,
  parseYouTubeVideoId,
} from '@/services/youtube';
import type {
  ChannelPlaylist,
  ChannelVideo,
  DownloadKind,
  DownloadStatus,
  Folder,
  FolderNode,
  PageResult,
  PlayableVideo,
  SavedVideo,
} from '@/types';
import { buildFolderTree } from '@/utils/folders';

type LibraryContextValue = {
  videos: SavedVideo[];
  folders: Folder[];
  folderTree: FolderNode[];
  channelVideos: ChannelVideo[];
  isLoading: boolean;
  isRefreshingChannels: boolean;
  channelError: string | null;
  channelLastUpdatedAt: number | null;
  apiKeyConfigured: boolean;
  activeDownloadCount: number;
  downloadVideo: (youtubeId: string, kind?: DownloadKind) => Promise<void>;
  downloadVideos: (youtubeIds: readonly string[], kind?: DownloadKind) => Promise<void>;
  removeDownload: (youtubeId: string) => Promise<void>;
  updateNotes: (youtubeId: string, notes: string) => Promise<void>;
  resolveVideo: (url: string) => Promise<PlayableVideo>;
  addVideo: (url: string, folderId: number | null) => Promise<SavedVideo>;
  saveVideo: (video: PlayableVideo, folderId: number | null) => Promise<void>;
  saveChannelVideo: (video: ChannelVideo, folderId: number | null) => Promise<void>;
  deleteVideo: (youtubeId: string) => Promise<void>;
  deleteVideos: (youtubeIds: readonly string[]) => Promise<void>;
  moveVideo: (youtubeId: string, folderId: number | null) => Promise<void>;
  moveVideos: (youtubeIds: readonly string[], folderId: number | null) => Promise<void>;
  createFolder: (name: string, parentId?: number | null) => Promise<number>;
  renameFolder: (folderId: number, name: string) => Promise<void>;
  moveFolder: (folderId: number, parentId: number | null) => Promise<void>;
  deleteFolder: (folderId: number, deleteVideos: boolean) => Promise<void>;
  exportLibrary: () => Promise<string>;
  refreshChannels: (channels?: readonly HardcodedChannel[]) => Promise<void>;
  loadChannelVideoPage: (
    channel: HardcodedChannel,
    pageToken?: string | null,
  ) => Promise<PageResult<ChannelVideo>>;
  restoreChannelVideoToken: (channelHandle: string) => Promise<string | null>;
  loadChannelPlaylistPage: (
    channel: HardcodedChannel,
    pageToken?: string | null,
  ) => Promise<PageResult<ChannelPlaylist>>;
  loadCachedChannelPlaylists: (channelHandle: string) => Promise<ChannelPlaylist[]>;
  restoreChannelPlaylistToken: (channelHandle: string) => Promise<string | null>;
  loadPlaylistVideoPage: (
    playlist: ChannelPlaylist,
    pageToken?: string | null,
  ) => Promise<PageResult<ChannelVideo>>;
  loadCachedPlaylistVideos: (playlistId: string) => Promise<ChannelVideo[]>;
  restorePlaylistToken: (playlistId: string) => Promise<string | null>;
};

type DownloadJob = {
  youtubeId: string;
  kind: DownloadKind;
  resolve: () => void;
  reject: (error: Error) => void;
};

const LibraryContext = createContext<LibraryContextValue | null>(null);
const youtubeApiKey = process.env.EXPO_PUBLIC_YOUTUBE_API_KEY?.trim() ?? '';

const channelVideosScope = (channelHandle: string) => `channel-videos:${channelHandle}`;
const channelPlaylistsScope = (channelHandle: string) => `channel-playlists:${channelHandle}`;
const playlistScope = (playlistId: string) => `playlist:${playlistId}`;

function normalizeFolderName(name: string): string {
  const normalized = name.trim().replace(/\s+/g, ' ');
  if (normalized.length === 0) {
    throw new Error('Folder name cannot be empty.');
  }
  if (normalized.length > 60) {
    throw new Error('Folder names must be 60 characters or fewer.');
  }
  return normalized;
}

function folderError(error: unknown): Error {
  if (error instanceof Error && error.message.toLowerCase().includes('unique')) {
    return new Error('A folder with that name already exists.');
  }
  return error instanceof Error ? error : new Error('The folder could not be saved.');
}

export function LibraryProvider({ children }: PropsWithChildren) {
  const db = useSQLiteContext();
  const [videos, setVideos] = useState<SavedVideo[]>([]);
  const [folders, setFolders] = useState<Folder[]>([]);
  const [channelVideos, setChannelVideos] = useState<ChannelVideo[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshingChannels, setIsRefreshingChannels] = useState(false);
  const [channelError, setChannelError] = useState<string | null>(null);
  const [activeDownloadCount, setActiveDownloadCount] = useState(0);

  const loadLibrary = useCallback(async () => {
    const [nextVideos, nextFolders] = await Promise.all([
      listSavedVideos(db),
      listFolders(db),
    ]);
    setVideos(nextVideos);
    setFolders(nextFolders);
  }, [db]);

  /** Fills in duration and publication date for older entries that lack them. */
  const backfillMetadata = useCallback(
    async (loaded: readonly SavedVideo[]) => {
      if (youtubeApiKey.length === 0) {
        return;
      }
      const missing = loaded
        .filter((video) => video.durationSeconds === null || video.publishedAt === null)
        .map((video) => video.youtubeId);
      if (missing.length === 0) {
        return;
      }
      const patches = await fetchVideosMetadata(missing, youtubeApiKey);
      if (patches.length === 0) {
        return;
      }
      await updateVideoMetadata(db, patches);
      setVideos(await listSavedVideos(db));
    },
    [db],
  );

  useEffect(() => {
    let active = true;

    void markStaleDownloadsInterrupted(db)
      .catch(() => false)
      .then(() => Promise.all([listSavedVideos(db), listFolders(db), listCachedChannelVideos(db)]))
      .then(([nextVideos, nextFolders, cachedChannels]) => {
        if (!active) {
          return;
        }
        setVideos(nextVideos);
        setFolders(nextFolders);
        setChannelVideos(cachedChannels);
        void backfillMetadata(nextVideos).catch(() => undefined);
      })
      .finally(() => {
        if (active) {
          setIsLoading(false);
        }
      });

    return () => {
      active = false;
    };
  }, [backfillMetadata, db]);

  const addVideo = useCallback(
    async (url: string, folderId: number | null) => {
      const youtubeId = parseYouTubeVideoId(url);
      if (await hasSavedVideo(db, youtubeId)) {
        throw new Error('This video is already in your library.');
      }

      const metadata = await fetchVideoMetadata(youtubeId, youtubeApiKey);
      await insertSavedVideo(db, metadata, folderId);
      await loadLibrary();
      const saved = (await listSavedVideos(db)).find((video) => video.youtubeId === youtubeId);

      if (saved === undefined) {
        throw new Error('The video was saved but could not be reloaded.');
      }
      return saved;
    },
    [db, loadLibrary],
  );

  const videosRef = useRef(videos);
  videosRef.current = videos;

  const resolveVideo = useCallback(async (url: string) => {
    const youtubeId = parseYouTubeVideoId(url);
    const existing = videosRef.current.find((video) => video.youtubeId === youtubeId);
    return existing ?? fetchVideoMetadata(youtubeId, youtubeApiKey);
  }, []);

  const saveVideo = useCallback(
    async (video: PlayableVideo, folderId: number | null) => {
      if (await hasSavedVideo(db, video.youtubeId)) {
        throw new Error('This video is already in your library.');
      }
      await insertSavedVideo(db, video, folderId);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const saveChannelVideo = useCallback(
    (video: ChannelVideo, folderId: number | null) => saveVideo(video, folderId),
    [saveVideo],
  );

  const lastPersistedProgress = useRef(new Map<string, number>());

  const patchVideo = useCallback((youtubeId: string, patch: Partial<SavedVideo>) => {
    setVideos((prev) =>
      prev.map((video) => (video.youtubeId === youtubeId ? { ...video, ...patch } : video)),
    );
  }, []);

  const setDownloadState = useCallback(
    async (
      youtubeId: string,
      status: DownloadStatus,
      kind: DownloadKind,
      progress: number,
      fileUri: string | null,
    ) => {
      patchVideo(youtubeId, {
        downloadStatus: status,
        downloadKind: kind,
        downloadProgress: progress,
        downloadedFileUri: fileUri,
      });
      await updateDownloadState(db, youtubeId, status, kind, progress, fileUri);
    },
    [db, patchVideo],
  );

  const reportDownloadProgress = useCallback(
    (youtubeId: string, kind: DownloadKind, progress: number) => {
      patchVideo(youtubeId, { downloadStatus: 'downloading', downloadProgress: progress });
      const lastPersisted = lastPersistedProgress.current.get(youtubeId) ?? 0;
      if (progress - lastPersisted >= 0.05) {
        lastPersistedProgress.current.set(youtubeId, progress);
        void updateDownloadState(db, youtubeId, 'downloading', kind, progress, null);
      }
    },
    [db, patchVideo],
  );

  const runDownload = useCallback(
    async (youtubeId: string, kind: DownloadKind) => {
      lastPersistedProgress.current.set(youtubeId, 0);
      try {
        await setDownloadState(youtubeId, 'downloading', kind, 0, null);
        const streamUrl = await resolveStreamUrl(youtubeId, kind);
        const fileUri = await downloadToDevice(streamUrl, youtubeId, kind, (progress) => {
          reportDownloadProgress(youtubeId, kind, progress);
        });
        await setDownloadState(youtubeId, 'downloaded', kind, 1, fileUri);
      } catch (error) {
        await setDownloadState(youtubeId, 'failed', kind, 0, null);
        throw error instanceof Error ? error : new Error('The download failed.');
      } finally {
        lastPersistedProgress.current.delete(youtubeId);
      }
    },
    [reportDownloadProgress, setDownloadState],
  );

  // Downloads run one at a time through this queue so that selecting a whole
  // folder does not open dozens of parallel transfers.
  const downloadQueue = useRef<DownloadJob[]>([]);
  const pendingDownloadIds = useRef(new Set<string>());
  const workerActive = useRef(false);
  const runDownloadRef = useRef(runDownload);
  runDownloadRef.current = runDownload;

  const processQueue = useCallback(() => {
    if (workerActive.current) {
      return;
    }
    workerActive.current = true;

    void (async () => {
      try {
        while (downloadQueue.current.length > 0) {
          const job = downloadQueue.current.shift();
          if (job === undefined) {
            break;
          }
          try {
            await runDownloadRef.current(job.youtubeId, job.kind);
            job.resolve();
          } catch (error) {
            job.reject(error instanceof Error ? error : new Error('The download failed.'));
          } finally {
            pendingDownloadIds.current.delete(job.youtubeId);
            setActiveDownloadCount(downloadQueue.current.length);
          }
        }
      } finally {
        workerActive.current = false;
        setActiveDownloadCount(downloadQueue.current.length);
      }
    })();
  }, []);

  const downloadVideo = useCallback(
    async (youtubeId: string, kind: DownloadKind = 'video') => {
      if (pendingDownloadIds.current.has(youtubeId)) {
        return;
      }
      pendingDownloadIds.current.add(youtubeId);
      await setDownloadState(youtubeId, 'queued', kind, 0, null);

      const completion = new Promise<void>((resolve, reject) => {
        downloadQueue.current.push({ youtubeId, kind, resolve, reject });
      });
      setActiveDownloadCount(downloadQueue.current.length);
      processQueue();
      await completion;
    },
    [processQueue, setDownloadState],
  );

  const downloadVideos = useCallback(
    async (youtubeIds: readonly string[], kind: DownloadKind = 'video') => {
      const results = await Promise.allSettled(
        youtubeIds.map((youtubeId) => downloadVideo(youtubeId, kind)),
      );
      const failures = results.filter((result) => result.status === 'rejected');
      if (failures.length === youtubeIds.length && failures.length > 0) {
        const [first] = failures;
        throw first?.status === 'rejected' && first.reason instanceof Error
          ? first.reason
          : new Error('The downloads failed.');
      }
      if (failures.length > 0) {
        throw new Error(
          `${failures.length} of ${youtubeIds.length} downloads failed. The rest were saved.`,
        );
      }
    },
    [downloadVideo],
  );

  const removeDownload = useCallback(
    async (youtubeId: string) => {
      await deleteAllDeviceFiles(youtubeId);
      await setDownloadState(youtubeId, 'unavailable', 'video', 0, null);
    },
    [setDownloadState],
  );

  const updateNotes = useCallback(
    async (youtubeId: string, notes: string) => {
      const trimmed = notes.trim().length === 0 ? null : notes;
      patchVideo(youtubeId, { notes: trimmed });
      await updateVideoNotes(db, youtubeId, trimmed);
    },
    [db, patchVideo],
  );

  const deleteVideo = useCallback(
    async (youtubeId: string) => {
      await deleteAllDeviceFiles(youtubeId);
      await deleteSavedVideoRecord(db, youtubeId);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const deleteVideos = useCallback(
    async (youtubeIds: readonly string[]) => {
      for (const youtubeId of youtubeIds) {
        await deleteAllDeviceFiles(youtubeId);
      }
      await deleteSavedVideosRecord(db, youtubeIds);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const moveVideo = useCallback(
    async (youtubeId: string, folderId: number | null) => {
      await moveSavedVideoRecord(db, youtubeId, folderId);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const moveVideos = useCallback(
    async (youtubeIds: readonly string[], folderId: number | null) => {
      await moveSavedVideosRecord(db, youtubeIds, folderId);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const createFolder = useCallback(
    async (name: string, parentId: number | null = null) => {
      try {
        const folderId = await createFolderRecord(db, normalizeFolderName(name), parentId);
        await loadLibrary();
        return folderId;
      } catch (error) {
        throw folderError(error);
      }
    },
    [db, loadLibrary],
  );

  const renameFolder = useCallback(
    async (folderId: number, name: string) => {
      try {
        await renameFolderRecord(db, folderId, normalizeFolderName(name));
        await loadLibrary();
      } catch (error) {
        throw folderError(error);
      }
    },
    [db, loadLibrary],
  );

  const moveFolder = useCallback(
    async (folderId: number, parentId: number | null) => {
      await moveFolderRecord(db, folderId, parentId);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const deleteFolder = useCallback(
    async (folderId: number, shouldDeleteVideos: boolean) => {
      if (shouldDeleteVideos) {
        const doomed = videosRef.current.filter((video) => video.folderId === folderId);
        for (const video of doomed) {
          await deleteAllDeviceFiles(video.youtubeId);
        }
      }
      await deleteFolderRecord(db, folderId, shouldDeleteVideos);
      await loadLibrary();
    },
    [db, loadLibrary],
  );

  const foldersRef = useRef(folders);
  foldersRef.current = folders;

  const exportLibrary = useCallback(
    () => exportLibraryToFile(buildLibraryExport(foldersRef.current, videosRef.current)),
    [],
  );

  const loadChannelVideoPage = useCallback(
    async (channel: HardcodedChannel, pageToken?: string | null) => {
      const result = await fetchChannelVideoPage(channel, youtubeApiKey, pageToken);
      if (pageToken) {
        const startPosition = await countCachedChannelVideos(db, channel.channelHandle);
        await appendCachedChannelVideos(db, result.items, startPosition);
      } else {
        await replaceCachedChannelVideos(db, channel.channelHandle, result.items);
      }
      await writePagingToken(
        db,
        channelVideosScope(channel.channelHandle),
        result.nextPageToken,
      );
      setChannelVideos(await listCachedChannelVideos(db));
      return result;
    },
    [db],
  );

  const restoreChannelVideoToken = useCallback(
    (channelHandle: string) => readPagingToken(db, channelVideosScope(channelHandle)),
    [db],
  );

  const loadChannelPlaylistPage = useCallback(
    async (channel: HardcodedChannel, pageToken?: string | null) => {
      const result = await fetchChannelPlaylistPage(channel, youtubeApiKey, pageToken);
      const cached = pageToken
        ? await listCachedChannelPlaylists(db, channel.channelHandle)
        : [];
      await cacheChannelPlaylists(
        db,
        channel.channelHandle,
        result.items,
        cached.length,
        !pageToken,
      );
      await writePagingToken(
        db,
        channelPlaylistsScope(channel.channelHandle),
        result.nextPageToken,
      );
      return result;
    },
    [db],
  );

  const loadCachedChannelPlaylists = useCallback(
    (channelHandle: string) => listCachedChannelPlaylists(db, channelHandle),
    [db],
  );

  const restoreChannelPlaylistToken = useCallback(
    (channelHandle: string) => readPagingToken(db, channelPlaylistsScope(channelHandle)),
    [db],
  );

  const loadPlaylistVideoPage = useCallback(
    async (playlist: ChannelPlaylist, pageToken?: string | null) => {
      const result = await fetchPlaylistVideoPage(playlist, youtubeApiKey, pageToken);
      const cached = pageToken ? await listCachedPlaylistVideos(db, playlist.playlistId) : [];
      await cachePlaylistVideos(
        db,
        playlist.playlistId,
        result.items,
        cached.length,
        !pageToken,
      );
      await writePagingToken(db, playlistScope(playlist.playlistId), result.nextPageToken);
      return result;
    },
    [db],
  );

  const loadCachedPlaylistVideos = useCallback(
    (playlistId: string) => listCachedPlaylistVideos(db, playlistId),
    [db],
  );

  const restorePlaylistToken = useCallback(
    (playlistId: string) => readPagingToken(db, playlistScope(playlistId)),
    [db],
  );

  const refreshChannels = useCallback(
    async (channels: readonly HardcodedChannel[] = HARDCODED_CHANNELS) => {
      setIsRefreshingChannels(true);
      setChannelError(null);

      try {
        for (const channel of channels) {
          await loadChannelVideoPage(channel, null);
        }
      } catch (error) {
        setChannelError(error instanceof Error ? error.message : 'Channels could not be refreshed.');
      } finally {
        setIsRefreshingChannels(false);
      }
    },
    [loadChannelVideoPage],
  );

  const channelLastUpdatedAt = useMemo(() => {
    if (channelVideos.length === 0) {
      return null;
    }
    return Math.max(...channelVideos.map((video) => video.fetchedAt));
  }, [channelVideos]);

  const folderTree = useMemo(() => buildFolderTree(folders), [folders]);

  const value = useMemo<LibraryContextValue>(
    () => ({
      videos,
      folders,
      folderTree,
      channelVideos,
      isLoading,
      isRefreshingChannels,
      channelError,
      channelLastUpdatedAt,
      apiKeyConfigured: youtubeApiKey.length > 0,
      activeDownloadCount,
      downloadVideo,
      downloadVideos,
      removeDownload,
      updateNotes,
      resolveVideo,
      addVideo,
      saveVideo,
      saveChannelVideo,
      deleteVideo,
      deleteVideos,
      moveVideo,
      moveVideos,
      createFolder,
      renameFolder,
      moveFolder,
      deleteFolder,
      exportLibrary,
      refreshChannels,
      loadChannelVideoPage,
      restoreChannelVideoToken,
      loadChannelPlaylistPage,
      loadCachedChannelPlaylists,
      restoreChannelPlaylistToken,
      loadPlaylistVideoPage,
      loadCachedPlaylistVideos,
      restorePlaylistToken,
    }),
    [
      activeDownloadCount,
      addVideo,
      channelError,
      channelLastUpdatedAt,
      channelVideos,
      createFolder,
      deleteFolder,
      deleteVideo,
      deleteVideos,
      downloadVideo,
      downloadVideos,
      exportLibrary,
      folderTree,
      folders,
      isLoading,
      isRefreshingChannels,
      loadCachedChannelPlaylists,
      loadCachedPlaylistVideos,
      loadChannelPlaylistPage,
      loadChannelVideoPage,
      loadPlaylistVideoPage,
      moveFolder,
      moveVideo,
      moveVideos,
      refreshChannels,
      removeDownload,
      renameFolder,
      resolveVideo,
      restoreChannelPlaylistToken,
      restoreChannelVideoToken,
      restorePlaylistToken,
      saveChannelVideo,
      saveVideo,
      updateNotes,
      videos,
    ],
  );

  return <LibraryContext.Provider value={value}>{children}</LibraryContext.Provider>;
}

export function useLibrary(): LibraryContextValue {
  const context = useContext(LibraryContext);
  if (context === null) {
    throw new Error('useLibrary must be used inside LibraryProvider.');
  }
  return context;
}

