import Ionicons from '@expo/vector-icons/Ionicons';
import type { ComponentProps } from 'react';
import { Alert, Pressable, StyleSheet, Text, View } from 'react-native';

import { BottomSheet } from '@/components/BottomSheet';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import type { DownloadKind, SavedVideo } from '@/types';

type IconName = ComponentProps<typeof Ionicons>['name'];

type VideoActionsModalProps = {
  video: SavedVideo | null;
  onClose: () => void;
  onMove: () => void;
  onOfflineInfo: () => void;
  onDelete: () => void;
};

export function VideoActionsModal({
  video,
  onClose,
  onMove,
  onOfflineInfo,
  onDelete,
}: VideoActionsModalProps) {
  const { videos, downloadVideo, removeDownload } = useLibrary();
  const liveVideo = video
    ? (videos.find((entry) => entry.youtubeId === video.youtubeId) ?? video)
    : null;

  const status = liveVideo?.downloadStatus ?? 'unavailable';
  const isTransferring = status === 'queued' || status === 'downloading';
  const isDownloaded = status === 'downloaded';
  const progress = Math.max(0, Math.min(100, Math.round((liveVideo?.downloadProgress ?? 0) * 100)));

  const start = (kind: DownloadKind) => {
    if (!liveVideo) {
      return;
    }
    onClose();
    void downloadVideo(liveVideo.youtubeId, kind).catch((error: unknown) => {
      Alert.alert(
        'Download failed',
        error instanceof Error ? error.message : 'The video could not be downloaded.',
      );
    });
  };

  const confirmRemove = () => {
    if (!liveVideo) {
      return;
    }
    const target = liveVideo.youtubeId;
    onClose();
    Alert.alert('Remove local copy?', 'The video stays in your library and can be downloaded again.', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Remove', style: 'destructive', onPress: () => void removeDownload(target) },
    ]);
  };

  return (
    <BottomSheet onClose={onClose} visible={video !== null}>
      <Text numberOfLines={2} style={styles.title}>
        {liveVideo?.title}
      </Text>
      <View style={styles.list}>
        {isTransferring ? (
          <ActionRow
            disabled
            icon="hourglass-outline"
            label={status === 'queued' ? 'Queued for download' : `Downloading… ${progress}%`}
            onPress={() => undefined}
          />
        ) : isDownloaded ? (
          <ActionRow
            icon="trash-bin-outline"
            label={`Remove local ${liveVideo?.downloadKind === 'audio' ? 'audio' : 'video'}`}
            onPress={confirmRemove}
          />
        ) : (
          <>
            <ActionRow
              icon="arrow-down-circle-outline"
              label={status === 'unavailable' ? 'Download video' : 'Retry video download'}
              onPress={() => start('video')}
            />
            <ActionRow
              icon="musical-notes-outline"
              label="Download audio only"
              onPress={() => start('audio')}
            />
          </>
        )}
        <ActionRow icon="folder-outline" label="Move to folder" onPress={onMove} />
        <ActionRow icon="cloud-outline" label="Offline availability" onPress={onOfflineInfo} />
        <ActionRow danger icon="trash-outline" label="Delete from library" onPress={onDelete} />
      </View>
    </BottomSheet>
  );
}

function ActionRow({
  icon,
  label,
  onPress,
  danger = false,
  disabled = false,
}: {
  icon: IconName;
  label: string;
  onPress: () => void;
  danger?: boolean;
  disabled?: boolean;
}) {
  const color = danger ? colors.danger : colors.ink;
  return (
    <Pressable
      accessibilityRole="button"
      disabled={disabled}
      onPress={onPress}
      style={({ pressed }) => [styles.row, pressed && styles.pressed, disabled && styles.disabled]}
    >
      <Ionicons color={color} name={icon} size={21} />
      <Text style={[styles.rowLabel, { color }]}>{label}</Text>
      {disabled ? null : <Ionicons color={colors.inkMuted} name="chevron-forward" size={18} />}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  title: {
    color: colors.ink,
    fontFamily: 'serif',
    fontSize: 20,
    lineHeight: 26,
    fontWeight: '600',
    marginBottom: spacing.lg,
  },
  list: {
    gap: spacing.sm,
  },
  row: {
    minHeight: 52,
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.md,
    paddingHorizontal: spacing.md,
    borderRadius: radius.md,
    backgroundColor: colors.surface,
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: colors.border,
  },
  rowLabel: {
    flex: 1,
    fontSize: 15,
    fontFamily: 'sans-serif-medium',
  },
  pressed: {
    opacity: 0.65,
  },
  disabled: {
    opacity: 0.55,
  },
});

