import { Image } from 'expo-image';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { colors, radius, spacing } from '@/constants/theme';
import type { DownloadKind, PlayableVideo } from '@/types';
import { formatDuration, formatRelativeDate } from '@/utils/format';

type VideoCardProps = {
  video: PlayableVideo;
  folderName?: string | null;
  onPress: () => void;
  onMore?: () => void;
  onSave?: () => void;
  saved?: boolean;
  selecting?: boolean;
  selected?: boolean;
  onToggleSelect?: () => void;
  onLongPress?: () => void;
  downloaded?: boolean;
  downloadKind?: DownloadKind;
  transferring?: boolean;
  downloadProgress?: number;
};

export function VideoCard({
  video,
  folderName,
  onPress,
  onMore,
  onSave,
  saved = false,
  selecting = false,
  selected = false,
  onToggleSelect,
  onLongPress,
  downloaded = false,
  downloadKind = 'video',
  transferring = false,
  downloadProgress = 0,
}: VideoCardProps) {
  const duration = formatDuration(video.durationSeconds);
  const publishedAge = formatRelativeDate(video.publishedAt);
  const percent = Math.max(0, Math.min(100, Math.round(downloadProgress * 100)));

  return (
    <Pressable
      accessibilityLabel={
        selecting
          ? `${selected ? 'Deselect' : 'Select'} ${video.title}`
          : `Play ${downloaded ? 'downloaded ' : ''}${video.title}`
      }
      accessibilityRole="button"
      accessibilityState={selecting ? { selected } : undefined}
      onLongPress={onLongPress}
      onPress={selecting && onToggleSelect ? onToggleSelect : onPress}
      style={({ pressed }) => [
        styles.card,
        selected && styles.cardSelected,
        pressed && styles.pressed,
      ]}
    >
      <View style={styles.thumbnailWrap}>
        <Image
          cachePolicy="memory-disk"
          contentFit="cover"
          recyclingKey={video.youtubeId}
          source={{ uri: video.thumbnailUrl }}
          style={styles.thumbnail}
          transition={0}
        />
        <View style={[styles.playBadge, selecting && styles.selectionBadge]}>
          <Ionicons
            color={selecting ? colors.black : colors.white}
            name={selecting ? (selected ? 'checkmark' : 'ellipse-outline') : 'play'}
            size={selecting ? 17 : 13}
          />
        </View>
        {duration ? <Text style={styles.duration}>{duration}</Text> : null}
        {transferring ? (
          <View style={styles.progressTrack}>
            <View style={[styles.progressFill, { width: `${percent}%` }]} />
          </View>
        ) : null}
      </View>
      <View style={styles.body}>
        <Text numberOfLines={2} style={styles.title}>
          {video.title}
        </Text>
        <Text numberOfLines={1} style={styles.channel}>
          {video.channelName}
          {publishedAge ? `  ·  ${publishedAge}` : ''}
        </Text>
        {folderName || downloaded || transferring ? (
          <View style={styles.detailRow}>
            {folderName ? (
              <Text numberOfLines={1} style={styles.detail}>
                {folderName}
              </Text>
            ) : null}
            {transferring ? (
              <View style={styles.stateBadge}>
                <Ionicons color={colors.accent} name="arrow-down-circle-outline" size={13} />
                <Text style={styles.stateLabel}>{percent}%</Text>
              </View>
            ) : downloaded ? (
              <View style={styles.stateBadge}>
                <Ionicons
                  color={colors.accent}
                  name={downloadKind === 'audio' ? 'musical-notes' : 'arrow-down-circle'}
                  size={13}
                />
                <Text style={styles.stateLabel}>
                  {downloadKind === 'audio' ? 'Audio' : 'Downloaded'}
                </Text>
              </View>
            ) : null}
          </View>
        ) : null}
      </View>
      {!selecting && onMore ? (
        <Pressable
          accessibilityLabel={`More actions for ${video.title}`}
          hitSlop={8}
          onPress={(event) => {
            event.stopPropagation();
            onMore();
          }}
          style={styles.action}
        >
          <Ionicons color={colors.inkMuted} name="ellipsis-vertical" size={20} />
        </Pressable>
      ) : onSave && !selecting ? (
        <Pressable
          accessibilityLabel={saved ? 'Already saved' : `Save ${video.title}`}
          disabled={saved}
          hitSlop={8}
          onPress={(event) => {
            event.stopPropagation();
            onSave();
          }}
          style={styles.action}
        >
          <Ionicons
            color={saved ? colors.accent : colors.inkMuted}
            name={saved ? 'checkmark-circle' : 'add-circle-outline'}
            size={22}
          />
        </Pressable>
      ) : null}
    </Pressable>
  );
}

const styles = StyleSheet.create({
