    borderRadius: radius.sm,
    overflow: 'hidden',
    backgroundColor: colors.surfaceMuted,
  },
  thumbnail: {
    width: '100%',
    height: '100%',
  },
  playBadge: {
    position: 'absolute',
    left: spacing.sm,
    top: spacing.sm,
    width: 28,
    height: 28,
    borderRadius: radius.round,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(8, 9, 8, 0.78)',
  },
  selectionBadge: {
    backgroundColor: colors.accent,
  },
  duration: {
    position: 'absolute',
    right: 5,
