    backgroundColor: 'rgba(8, 9, 8, 0.7)',
  },
  progressFill: {
    height: '100%',
    backgroundColor: colors.accent,
  },
  body: {
    flex: 1,
    alignSelf: 'stretch',
    justifyContent: 'center',
    minWidth: 0,
  },
  title: {
    color: colors.ink,
    fontFamily: 'sans-serif-medium',
    fontSize: 14,
    lineHeight: 19,
  },
  channel: {
    color: colors.inkMuted,
    fontSize: 12,
    lineHeight: 17,
    marginTop: 3,
  },
  detail: {
    flex: 1,
    color: colors.accent,
    fontSize: 11,
    lineHeight: 15,
  },
  detailRow: {
    flexDirection: 'row',
