  title: string,
  message: string,
  onPick: (kind: DownloadKind) => void,
): void {
  Alert.alert(title, message, [
    { text: 'Cancel', style: 'cancel' },
    { text: 'Audio only', onPress: () => onPick('audio') },
    { text: 'Video', onPress: () => onPick('video') },
