import Ionicons from '@expo/vector-icons/Ionicons';
import { useMemo, useState } from 'react';
import { Alert, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { AppButton } from '@/components/AppButton';
import { EmptyState } from '@/components/EmptyState';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { OfflineAvailabilityModal } from '@/components/OfflineAvailabilityModal';
import { ScreenHeader } from '@/components/ScreenHeader';
import { SearchField } from '@/components/SearchField';
import { VideoActionsModal } from '@/components/VideoActionsModal';
import { VideoCard } from '@/components/VideoCard';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { SavedVideo } from '@/types';
import { promptDownloadKind } from '@/utils/downloadPrompt';

type FolderVideosScreenProps = {
  folderId: number;
  folderName: string;
};

export function FolderVideosScreen({ folderId, folderName }: FolderVideosScreenProps) {
  const {
    videos,
    folders,
    folderTree,
    deleteVideo,
    deleteVideos,
    downloadVideos,
    moveVideo,
    moveVideos,
  } = useLibrary();
  const { goBack, push } = useAppNavigation();
  const [actionVideo, setActionVideo] = useState<SavedVideo | null>(null);
  const [moveTarget, setMoveTarget] = useState<SavedVideo | null>(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedVideoIds, setSelectedVideoIds] = useState<Set<string>>(() => new Set());
  const [bulkMoveVisible, setBulkMoveVisible] = useState(false);
  const [availabilityVideo, setAvailabilityVideo] = useState<SavedVideo | null>(null);
  const [search, setSearch] = useState('');

  const subfolders = useMemo(
    () => folderTree.filter((folder) => folder.parentId === folderId),
    [folderId, folderTree],
  );

  const allFolderVideos = useMemo(
    () => videos.filter((video) => video.folderId === folderId),
    [folderId, videos],
  );

  const folderVideos = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (query.length === 0) {
      return allFolderVideos;
    }
    return allFolderVideos.filter((video) =>
      [video.title, video.channelName, video.notes]
        .filter((field): field is string => typeof field === 'string')
        .some((field) => field.toLowerCase().includes(query)),
    );
  }, [allFolderVideos, search]);

  const pendingIds = useMemo(
    () =>
      folderVideos
        .filter((video) => video.downloadStatus !== 'downloaded')
        .map((video) => video.youtubeId),
    [folderVideos],
  );

  const endSelection = () => {
    setSelectionMode(false);
    setSelectedVideoIds(new Set());
    setBulkMoveVisible(false);
  };

  const toggleSelected = (youtubeId: string) => {
    setSelectedVideoIds((current) => {
      const next = new Set(current);
      if (next.has(youtubeId)) {
        next.delete(youtubeId);
      } else {
        next.add(youtubeId);
      }
      return next;
    });
  };

  const startDownloads = (ids: readonly string[], message: string) => {
    if (ids.length === 0) {
      return;
    }
    promptDownloadKind(
      `Download ${ids.length} ${ids.length === 1 ? 'video' : 'videos'}?`,
      message,
      (kind) => {
        void downloadVideos(ids, kind).catch((error: unknown) => {
          Alert.alert(
            'Download problem',
            error instanceof Error ? error.message : 'The downloads failed.',
          );
        });
        endSelection();
      },
    );
  };

  const deleteSelection = () => {
    const ids = [...selectedVideoIds];
    if (ids.length === 0) {
      return;
    }
    Alert.alert(
      `Delete ${ids.length} saved ${ids.length === 1 ? 'video' : 'videos'}?`,
      'This removes the selected entries from Quiet Library.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => void deleteVideos(ids).then(endSelection),
        },
      ],
    );
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        actions={[
          pendingIds.length > 0
            ? {
                icon: 'cloud-download-outline',
                label: 'Download every video in this folder',
                onPress: () =>
                  startDownloads(
                    pendingIds,
                    'Everything in this folder that is not already on the device.',
                  ),
              }
            : null,
          allFolderVideos.length > 0
            ? {
                icon: selectionMode ? 'close' : 'checkmark-circle-outline',
                label: selectionMode ? 'Cancel selection' : 'Select videos',
                onPress: selectionMode ? endSelection : () => setSelectionMode(true),
              }
            : null,
        ]}
        onBack={goBack}
        subtitle={
          selectionMode
            ? `${selectedVideoIds.size} selected`
            : `${allFolderVideos.length} ${allFolderVideos.length === 1 ? 'video' : 'videos'}${
                subfolders.length > 0
                  ? ` · ${subfolders.length} ${subfolders.length === 1 ? 'subfolder' : 'subfolders'}`
                  : ''
              }`
        }
        title={folderName}
      />
      {selectionMode ? (
        <View style={styles.selectionBar}>
          <AppButton
            icon="checkmark-done-outline"
            label="All"
            onPress={() =>
              setSelectedVideoIds(new Set(folderVideos.map((video) => video.youtubeId)))
            }
            style={styles.selectionButton}
            variant="secondary"
          />
          <AppButton
            disabled={selectedVideoIds.size === 0}
            icon="arrow-down-circle-outline"
            label="Save"
            onPress={() =>
              startDownloads([...selectedVideoIds], 'Choose what to keep on this device.')
            }
            style={styles.selectionButton}
            variant="secondary"
          />
          <AppButton
            disabled={selectedVideoIds.size === 0}
            icon="folder-outline"
            label="Move"
            onPress={() => setBulkMoveVisible(true)}
            style={styles.selectionButton}
            variant="secondary"
          />
          <AppButton
            disabled={selectedVideoIds.size === 0}
            icon="trash-outline"
            label="Delete"
            onPress={deleteSelection}
            style={styles.selectionButton}
            variant="danger"
          />
        </View>
      ) : null}
      {allFolderVideos.length > 0 ? (
        <View style={styles.searchWrap}>
          <SearchField
            onChangeText={setSearch}
            placeholder={`Search in ${folderName}`}
            value={search}
          />
        </View>
      ) : null}
      <FlatList
        contentContainerStyle={
          folderVideos.length === 0 && subfolders.length === 0 ? styles.emptyList : styles.list
        }
        data={folderVideos}
        keyExtractor={(video) => video.youtubeId}
        keyboardShouldPersistTaps="handled"
        ListEmptyComponent={
          subfolders.length === 0 ? (
            <EmptyState
              icon="folder-open-outline"
              message={
                search.trim().length > 0
                  ? 'No video in this folder matches your search.'
                  : 'Move a saved video here from its action menu.'
              }
              title={search.trim().length > 0 ? 'No matches' : 'This folder is empty'}
            />
          ) : null
        }
        ListHeaderComponent={
          subfolders.length > 0 ? (
            <View style={styles.subfolders}>
              {subfolders.map((folder) => (
                <Pressable
                  accessibilityRole="button"
                  key={folder.id}
                  onPress={() =>
                    push({ name: 'folder', folderId: folder.id, folderName: folder.name })
                  }
                  style={({ pressed }) => [styles.subfolder, pressed && styles.pressed]}
                >
                  <Ionicons color={colors.accent} name="folder-outline" size={18} />
                  <Text numberOfLines={1} style={styles.subfolderName}>
                    {folder.name}
                  </Text>
                  <Text style={styles.subfolderCount}>{folder.totalVideoCount}</Text>
                  <Ionicons color={colors.inkMuted} name="chevron-forward" size={16} />
                </Pressable>
              ))}
            </View>
          ) : null
        }
        renderItem={({ item }) => (
          <VideoCard
            downloadKind={item.downloadKind}
            downloadProgress={item.downloadProgress}
            downloaded={item.downloadStatus === 'downloaded' && item.downloadedFileUri !== null}
            onLongPress={() => {
              setSelectionMode(true);
              setSelectedVideoIds((current) => new Set(current).add(item.youtubeId));
            }}
            onMore={() => setActionVideo(item)}
            onPress={() => push({ name: 'player', video: item })}
            onToggleSelect={() => toggleSelected(item.youtubeId)}
            selected={selectedVideoIds.has(item.youtubeId)}
            selecting={selectionMode}
            transferring={
              item.downloadStatus === 'downloading' || item.downloadStatus === 'queued'
            }
            video={item}
          />
        )}
        removeClippedSubviews
      />
      <VideoActionsModal
        onClose={() => setActionVideo(null)}
        onDelete={() => {
          if (!actionVideo) {
            return;
          }
          const target = actionVideo;
          setActionVideo(null);
          Alert.alert('Delete saved video?', 'This removes it from Quiet Library.', [
            { text: 'Cancel', style: 'cancel' },
            {
              text: 'Delete',
              style: 'destructive',
              onPress: () => void deleteVideo(target.youtubeId),
            },
          ]);
        }}
        onMove={() => {
          setMoveTarget(actionVideo);
          setActionVideo(null);
        }}
        onOfflineInfo={() => {
          setAvailabilityVideo(actionVideo);
          setActionVideo(null);
        }}
        video={actionVideo}
      />
      <FolderPickerModal
        currentFolderId={folderId}
        folders={folders}
        onClose={() => setMoveTarget(null)}
        onSelect={(nextFolderId) => {
          if (moveTarget) {
            void moveVideo(moveTarget.youtubeId, nextFolderId);
          }
          setMoveTarget(null);
        }}
        visible={moveTarget !== null}
      />
      <FolderPickerModal
        currentFolderId={folderId}
        folders={folders}
        onClose={() => setBulkMoveVisible(false)}
        onSelect={(nextFolderId) => {
          void moveVideos([...selectedVideoIds], nextFolderId).then(endSelection);
        }}
        title={`Move ${selectedVideoIds.size} ${selectedVideoIds.size === 1 ? 'video' : 'videos'}`}
        visible={bulkMoveVisible}
      />
      <OfflineAvailabilityModal
        onClose={() => setAvailabilityVideo(null)}
        video={availabilityVideo}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: colors.background,
  },
  list: {
