import Ionicons from '@expo/vector-icons/Ionicons';
import { useState } from 'react';
import { Alert, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { EmptyState } from '@/components/EmptyState';
import { FolderNameModal } from '@/components/FolderNameModal';
import { IconButton } from '@/components/IconButton';
import { ScreenHeader } from '@/components/ScreenHeader';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { FolderNode } from '@/types';

export function FoldersScreen() {
  const { folderTree, videos, createFolder, renameFolder, deleteFolder, exportLibrary } =
    useLibrary();
  const { goBack, push } = useAppNavigation();
  // `undefined` keeps the sheet closed; `null` creates a top level folder.
  const [creatingUnder, setCreatingUnder] = useState<number | null | undefined>(undefined);
  const [renameTarget, setRenameTarget] = useState<FolderNode | null>(null);
  const [exporting, setExporting] = useState(false);

  const confirmDelete = (folder: FolderNode) => {
    const hasChildren = folderTree.some((entry) => entry.parentId === folder.id);
    Alert.alert(
      `Delete “${folder.name}”?`,
      [
        folder.videoCount === 0
          ? 'The empty folder will be removed.'
          : `This folder holds ${folder.videoCount} ${folder.videoCount === 1 ? 'video' : 'videos'}. Choose what happens to them.`,
        hasChildren ? 'Its subfolders move up one level and keep their videos.' : null,
      ]
        .filter(Boolean)
        .join('\n\n'),
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: folder.videoCount === 0 ? 'Delete folder' : 'Keep videos',
          onPress: () => void deleteFolder(folder.id, false),
        },
        ...(folder.videoCount > 0
          ? [
              {
                text: 'Delete folder and videos',
                style: 'destructive' as const,
                onPress: () => void deleteFolder(folder.id, true),
              },
            ]
          : []),
      ],
    );
  };

  const runExport = () => {
    if (exporting) {
      return;
    }
    setExporting(true);
    void exportLibrary()
      .then(() => undefined)
      .catch((error: unknown) => {
        Alert.alert(
          'Export failed',
          error instanceof Error ? error.message : 'The file could not be written.',
        );
      })
      .finally(() => setExporting(false));
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        actions={[
          {
            icon: 'share-outline',
            label: 'Export library as JSON',
            onPress: runExport,
          },
          {
            icon: 'add',
            label: 'Create folder',
            onPress: () => setCreatingUnder(null),
          },
        ]}
        onBack={goBack}
        subtitle={`${folderTree.length} ${folderTree.length === 1 ? 'folder' : 'folders'} · ${videos.length} saved`}
        title="Folders"
      />
      <FlatList
        contentContainerStyle={folderTree.length === 0 ? styles.emptyList : styles.list}
        data={folderTree}
        keyExtractor={(folder) => String(folder.id)}
        ListEmptyComponent={
          <EmptyState
            icon="folder-open-outline"
            message="Create folders for topics, courses, or anything you want to return to. Folders can hold subfolders too."
            title="No folders yet"
          />
        }
        renderItem={({ item }) => (
          <View style={{ paddingLeft: item.depth * spacing.lg }}>
            <Pressable
              accessibilityRole="button"
              onPress={() => push({ name: 'folder', folderId: item.id, folderName: item.name })}
              style={({ pressed }) => [styles.row, pressed && styles.pressed]}
            >
              <View style={styles.folderIcon}>
                <Ionicons
                  color={colors.accent}
                  name={item.depth > 0 ? 'file-tray-full-outline' : 'folder-outline'}
                  size={20}
                />
              </View>
              <View style={styles.copy}>
                <Text numberOfLines={1} style={styles.name}>
                  {item.name}
                </Text>
                <Text style={styles.count}>
                  {item.videoCount} {item.videoCount === 1 ? 'video' : 'videos'}
                  {item.totalVideoCount > item.videoCount
                    ? ` · ${item.totalVideoCount} with subfolders`
                    : ''}
                </Text>
              </View>
              <IconButton
                icon="add"
                label={`Add a subfolder inside ${item.name}`}
                onPress={() => setCreatingUnder(item.id)}
              />
              <IconButton
                icon="pencil-outline"
                label={`Rename ${item.name}`}
                onPress={() => setRenameTarget(item)}
              />
              <IconButton
                icon="trash-outline"
                label={`Delete ${item.name}`}
                onPress={() => confirmDelete(item)}
              />
            </Pressable>
          </View>
        )}
      />
      <FolderNameModal
        onClose={() => setCreatingUnder(undefined)}
        onSubmit={async (name) => {
          await createFolder(name, creatingUnder ?? null);
        }}
        submitLabel="Create"
        title={creatingUnder === null ? 'New folder' : 'New subfolder'}
        visible={creatingUnder !== undefined}
      />
      <FolderNameModal
        initialName={renameTarget?.name}
        onClose={() => setRenameTarget(null)}
        onSubmit={async (name) => {
          if (renameTarget) {
            await renameFolder(renameTarget.id, name);
          }
        }}
        submitLabel="Rename"
        title="Rename folder"
        visible={renameTarget !== null}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: colors.background,
  },
