import Ionicons from '@expo/vector-icons/Ionicons';
import { useMemo, useState } from 'react';
import { ActivityIndicator, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { AppButton } from '@/components/AppButton';
import { IconButton } from '@/components/IconButton';
import { HARDCODED_CHANNELS, type HardcodedChannel } from '@/config/channels';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import { isShortVideo } from '@/utils/format';

export function ChannelsView() {
  const { channelVideos, isRefreshingChannels, channelError, refreshChannels } = useLibrary();
  const { push } = useAppNavigation();
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedHandles, setSelectedHandles] = useState<Set<string>>(() => new Set());

  const cachedCounts = useMemo(() => {
    const counts = new Map<string, number>();
    for (const video of channelVideos) {
      if (isShortVideo(video)) {
        continue;
      }
      counts.set(video.channelHandle, (counts.get(video.channelHandle) ?? 0) + 1);
    }
    return counts;
  }, [channelVideos]);

  const endSelection = () => {
    setSelectionMode(false);
    setSelectedHandles(new Set());
  };

  const toggle = (channelHandle: string) => {
    setSelectedHandles((current) => {
      const next = new Set(current);
      if (next.has(channelHandle)) {
        next.delete(channelHandle);
      } else {
        next.add(channelHandle);
      }
      return next;
    });
  };

  const selectAll = () => {
    setSelectedHandles((current) =>
      current.size === HARDCODED_CHANNELS.length
        ? new Set()
        : new Set(HARDCODED_CHANNELS.map((channel) => channel.channelHandle)),
    );
  };

  const refreshSelected = () => {
    const channels: HardcodedChannel[] = HARDCODED_CHANNELS.filter((channel) =>
      selectedHandles.has(channel.channelHandle),
    );
    if (channels.length === 0) {
      return;
    }
    void refreshChannels(channels).then(endSelection);
  };

  return (
    <View style={styles.container}>
      <View style={styles.intro}>
        <View style={styles.introRow}>
          <View style={styles.introCopy}>
            <Text style={styles.eyebrow}>
              {selectionMode ? 'SELECT CHANNELS' : 'CURATED CHANNELS'}
            </Text>
            <Text style={styles.message}>
              {selectionMode
                ? `${selectedHandles.size} selected. Refresh them together to pull new uploads.`
                : 'Open a channel to browse its videos and playlists.'}
            </Text>
          </View>
          {selectionMode ? (
            <IconButton icon="close" label="Cancel selection" onPress={endSelection} />
          ) : (
            <IconButton
              filled
              icon="checkmark-circle-outline"
              label="Select channels"
              onPress={() => setSelectionMode(true)}
            />
          )}
        </View>
        {selectionMode ? (
          <View style={styles.selectionBar}>
            <AppButton
              icon="checkmark-done-outline"
              label={selectedHandles.size === HARDCODED_CHANNELS.length ? 'None' : 'All'}
              onPress={selectAll}
              style={styles.selectionButton}
              variant="secondary"
            />
            <AppButton
              disabled={selectedHandles.size === 0 || isRefreshingChannels}
              icon="refresh-outline"
              label="Refresh selected"
              loading={isRefreshingChannels}
              onPress={refreshSelected}
              style={styles.selectionButton}
            />
          </View>
        ) : null}
        {channelError ? <Text style={styles.error}>{channelError}</Text> : null}
      </View>
      <FlatList
        contentContainerStyle={styles.list}
        data={HARDCODED_CHANNELS}
        keyExtractor={(channel) => channel.channelHandle}
        renderItem={({ item }) => {
          const cachedCount = cachedCounts.get(item.channelHandle) ?? 0;
          const selected = selectedHandles.has(item.channelHandle);
          return (
            <Pressable
              accessibilityLabel={
                selectionMode
                  ? `${selected ? 'Deselect' : 'Select'} ${item.name}`
                  : `Open ${item.name}`
              }
              accessibilityRole="button"
              accessibilityState={selectionMode ? { selected } : undefined}
              onLongPress={() => {
                setSelectionMode(true);
                toggle(item.channelHandle);
              }}
              onPress={() =>
                selectionMode
                  ? toggle(item.channelHandle)
                  : push({ name: 'channel', channel: item })
              }
              style={({ pressed }) => [
                styles.channel,
                selected && styles.channelSelected,
                pressed && styles.pressed,
              ]}
            >
              <View style={[styles.icon, selected && styles.iconSelected]}>
                <Ionicons
                  color={selected ? colors.black : colors.accent}
                  name={
                    selectionMode
                      ? selected
                        ? 'checkmark'
                        : 'ellipse-outline'
                      : 'folder-open-outline'
                  }
                  size={selectionMode ? 22 : 24}
                />
              </View>
              <View style={styles.copy}>
                <Text style={styles.name}>{item.name}</Text>
                <Text style={styles.handle}>
                  {item.channelHandle}
                  {cachedCount > 0 ? `  ·  ${cachedCount} cached` : ''}
                </Text>
              </View>
              {isRefreshingChannels && selected ? (
                <ActivityIndicator color={colors.accent} />
              ) : (
                <Ionicons color={colors.inkMuted} name="chevron-forward" size={20} />
              )}
            </Pressable>
          );
        }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  intro: {
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.md,
    paddingBottom: spacing.lg,
  },
  introRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.md,
  },
  introCopy: { flex: 1 },
  eyebrow: {
    color: colors.accent,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
    letterSpacing: 1.1,
  },
  message: {
    color: colors.inkMuted,
    fontSize: 13,
    lineHeight: 19,
    marginTop: spacing.xs,
  },
  selectionBar: {
