import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  FlatList,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { AppButton } from '@/components/AppButton';
import { EmptyState } from '@/components/EmptyState';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { PlaylistCard } from '@/components/PlaylistCard';
import { ScreenHeader } from '@/components/ScreenHeader';
import { SearchField } from '@/components/SearchField';
import { SegmentedControl } from '@/components/SegmentedControl';
import { VideoCard } from '@/components/VideoCard';
import type { HardcodedChannel } from '@/config/channels';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { ChannelPlaylist, ChannelVideo, DownloadKind } from '@/types';
import { promptDownloadKind } from '@/utils/downloadPrompt';
import { isShortVideo } from '@/utils/format';

type ChannelScreenProps = { channel: HardcodedChannel };
type ChannelSection = 'videos' | 'playlists';

const sections = [
  { label: 'Videos', value: 'videos' },
  { label: 'Playlists', value: 'playlists' },
] as const;

/** Remembered between visits so returning from a video keeps your place. */
const scrollOffsets = new Map<string, number>();

function appendUnique<T>(current: T[], incoming: T[], getId: (item: T) => string): T[] {
  const ids = new Set(current.map(getId));
  return [...current, ...incoming.filter((item) => !ids.has(getId(item)))];
}

export function ChannelScreen({ channel }: ChannelScreenProps) {
  const {
    videos,
    folders,
    channelVideos,
    isLoading,
    apiKeyConfigured,
    downloadVideos,
    loadCachedChannelPlaylists,
    loadChannelVideoPage,
    loadChannelPlaylistPage,
    restoreChannelPlaylistToken,
    restoreChannelVideoToken,
    saveChannelVideo,
  } = useLibrary();
  const { goBack, push } = useAppNavigation();
  const [section, setSection] = useState<ChannelSection>('videos');
  const [videoToken, setVideoToken] = useState<string | null>(null);
  const [playlistToken, setPlaylistToken] = useState<string | null>(null);
  const [playlists, setPlaylists] = useState<ChannelPlaylist[]>([]);
  const [playlistsLoaded, setPlaylistsLoaded] = useState(false);
  const [loadingVideos, setLoadingVideos] = useState(false);
  const [loadingPlaylists, setLoadingPlaylists] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set());
  const [saveTarget, setSaveTarget] = useState<ChannelVideo | null>(null);
  const [bulkTarget, setBulkTarget] = useState<'save' | 'download' | null>(null);
  const videoLoadingRef = useRef(false);
  const playlistLoadingRef = useRef(false);
  const bootstrapped = useRef(false);

  const channelVideosForHandle = useMemo(
    () =>
      channelVideos.filter(
        (video) => video.channelHandle === channel.channelHandle && !isShortVideo(video),
      ),
    [channel.channelHandle, channelVideos],
  );

  const searching = search.trim().length > 0;
  const visibleVideos = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (query.length === 0) {
      return channelVideosForHandle;
    }
    return channelVideosForHandle.filter((video) =>
      [video.title, video.description]
        .filter((field): field is string => typeof field === 'string')
        .some((field) => field.toLowerCase().includes(query)),
    );
  }, [channelVideosForHandle, search]);

  const cachedCountRef = useRef(0);
  cachedCountRef.current = channelVideosForHandle.length;

  const savedIds = useMemo(() => new Set(videos.map((video) => video.youtubeId)), [videos]);
  const downloadedIds = useMemo(
    () =>
      new Set(
        videos
          .filter((video) => video.downloadStatus === 'downloaded' && video.downloadedFileUri)
          .map((video) => video.youtubeId),
      ),
    [videos],
  );

  const loadVideos = useCallback(
    async (pageToken: string | null = null) => {
      if (!apiKeyConfigured || videoLoadingRef.current) {
        return;
      }
      videoLoadingRef.current = true;
      setLoadingVideos(true);
      setError(null);
      try {
        const result = await loadChannelVideoPage(channel, pageToken);
        setVideoToken(result.nextPageToken);
      } catch (loadError) {
        setError(loadError instanceof Error ? loadError.message : 'Videos could not be loaded.');
      } finally {
        videoLoadingRef.current = false;
        setLoadingVideos(false);
      }
    },
    [apiKeyConfigured, channel, loadChannelVideoPage],
  );

  const loadPlaylists = useCallback(
    async (pageToken: string | null = null) => {
      if (!apiKeyConfigured || playlistLoadingRef.current) {
        return;
      }
      playlistLoadingRef.current = true;
      setLoadingPlaylists(true);
      setError(null);
      try {
        const result = await loadChannelPlaylistPage(channel, pageToken);
        setPlaylists((current) =>
          pageToken ? appendUnique(current, result.items, (item) => item.playlistId) : result.items,
        );
        setPlaylistToken(result.nextPageToken);
        setPlaylistsLoaded(true);
      } catch (loadError) {
        setError(loadError instanceof Error ? loadError.message : 'Playlists could not be loaded.');
      } finally {
        playlistLoadingRef.current = false;
        setLoadingPlaylists(false);
      }
    },
    [apiKeyConfigured, channel, loadChannelPlaylistPage],
  );

  // Cached videos are shown straight away; the network is only used when the
  // cache is empty or the refresh button is pressed. That keeps the list (and
  // the scroll position) stable when coming back from a video.
  useEffect(() => {
    if (isLoading || bootstrapped.current) {
      return;
    }
    bootstrapped.current = true;
    let active = true;

    void (async () => {
      const token = await restoreChannelVideoToken(channel.channelHandle).catch(() => null);
      if (!active) {
        return;
      }
      setVideoToken(token);
      if (cachedCountRef.current === 0 && apiKeyConfigured) {
        void loadVideos(null);
      }
    })();

    return () => {
      active = false;
    };
  }, [apiKeyConfigured, channel.channelHandle, isLoading, loadVideos, restoreChannelVideoToken]);

  useEffect(() => {
    if (section !== 'playlists' || playlistsLoaded) {
      return;
    }
    let active = true;

    void (async () => {
      const [cached, token] = await Promise.all([
        loadCachedChannelPlaylists(channel.channelHandle).catch(() => []),
        restoreChannelPlaylistToken(channel.channelHandle).catch(() => null),
      ]);
      if (!active) {
        return;
      }
      if (cached.length > 0) {
        setPlaylists(cached);
        setPlaylistToken(token);
        setPlaylistsLoaded(true);
        return;
      }
      if (apiKeyConfigured) {
        void loadPlaylists(null);
      }
    })();

    return () => {
      active = false;
    };
  }, [
    apiKeyConfigured,
    channel.channelHandle,
    loadCachedChannelPlaylists,
    loadPlaylists,
    playlistsLoaded,
    restoreChannelPlaylistToken,
    section,
  ]);

  const refresh = () => {
    if (section === 'videos') {
      scrollOffsets.delete(channel.channelHandle);
      setVideoToken(null);
      void loadVideos(null);
    } else {
      setPlaylistsLoaded(false);
      setPlaylistToken(null);
      void loadPlaylists(null);
    }
  };

  const endSelection = () => {
    setSelectionMode(false);
    setSelectedIds(new Set());
    setBulkTarget(null);
  };

  const toggleSelected = (youtubeId: string) => {
    setSelectedIds((current) => {
      const next = new Set(current);
      if (next.has(youtubeId)) {
        next.delete(youtubeId);
      } else {
        next.add(youtubeId);
      }
      return next;
    });
  };

  const selectedVideos = useMemo(
    () => visibleVideos.filter((video) => selectedIds.has(video.youtubeId)),
    [selectedIds, visibleVideos],
  );

  const saveMany = useCallback(
    async (items: readonly ChannelVideo[], folderId: number | null) => {
      for (const item of items) {
        if (!savedIds.has(item.youtubeId)) {
          await saveChannelVideo(item, folderId);
        }
      }
    },
    [saveChannelVideo, savedIds],
  );

  const handleBulkFolder = (folderId: number | null) => {
    const items = [...selectedVideos];
    const mode = bulkTarget;
    setBulkTarget(null);
    if (items.length === 0 || mode === null) {
      return;
    }

    if (mode === 'save') {
      void saveMany(items, folderId)
        .then(endSelection)
        .catch((error_: unknown) => {
          Alert.alert(
            'Could not save',
            error_ instanceof Error ? error_.message : 'Some videos were not saved.',
          );
        });
      return;
    }

    promptDownloadKind(
      `Download ${items.length} ${items.length === 1 ? 'video' : 'videos'}?`,
      'They are saved to your library first, then transferred one after another.',
      (kind: DownloadKind) => {
        void saveMany(items, folderId)
          .then(() => downloadVideos(items.map((item) => item.youtubeId), kind))
          .then(endSelection)
          .catch((error_: unknown) => {
            Alert.alert(
              'Download problem',
              error_ instanceof Error ? error_.message : 'The downloads failed.',
            );
          });
      },
    );
  };

  const rememberOffset = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    if (!searching) {
      scrollOffsets.set(channel.channelHandle, event.nativeEvent.contentOffset.y);
    }
  };

  const emptyMessage = !apiKeyConfigured
    ? 'Add EXPO_PUBLIC_YOUTUBE_API_KEY to .env and rebuild the app.'
    : searching
      ? `No cached video matches “${search.trim()}”. Scroll down to load more from YouTube.`
      : (error ?? 'Nothing is available in this section.');

  return (
    <View style={styles.screen}>
      <ScreenHeader
        actions={[
          { icon: 'refresh-outline', label: 'Refresh channel', onPress: refresh },
          section === 'videos' && visibleVideos.length > 0
            ? {
                icon: selectionMode ? 'close' : 'checkmark-circle-outline',
                label: selectionMode ? 'Cancel selection' : 'Select videos',
                onPress: selectionMode ? endSelection : () => setSelectionMode(true),
              }
            : null,
        ]}
        onBack={goBack}
        subtitle={
          selectionMode ? `${selectedIds.size} selected` : channel.channelHandle
        }
        title={channel.name}
      />
      <SegmentedControl onChange={setSection} options={sections} value={section} />
      {error ? (
        <View style={[styles.notice, styles.errorNotice]}>
          <Text style={[styles.noticeText, styles.errorText]}>{error}</Text>
        </View>
      ) : null}

      {section === 'videos' ? (
        <>
          <View style={styles.searchWrap}>
            <SearchField
              onChangeText={setSearch}
              placeholder={`Search ${channel.name}`}
              value={search}
            />
          </View>
          {selectionMode ? (
            <View style={styles.selectionBar}>
              <AppButton
                icon="checkmark-done-outline"
                label="All"
                onPress={() =>
                  setSelectedIds(new Set(visibleVideos.map((video) => video.youtubeId)))
                }
                style={styles.selectionButton}
                variant="secondary"
              />
              <AppButton
                disabled={selectedIds.size === 0}
                icon="bookmark-outline"
                label="Save"
                onPress={() => setBulkTarget('save')}
                style={styles.selectionButton}
                variant="secondary"
              />
              <AppButton
                disabled={selectedIds.size === 0}
                icon="arrow-down-circle-outline"
                label="Download"
                onPress={() => setBulkTarget('download')}
                style={styles.selectionButton}
              />
            </View>
          ) : null}
          <FlatList
            contentContainerStyle={visibleVideos.length === 0 ? styles.emptyList : styles.list}
            contentOffset={{ x: 0, y: scrollOffsets.get(channel.channelHandle) ?? 0 }}
            data={visibleVideos}
            keyExtractor={(item) => item.youtubeId}
            keyboardShouldPersistTaps="handled"
            ListEmptyComponent={
              !loadingVideos ? (
                <EmptyState
                  icon={searching ? 'search-outline' : 'videocam-outline'}
                  message={emptyMessage}
                  title={searching ? 'No matches yet' : 'No videos yet'}
                />
              ) : null
            }
            ListFooterComponent={loadingVideos && visibleVideos.length > 0 ? <PageLoader /> : null}
            onEndReached={() => {
              if (videoToken && !loadingVideos) {
                void loadVideos(videoToken);
              }
            }}
            onEndReachedThreshold={0.45}
            onScroll={rememberOffset}
            renderItem={({ item }) => (
              <VideoCard
                downloaded={downloadedIds.has(item.youtubeId)}
                onLongPress={() => {
                  setSelectionMode(true);
                  toggleSelected(item.youtubeId);
                }}
