          contentContainerStyle={visibleVideos.length === 0 ? styles.emptyList : styles.list}
          data={visibleVideos}
          keyExtractor={(item) => item.youtubeId}
          ListEmptyComponent={
            !loadingVideos ? (
              <EmptyState icon="videocam-outline" message={emptyMessage} title="No videos yet" />
