import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, Alert, FlatList, StyleSheet, Text, View } from 'react-native';

import { EmptyState } from '@/components/EmptyState';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { ScreenHeader } from '@/components/ScreenHeader';
import { SearchField } from '@/components/SearchField';
import { VideoCard } from '@/components/VideoCard';
import { colors, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import type { ChannelPlaylist, ChannelVideo } from '@/types';

type PlaylistScreenProps = { playlist: ChannelPlaylist };

export function PlaylistScreen({ playlist }: PlaylistScreenProps) {
  const {
    videos,
    folders,
    apiKeyConfigured,
    loadCachedPlaylistVideos,
    loadPlaylistVideoPage,
    restorePlaylistToken,
    saveChannelVideo,
  } = useLibrary();
  const { goBack, push } = useAppNavigation();
  const [items, setItems] = useState<ChannelVideo[]>([]);
  const [nextPageToken, setNextPageToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [saveTarget, setSaveTarget] = useState<ChannelVideo | null>(null);
  const loadingRef = useRef(false);
  const savedIds = useMemo(() => new Set(videos.map((video) => video.youtubeId)), [videos]);
  const downloadedIds = useMemo(
    () =>
      new Set(
        videos
          .filter((video) => video.downloadStatus === 'downloaded' && video.downloadedFileUri)
          .map((video) => video.youtubeId),
      ),
    [videos],
  );

  const loadPage = useCallback(
    async (pageToken: string | null = null) => {
      if (!apiKeyConfigured || loadingRef.current) {
        return;
      }
      loadingRef.current = true;
      setLoading(true);
      setError(null);
      try {
        const result = await loadPlaylistVideoPage(playlist, pageToken);
        setItems((current) => {
          if (!pageToken) {
            return result.items;
          }
          const known = new Set(current.map((video) => video.youtubeId));
          return [...current, ...result.items.filter((video) => !known.has(video.youtubeId))];
        });
        setNextPageToken(result.nextPageToken);
        setLoaded(true);
      } catch (loadError) {
        setError(loadError instanceof Error ? loadError.message : 'Playlist could not be loaded.');
      } finally {
        loadingRef.current = false;
        setLoading(false);
      }
    },
    [apiKeyConfigured, loadPlaylistVideoPage, playlist],
  );

  // Cached playlist items appear immediately and stay available offline.
  useEffect(() => {
    if (loaded) {
      return;
    }
    let active = true;

    void (async () => {
      const [cached, token] = await Promise.all([
        loadCachedPlaylistVideos(playlist.playlistId).catch(() => []),
        restorePlaylistToken(playlist.playlistId).catch(() => null),
      ]);
      if (!active) {
        return;
      }
      if (cached.length > 0) {
        setItems(cached);
        setNextPageToken(token);
        setLoaded(true);
        return;
      }
      if (apiKeyConfigured) {
        void loadPage(null);
      }
    })();

    return () => {
      active = false;
    };
  }, [
    apiKeyConfigured,
    loadCachedPlaylistVideos,
    loadPage,
    loaded,
    playlist.playlistId,
    restorePlaylistToken,
  ]);

  const visibleItems = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (query.length === 0) {
      return items;
    }
    return items.filter((video) => video.title.toLowerCase().includes(query));
  }, [items, search]);

  const emptyMessage = !apiKeyConfigured
    ? 'Add EXPO_PUBLIC_YOUTUBE_API_KEY to .env and rebuild the app.'
    : (error ?? 'This playlist has no public videos.');

  return (
    <View style={styles.screen}>
      <ScreenHeader
        action={{
          icon: 'refresh-outline',
          label: 'Refresh playlist',
          onPress: () => {
            setNextPageToken(null);
            void loadPage(null);
          },
        }}
        onBack={goBack}
        subtitle={`${playlist.itemCount} videos · ${playlist.channelName}`}
        title={playlist.title}
      />
      {items.length > 0 ? (
        <View style={styles.searchWrap}>
          <SearchField
            onChangeText={setSearch}
            placeholder="Search this playlist"
            value={search}
          />
        </View>
      ) : null}
      <FlatList
        contentContainerStyle={visibleItems.length === 0 ? styles.emptyList : styles.list}
        data={visibleItems}
        keyExtractor={(item) => item.youtubeId}
        keyboardShouldPersistTaps="handled"
        ListEmptyComponent={
          !loading ? (
            <EmptyState icon="list-outline" message={emptyMessage} title="Playlist is empty" />
          ) : null
        }
        ListFooterComponent={
          loading && visibleItems.length > 0 ? (
            <View style={styles.loader}>
              <ActivityIndicator color={colors.accent} />
              <Text style={styles.loaderText}>Loading more...</Text>
            </View>
          ) : null
        }
        onEndReached={() => {
          if (nextPageToken && !loading) {
            void loadPage(nextPageToken);
          }
        }}
        onEndReachedThreshold={0.45}
        renderItem={({ item }) => (
          <VideoCard
            downloaded={downloadedIds.has(item.youtubeId)}
            onPress={() => push({ name: 'player', video: item })}
            onSave={() => setSaveTarget(item)}
            saved={savedIds.has(item.youtubeId)}
            video={item}
          />
        )}
      />
      <FolderPickerModal
        currentFolderId={null}
        folders={folders}
        onClose={() => setSaveTarget(null)}
        onSelect={(folderId) => {
          if (saveTarget) {
            void saveChannelVideo(saveTarget, folderId).catch((saveError: unknown) => {
              Alert.alert(
                'Could not save video',
                saveError instanceof Error ? saveError.message : 'Try again.',
              );
            });
          }
          setSaveTarget(null);
        }}
        title="Save to folder"
        visible={saveTarget !== null}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: colors.background },
  searchWrap: {
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.md,
  },
  list: {
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.md,
    paddingBottom: spacing.xxl,
    gap: spacing.md,
  },
  emptyList: { flexGrow: 1, justifyContent: 'center' },
  loader: { alignItems: 'center', gap: spacing.sm, paddingVertical: spacing.xl },
  loaderText: { color: colors.inkMuted, fontSize: 12 },
});

