import Ionicons from '@expo/vector-icons/Ionicons';
import { useEventListener } from 'expo';
import { Image } from 'expo-image';
import { useVideoPlayer } from 'expo-video';
import { useEffect, useRef, useState } from 'react';
import {
  type LayoutChangeEvent,
  Pressable,
  type GestureResponderEvent,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { colors, radius, spacing } from '@/constants/theme';
import { formatDuration } from '@/utils/format';

type LocalAudioPlayerProps = {
  uri: string;
  thumbnailUrl: string;
  onError: (message: string) => void;
};

export function LocalAudioPlayer({ uri, thumbnailUrl, onError }: LocalAudioPlayerProps) {
  const player = useVideoPlayer({ uri }, (instance) => {
    instance.loop = false;
    instance.staysActiveInBackground = true;
    instance.showNowPlayingNotification = true;
    instance.play();
  });
  const [playing, setPlaying] = useState(true);
  const [position, setPosition] = useState(0);
  const [duration, setDuration] = useState(0);
  const trackWidth = useRef(0);

  useEventListener(player, 'statusChange', ({ status, error }) => {
    if (status === 'error') {
      onError(error?.message ?? 'The downloaded audio could not be played.');
    }
  });

  useEventListener(player, 'playingChange', ({ isPlaying }) => setPlaying(isPlaying));

  useEffect(() => {
    const timer = setInterval(() => {
      setPosition(player.currentTime);
      setDuration(player.duration);
    }, 400);
    return () => clearInterval(timer);
  }, [player]);

  const progress = duration > 0 ? Math.min(1, Math.max(0, position / duration)) : 0;

  const seekToTouch = (event: GestureResponderEvent) => {
    if (duration <= 0 || trackWidth.current <= 0) {
      return;
    }
    const ratio = Math.min(1, Math.max(0, event.nativeEvent.locationX / trackWidth.current));
    player.currentTime = ratio * duration;
    setPosition(ratio * duration);
  };

  const measureTrack = (event: LayoutChangeEvent) => {
    trackWidth.current = event.nativeEvent.layout.width;
  };

  return (
    <View style={styles.container}>
      <Image
        cachePolicy="memory-disk"
        contentFit="cover"
        source={{ uri: thumbnailUrl }}
        style={styles.artwork}
      />
      <View style={styles.shade} />
      <View style={styles.controls}>
        <View style={styles.badge}>
          <Ionicons color={colors.accent} name="musical-notes" size={14} />
          <Text style={styles.badgeLabel}>AUDIO ONLY</Text>
        </View>
        <Pressable
          accessibilityLabel="Seek"
          accessibilityRole="adjustable"
          onLayout={measureTrack}
          onPress={seekToTouch}
          style={styles.trackTouch}
        >
          <View style={styles.track}>
            <View style={[styles.trackFill, { width: `${progress * 100}%` }]} />
          </View>
        </Pressable>
        <View style={styles.timeRow}>
          <Text style={styles.time}>{formatDuration(Math.floor(position)) ?? '0:00'}</Text>
          <Text style={styles.time}>{formatDuration(Math.floor(duration)) ?? '0:00'}</Text>
        </View>
        <View style={styles.buttons}>
          <ControlButton
            icon="play-back"
            label="Back 15 seconds"
            onPress={() => player.seekBy(-15)}
          />
          <Pressable
            accessibilityLabel={playing ? 'Pause' : 'Play'}
            accessibilityRole="button"
            onPress={() => (playing ? player.pause() : player.play())}
            style={({ pressed }) => [styles.playButton, pressed && styles.pressed]}
          >
            <Ionicons color={colors.black} name={playing ? 'pause' : 'play'} size={26} />
          </Pressable>
          <ControlButton
            icon="play-forward"
            label="Forward 15 seconds"
            onPress={() => player.seekBy(15)}
          />
        </View>
      </View>
    </View>
  );
}

function ControlButton({
  icon,
  label,
  onPress,
}: {
  icon: 'play-back' | 'play-forward';
  label: string;
  onPress: () => void;
}) {
  return (
    <Pressable
      accessibilityLabel={label}
      accessibilityRole="button"
      hitSlop={10}
      onPress={onPress}
      style={({ pressed }) => [styles.controlButton, pressed && styles.pressed]}
    >
      <Ionicons color={colors.white} name={icon} size={22} />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    aspectRatio: 16 / 9,
    minHeight: 220,
    justifyContent: 'flex-end',
    overflow: 'hidden',
