  },
  artwork: { position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 },
  shade: {
    position: 'absolute',
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
    backgroundColor: 'rgba(5, 6, 5, 0.74)',
  },
  controls: {
    paddingHorizontal: spacing.xl,
