import Ionicons from '@expo/vector-icons/Ionicons';
import { Image } from 'expo-image';
import { useKeepAwake } from 'expo-keep-awake';
import { useEffect, useRef, useState } from 'react';
import {
  Alert,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { AppButton } from '@/components/AppButton';
import { FolderPickerModal } from '@/components/FolderPickerModal';
import { LocalAudioPlayer } from '@/components/LocalAudioPlayer';
import { LocalVideoPlayer } from '@/components/LocalVideoPlayer';
import { ScreenHeader } from '@/components/ScreenHeader';
import { YouTubePlayer } from '@/components/YouTubePlayer';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import { useAppNavigation } from '@/context/NavigationContext';
import { fetchVideoMetadata } from '@/services/youtube';
import type { PlayableVideo } from '@/types';
import { promptDownloadKind } from '@/utils/downloadPrompt';
import { formatDuration, formatPublishedDate, formatRelativeDate } from '@/utils/format';

type PlayerScreenProps = { video: PlayableVideo };

export function PlayerScreen({ video }: PlayerScreenProps) {
  // The screen must not dim or lock while something is playing.
  useKeepAwake();
  const { goBack } = useAppNavigation();
  const { folders, saveVideo, videos, downloadVideo, updateNotes } = useLibrary();
  const [playerError, setPlayerError] = useState<string | null>(null);
  const [ended, setEnded] = useState(false);
  const [playerSession, setPlayerSession] = useState(0);
  const [descriptionExpanded, setDescriptionExpanded] = useState(false);
  const [description, setDescription] = useState(video.description);
  const [saveVisible, setSaveVisible] = useState(false);
  const savedVideo = videos.find((entry) => entry.youtubeId === video.youtubeId);
  const saved = savedVideo !== undefined;
  const localFileUri =
    savedVideo?.downloadStatus === 'downloaded' && savedVideo.downloadedFileUri
      ? savedVideo.downloadedFileUri
      : null;
  const isDownloaded = localFileUri !== null;
  const isAudioOnly = isDownloaded && savedVideo?.downloadKind === 'audio';
  const isTransferring =
    savedVideo?.downloadStatus === 'queued' || savedVideo?.downloadStatus === 'downloading';
  const duration = formatDuration(video.durationSeconds);
  const published = formatPublishedDate(video.publishedAt);
  const publishedAge = formatRelativeDate(video.publishedAt);

  const [noteDraft, setNoteDraft] = useState(savedVideo?.notes ?? '');
  const noteTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingNote = useRef<string | null>(null);
  const updateNotesRef = useRef(updateNotes);
  updateNotesRef.current = updateNotes;

  useEffect(() => {
    setNoteDraft(savedVideo?.notes ?? '');
    // Only reset when the note belongs to a different video.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [video.youtubeId, saved]);

  useEffect(() => {
    if (description || isDownloaded) {
      return;
    }
    let active = true;
    void fetchVideoMetadata(video.youtubeId, process.env.EXPO_PUBLIC_YOUTUBE_API_KEY?.trim() ?? '')
      .then((metadata) => {
        if (active) {
          setDescription(metadata.description);
        }
      })
      .catch(() => undefined);
    return () => {
      active = false;
    };
  }, [description, isDownloaded, video.youtubeId]);

  useEffect(() => {
    setPlayerError(null);
  }, [localFileUri]);

  // Flush an unsaved note when leaving the screen.
  useEffect(
    () => () => {
      if (noteTimer.current) {
        clearTimeout(noteTimer.current);
      }
      if (pendingNote.current !== null) {
        void updateNotesRef.current(video.youtubeId, pendingNote.current).catch(() => undefined);
      }
    },
    [video.youtubeId],
  );

  const changeNotes = (text: string) => {
    setNoteDraft(text);
    pendingNote.current = text;
    if (noteTimer.current) {
      clearTimeout(noteTimer.current);
    }
    noteTimer.current = setTimeout(() => {
      pendingNote.current = null;
      void updateNotes(video.youtubeId, text).catch(() => undefined);
    }, 700);
  };

  const replay = () => {
    setEnded(false);
    setPlayerError(null);
    setPlayerSession((session) => session + 1);
  };

  const startDownload = () => {
    promptDownloadKind(
      'Keep this on the device?',
      'Video keeps the picture; audio only is much smaller and plays in the background.',
      (kind) => {
        void downloadVideo(video.youtubeId, kind).catch((error: unknown) => {
          Alert.alert(
            'Download failed',
            error instanceof Error ? error.message : 'The video could not be downloaded.',
          );
        });
      },
    );
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        onBack={goBack}
        subtitle={isAudioOnly ? 'Local audio' : isDownloaded ? 'Local playback' : 'Focused playback'}
        title="Now playing"
      />
      <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
        {playerError ? (
          <View style={styles.errorPanel}>
            <Ionicons color={colors.danger} name="alert-circle-outline" size={28} />
            <Text style={styles.errorTitle}>
              {isDownloaded ? 'Local playback unavailable' : 'Playback unavailable'}
            </Text>
            <Text style={styles.errorMessage}>{playerError}</Text>
          </View>
        ) : isAudioOnly && localFileUri ? (
          <LocalAudioPlayer
            onError={setPlayerError}
            thumbnailUrl={video.thumbnailUrl}
            uri={localFileUri}
          />
        ) : isDownloaded && localFileUri ? (
          <LocalVideoPlayer onError={setPlayerError} uri={localFileUri} />
        ) : ended ? (
          <View style={styles.endedPanel}>
            <Image
              contentFit="cover"
              source={{ uri: video.thumbnailUrl }}
              style={styles.endedImage}
            />
            <View style={styles.endedShade} />
            <Pressable
              accessibilityLabel="Replay video"
              accessibilityRole="button"
              onPress={replay}
              style={({ pressed }) => [styles.replay, pressed && styles.pressed]}
            >
              <Ionicons color={colors.black} name="refresh" size={22} />
              <Text style={styles.replayText}>Replay</Text>
            </Pressable>
          </View>
        ) : (
          <YouTubePlayer
            key={playerSession}
            onEnded={() => setEnded(true)}
            onError={setPlayerError}
            youtubeId={video.youtubeId}
          />
        )}
        <View style={styles.details}>
          <Text style={styles.attribution}>
            {isAudioOnly ? 'LOCAL AUDIO' : isDownloaded ? 'LOCAL PLAYBACK' : 'YOUTUBE PLAYBACK'}
          </Text>
          <Text style={styles.title}>{video.title}</Text>
          <Text style={styles.channel}>{video.channelName}</Text>
          {duration || published ? (
            <Text style={styles.metadata}>
              {[duration, published, publishedAge].filter(Boolean).join('  ·  ')}
            </Text>
          ) : null}
          <View style={styles.actions}>
            <AppButton
              disabled={saved}
              icon={saved ? 'checkmark-circle' : 'bookmark-outline'}
              label={saved ? 'Saved' : 'Save video'}
              onPress={() => setSaveVisible(true)}
              variant={saved ? 'secondary' : 'primary'}
            />
            {saved && !isDownloaded ? (
              <AppButton
                disabled={isTransferring}
                icon={isTransferring ? 'hourglass-outline' : 'arrow-down-circle-outline'}
                label={
                  isTransferring
                    ? `${Math.round((savedVideo?.downloadProgress ?? 0) * 100)}%`
                    : 'Download'
                }
                onPress={startDownload}
                variant="secondary"
              />
            ) : null}
          </View>

          {saved ? (
            <View style={styles.notesBlock}>
              <Text style={styles.sectionLabel}>MY NOTES</Text>
              <TextInput
                multiline
                onChangeText={changeNotes}
                placeholder="Write what you want to remember about this video…"
                placeholderTextColor={colors.inkMuted}
                style={styles.notesInput}
                textAlignVertical="top"
                value={noteDraft}
              />
              <Text style={styles.notesHint}>Notes are saved on this device as you type.</Text>
            </View>
          ) : null}

          {description ? (
            <View style={styles.descriptionBlock}>
              <Text style={styles.sectionLabel}>DESCRIPTION</Text>
              <Text numberOfLines={descriptionExpanded ? undefined : 5} style={styles.description}>
                {description}
              </Text>
              <Pressable
                accessibilityRole="button"
                onPress={() => setDescriptionExpanded((expanded) => !expanded)}
                style={({ pressed }) => pressed && styles.pressed}
              >
                <Text style={styles.more}>{descriptionExpanded ? 'Show less' : 'Show more'}</Text>
              </Pressable>
            </View>
          ) : null}
        </View>
      </ScrollView>
      <FolderPickerModal
        currentFolderId={null}
        folders={folders}
        onClose={() => setSaveVisible(false)}
        onSelect={(folderId) => {
          setSaveVisible(false);
          void saveVideo({ ...video, description }, folderId).catch((error: unknown) => {
            Alert.alert(
              'Could not save video',
              error instanceof Error ? error.message : 'Try again.',
            );
          });
        }}
        title="Save to folder"
        visible={saveVisible}
      />
    </View>
  );
}

const styles = StyleSheet.create({
