input.new_string:
export type PagingState = {
  /** False when this scope has never been paged, e.g. a cache from an older build. */
  known: boolean;
  token: string | null;
};

export async function readPagingState(
  db: SQLiteDatabase,
  scope: string,
): Promise<PagingState> {
  const row = await db.getFirstAsync<{ nextPageToken: string | null }>(
    'SELECT next_page_token AS nextPageToken FROM paging_state WHERE scope = ?',
    scope,
  );
  return { known: row !== null, token: row?.nextPageToken ?? null };
}

export async function readPagingToken(
  db: SQLiteDatabase,
  scope: string,
): Promise<string | null> {
  return (await readPagingState(db, scope)).token;
}

