type FolderPickerModalProps = {
  visible: boolean;
  title?: string;
  folders: readonly Folder[];
  currentFolderId: number | null;
  onSelect: (folderId: number | null) => void;
  onClose: () => void;
};

export function FolderPickerModal({
  visible,
  title = 'Choose a folder',
  folders,
  currentFolderId,
  onSelect,
  onClose,
}: FolderPickerModalProps) {
  const { createFolder } = useLibrary();
  const tree = useMemo(() => buildFolderTree(folders), [folders]);
  // `undefined` keeps the create sheet closed; `null` creates a top level folder.
  const [creatingUnder, setCreatingUnder] = useState<number | null | undefined>(undefined);

  return (
    <>
      <BottomSheet onClose={onClose} visible={visible}>
        <Text style={styles.title}>{title}</Text>
      <ScrollView contentContainerStyle={styles.list}>
        <Pressable
          accessibilityLabel="Create a new folder"
          accessibilityRole="button"
          onPress={() => setCreatingUnder(null)}
          style={({ pressed }) => [styles.createRow, pressed && styles.pressed]}
        >
          <Ionicons color={colors.accent} name="add-circle-outline" size={20} />
          <Text style={styles.createLabel}>New folder</Text>
        </Pressable>
        <FolderRow
          current={currentFolderId === null}
          depth={0}
          label="Unfiled"
          onPress={() => onSelect(null)}
        />
        {tree.map((folder) => (
          <FolderRow
            current={currentFolderId === folder.id}
            depth={folder.depth}
            key={folder.id}
            label={folder.name}
            onAddChild={() => setCreatingUnder(folder.id)}
            onPress={() => onSelect(folder.id)}
          />
        ))}
      </ScrollView>
        <AppButton label="Cancel" onPress={onClose} variant="quiet" />
      </BottomSheet>
      <FolderNameModal
        onClose={() => setCreatingUnder(undefined)}
        onSubmit={async (name) => {
          const folderId = await createFolder(name, creatingUnder ?? null);
          setCreatingUnder(undefined);
          onSelect(folderId);
        }}
        submitLabel="Create and use"
        title={creatingUnder === null ? 'New folder' : 'New subfolder'}
        visible={creatingUnder !== undefined}
      />
    </>
  );
}

function FolderRow({
  label,
  current,
  depth,
  onPress,
  onAddChild,
}: {
  label: string;
  current: boolean;
  depth: number;
  onPress: () => void;
  onAddChild?: () => void;
}) {
  return (
    <View style={[styles.rowWrap, { paddingLeft: depth * spacing.lg }]}>
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ selected: current }}
        onPress={onPress}
        style={({ pressed }) => [
          styles.row,
          current && styles.rowCurrent,
          pressed && styles.pressed,
        ]}
      >
        <Ionicons
          color={current ? colors.black : colors.ink}
          name={
            current
              ? 'checkmark-circle'
              : depth > 0
                ? 'return-down-forward-outline'
                : 'folder-outline'
          }
          size={18}
        />
        <Text numberOfLines={1} style={[styles.rowLabel, current && styles.rowLabelCurrent]}>
          {label}
        </Text>
      </Pressable>
      {onAddChild ? (
        <Pressable
          accessibilityLabel={`Create a subfolder inside ${label}`}
          accessibilityRole="button"
          hitSlop={6}
          onPress={onAddChild}
          style={({ pressed }) => [styles.addChild, pressed && styles.pressed]}
        >
          <Ionicons color={colors.inkMuted} name="add" size={18} />
        </Pressable>
      ) : null}
    </View>
  );
}

