import Ionicons from '@expo/vector-icons/Ionicons';
import { Alert, StyleSheet, Text, View } from 'react-native';

import { AppButton } from '@/components/AppButton';
import { BottomSheet } from '@/components/BottomSheet';
import { colors, radius, spacing } from '@/constants/theme';
import { useLibrary } from '@/context/LibraryContext';
import type { DownloadKind, DownloadStatus, SavedVideo } from '@/types';

type OfflineAvailabilityModalProps = {
  video: SavedVideo | null;
  onClose: () => void;
};

const statusCopy: Record<DownloadStatus, { label: string; message: string; icon: 'cloud-outline' | 'time-outline' | 'arrow-down-circle-outline' | 'checkmark-circle-outline' | 'alert-circle-outline' | 'pause-circle-outline' }> = {
  unavailable: {
    label: 'Not available locally',
    message: 'No local copy is recorded for this video.',
    icon: 'cloud-outline',
  },
  queued: {
    label: 'Queued',
    message: 'This video is waiting for its transfer to start.',
    icon: 'time-outline',
  },
  downloading: {
    label: 'Transferring',
    message: 'The local copy is currently being prepared.',
    icon: 'arrow-down-circle-outline',
  },
  downloaded: {
    label: 'Available locally',
    message: 'A completed local copy is stored on this device.',
    icon: 'checkmark-circle-outline',
  },
  failed: {
    label: 'Transfer failed',
    message: 'The last transfer did not finish successfully.',
    icon: 'alert-circle-outline',
  },
  interrupted: {
    label: 'Transfer interrupted',
    message: 'The transfer stopped before it completed.',
    icon: 'pause-circle-outline',
  },
};

export function OfflineAvailabilityModal({ video, onClose }: OfflineAvailabilityModalProps) {
  const { downloadVideo, removeDownload, videos } = useLibrary();
  const liveVideo = video
    ? videos.find((entry) => entry.youtubeId === video.youtubeId) ?? video
    : null;
  const status = liveVideo ? statusCopy[liveVideo.downloadStatus] : statusCopy.unavailable;
  const progress = liveVideo?.downloadStatus === 'downloading'
    ? Math.max(0, Math.min(100, Math.round(liveVideo.downloadProgress * 100)))
    : null;
  const canDownload =
    liveVideo !== null &&
    (liveVideo.downloadStatus === 'unavailable' ||
      liveVideo.downloadStatus === 'failed' ||
      liveVideo.downloadStatus === 'interrupted');
  const isTransferring =
    liveVideo !== null &&
    (liveVideo.downloadStatus === 'queued' || liveVideo.downloadStatus === 'downloading');

  const startDownload = (kind: DownloadKind) => {
    if (!liveVideo) {
      return;
    }
    void downloadVideo(liveVideo.youtubeId, kind).catch((error: unknown) => {
      Alert.alert(
        'Download failed',
        error instanceof Error ? error.message : 'The video could not be downloaded.',
      );
    });
  };

  return (
    <BottomSheet onClose={onClose} visible={video !== null}>
      <Text style={styles.eyebrow}>OFFLINE AVAILABILITY</Text>
      <Text numberOfLines={2} style={styles.title}>{liveVideo?.title}</Text>
      <View style={styles.statusCard}>
        <Ionicons color={colors.accent} name={status.icon} size={28} />
        <View style={styles.statusCopy}>
          <Text style={styles.statusLabel}>{status.label}</Text>
          <Text style={styles.message}>{status.message}</Text>
          {progress !== null ? <Text style={styles.progress}>{progress}% complete</Text> : null}
        </View>
      </View>
      {canDownload ? (
        <>
          <AppButton
            icon="arrow-down-circle-outline"
            label={liveVideo?.downloadStatus === 'unavailable' ? 'Download video' : 'Retry video download'}
            onPress={() => startDownload('video')}
            style={styles.action}
          />
          <AppButton
            icon="musical-notes-outline"
            label="Download audio only"
            onPress={() => startDownload('audio')}
            style={styles.secondaryAction}
            variant="secondary"
          />
        </>
      ) : null}
      {isTransferring ? (
        <AppButton
          disabled
          icon="hourglass-outline"
          label="Transfer in progress"
          onPress={() => undefined}
          style={styles.action}
          variant="secondary"
        />
      ) : null}
      {liveVideo?.downloadStatus === 'downloaded' ? (
        <AppButton
          icon="trash-outline"
          label="Remove local copy"
          onPress={() => {
            void removeDownload(liveVideo.youtubeId);
          }}
          style={styles.action}
          variant="danger"
        />
      ) : null}
      <AppButton label="Close" onPress={onClose} style={styles.close} variant="secondary" />
    </BottomSheet>
  );
}

const styles = StyleSheet.create({
  eyebrow: {
    color: colors.accent,
    fontFamily: 'sans-serif-medium',
    fontSize: 10,
    letterSpacing: 1.1,
  },
  title: {
    color: colors.ink,
    fontFamily: 'serif',
    fontSize: 21,
