import { useState } from 'react';
import { StyleSheet, View } from 'react-native';

import { ScreenHeader } from '@/components/ScreenHeader';
import { SegmentedControl } from '@/components/SegmentedControl';
import { colors, spacing } from '@/constants/theme';
import { useAppNavigation } from '@/context/NavigationContext';
import { ChannelsView } from '@/screens/sections/ChannelsView';
import { LibraryView } from '@/screens/sections/LibraryView';

type HomeSection = 'library' | 'channels';

const sections = [
  { label: 'Saved', value: 'library' },
  { label: 'Channels', value: 'channels' },
] as const;

export function HomeScreen() {
  const [section, setSection] = useState<HomeSection>('library');
  const { push } = useAppNavigation();

  return (
    <View style={styles.screen}>
      <ScreenHeader
        action={{
          icon: 'folder-outline',
          label: 'Manage folders',
          onPress: () => push({ name: 'folders' }),
        }}
        subtitle="Only what you chose"
        title="Quiet Library"
      />
      <SegmentedControl onChange={setSection} options={sections} value={section} />
      <View style={styles.content}>
        {section === 'library' ? <LibraryView /> : <ChannelsView />}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: colors.background,
  },
  content: {
    flex: 1,
    marginTop: spacing.md,
  },
});

import { useState } from 'react';
import { StyleSheet, View } from 'react-native';

import { ScreenHeader } from '@/components/ScreenHeader';
import { SegmentedControl } from '@/components/SegmentedControl';
import { colors, spacing } from '@/constants/theme';
import { useAppNavigation } from '@/context/NavigationContext';
import { ChannelsView } from '@/screens/sections/ChannelsView';
import { LibraryView } from '@/screens/sections/LibraryView';

type HomeSection = 'library' | 'channels';

const sections = [
  { label: 'Saved', value: 'library' },
  { label: 'Channels', value: 'channels' },
] as const;

/**
 * Remembered across mounts so returning from a channel lands back on the
 * Channels tab instead of resetting to Saved.
 */
let lastSection: HomeSection = 'library';

export function HomeScreen() {
  const [section, setSection] = useState<HomeSection>(lastSection);
  const { push } = useAppNavigation();

  const changeSection = (next: HomeSection) => {
    lastSection = next;
    setSection(next);
  };

  return (
    <View style={styles.screen}>
      <ScreenHeader
        action={{
          icon: 'folder-outline',
          label: 'Manage folders',
          onPress: () => push({ name: 'folders' }),
        }}
        subtitle="Only what you chose"
        title="Quiet Library"
      />
      <SegmentedControl onChange={setSection} options={sections} value={section} />
      <View style={styles.content}>
        {section === 'library' ? <LibraryView /> : <ChannelsView />}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: colors.background,
  },
  content: {
    flex: 1,
    marginTop: spacing.md,
  },
});

