/**
 * Searches one channel's public uploads through the Data API so results are not
 * limited to what has already been cached on the device. `search.list` costs
 * 100 quota units per call, so callers should debounce.
 */
export async function searchChannelVideoPage(
  channel: HardcodedChannel,
  apiKey: string,
  query: string,
  pageToken?: string | null,
): Promise<PageResult<ChannelVideo>> {
  const key = requireApiKey(apiKey);
  const trimmed = query.trim();
  if (trimmed.length === 0) {
    return { items: [], nextPageToken: null };
  }

  const { channelId } = await resolveChannel(channel, key);
  const params = new URLSearchParams({
    part: 'snippet',
    channelId,
    q: trimmed,
    type: 'video',
    order: 'relevance',
    maxResults: PAGE_SIZE,
    key,
  });
  if (pageToken) {
    params.set('pageToken', pageToken);
  }

  const response = await fetchJson<SearchApiResponse>(
    `${YOUTUBE_API_BASE}/search?${params.toString()}`,
  );
  const ids = response.items.flatMap((item) => (item.id.videoId ? [item.id.videoId] : []));
  return {
    items: await hydrateVideoPage(ids, channel.channelHandle, key),
    nextPageToken: response.nextPageToken ?? null,
  };
}

