// Ask YouTube for matches beyond the cache. `search.list` is expensive in
// quota terms, so it only runs after typing pauses.
useEffect(() => {
  const query = search.trim();
  if (query.length < 2 || !apiKeyConfigured) {
    searchRequest.current += 1;
    setRemoteResults([]);
    setRemoteToken(null);
    setRemoteSearching(false);
    return;
  }

  const requestId = ++searchRequest.current;
  const timer = setTimeout(() => {
    setRemoteSearching(true);
    void searchChannelVideoPage(channel, query, null)
      .then((result) => {
        if (requestId !== searchRequest.current) {
          return;
        }
        setRemoteResults(result.items);
        setRemoteToken(result.nextPageToken);
      })
      .catch((searchError: unknown) => {
        if (requestId !== searchRequest.current) {
          return;
        }
        setError(
          searchError instanceof Error
            ? searchError.message
            : 'The channel could not be searched.',
        );
      })
      .finally(() => {
        if (requestId === searchRequest.current) {
          setRemoteSearching(false);
        }
      });
  }, 650);

  return () => clearTimeout(timer);
}, [apiKeyConfigured, channel, search, searchChannelVideoPage]);

const loadMoreRemote = useCallback(() => {
  const query = search.trim();
  if (!remoteToken || remoteSearching || query.length < 2) {
    return;
  }
  const requestId = searchRequest.current;
  setRemoteSearching(true);
  void searchChannelVideoPage(channel, query, remoteToken)
    .then((result) => {
      if (requestId !== searchRequest.current) {
        return;
      }
      setRemoteResults((current) =>
        appendUnique(current, result.items, (item) => item.youtubeId),
      );
      setRemoteToken(result.nextPageToken);
    })
    .catch(() => undefined)
    .finally(() => {
      if (requestId === searchRequest.current) {
        setRemoteSearching(false);
