import { requireNativeModule } from 'expo-modules-core';
import type { EventSubscription } from 'expo-modules-core';

export type StreamKind = 'video' | 'audio';

export type ResolvedStream = {
  url: string;
  quality: string;
  title: string;
  durationSeconds: number;
};

export type DownloadProgressEvent = {
  id: string;
  written: number;
  /** -1 when the server did not report a length. */
  total: number;
};

type NewPipeNativeModule = {
  resolveStream: (videoId: string, kind: StreamKind) => Promise<ResolvedStream>;
  downloadToFile: (
    url: string,
    destination: string,
    id: string,
  ) => Promise<{ uri: string; bytes: number }>;
  cancelDownload: (id: string) => void;
  addListener: (
    event: 'onDownloadProgress',
    listener: (payload: DownloadProgressEvent) => void,
  ) => EventSubscription;
};

const NewPipe = requireNativeModule<NewPipeNativeModule>('NewPipe');

export function resolveStream(videoId: string, kind: StreamKind = 'video'): Promise<ResolvedStream> {
  return NewPipe.resolveStream(videoId, kind);
}

export function downloadToFile(
  url: string,
  destination: string,
  id: string,
): Promise<{ uri: string; bytes: number }> {
  return NewPipe.downloadToFile(url, destination, id);
}

export function cancelDownload(id: string): void {
  NewPipe.cancelDownload(id);
}

export function addDownloadProgressListener(
  listener: (payload: DownloadProgressEvent) => void,
): EventSubscription {
  return NewPipe.addListener('onDownloadProgress', listener);
}

