import * as FileSystem from 'expo-file-system/legacy';

import { resolveStream } from '../../modules/newpipe';
import type { DownloadKind } from '@/types';

// Matches the User-Agent the native NewPipe Extractor module sends, so the
// googlevideo URL it resolves stays valid for the file transfer.
const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; rv:91.0) Gecko/20100101 Firefox/91.0';
const DOWNLOADS_DIR = `${FileSystem.documentDirectory}downloads/`;

export class DownloadServiceError extends Error {}

function extensionFor(kind: DownloadKind): string {
  return kind === 'audio' ? 'm4a' : 'mp4';
}

function destinationFor(youtubeId: string, kind: DownloadKind): string {
  return `${DOWNLOADS_DIR}${youtubeId}.${extensionFor(kind)}`;
}

export async function resolveStreamUrl(youtubeId: string, kind: DownloadKind): Promise<string> {
  try {
    const stream = await resolveStream(youtubeId, kind);
    return stream.url;
  } catch (error) {
    throw new DownloadServiceError(
      error instanceof Error && error.message.length > 0
        ? error.message
        : 'This video cannot be downloaded.',
    );
  }
}

export async function downloadToDevice(
  streamUrl: string,
  youtubeId: string,
  kind: DownloadKind,
  onProgress: (progress: number) => void,
): Promise<string> {
  await FileSystem.makeDirectoryAsync(DOWNLOADS_DIR, { intermediates: true });
  const destination = destinationFor(youtubeId, kind);

  const resumable = FileSystem.createDownloadResumable(
    streamUrl,
    destination,
    { headers: { 'User-Agent': USER_AGENT } },
    (progress) => {
      if (progress.totalBytesExpectedToWrite > 0) {
        onProgress(progress.totalBytesWritten / progress.totalBytesExpectedToWrite);
      }
    },
  );

  let result;
  try {
    result = await resumable.downloadAsync();
  } catch {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The file could not be saved to this device.');
  }
  if (result === undefined || result.status < 200 || result.status >= 300) {
    await FileSystem.deleteAsync(destination, { idempotent: true });
    throw new DownloadServiceError('The file could not be saved to this device.');
  }

  // A previous download of the other kind would otherwise linger on disk.
  const otherKind: DownloadKind = kind === 'audio' ? 'video' : 'audio';
  await deleteDeviceFile(destinationFor(youtubeId, otherKind));

  onProgress(1);
  return result.uri;
}

export async function deleteDeviceFile(fileUri: string | null): Promise<void> {
  if (fileUri) {
    await FileSystem.deleteAsync(fileUri, { idempotent: true }).catch(() => undefined);
  }
}

/** Removes both the video and audio copies of a saved video, whichever exist. */
export async function deleteAllDeviceFiles(youtubeId: string): Promise<void> {
  await Promise.all([
    deleteDeviceFile(destinationFor(youtubeId, 'video')),
    deleteDeviceFile(destinationFor(youtubeId, 'audio')),
  ]);
}

