// Several transfers run at once; anything beyond the limit waits its turn so
// selecting a whole folder cannot open dozens of connections.
const downloadQueue = useRef<DownloadJob[]>([]);
const pendingDownloadIds = useRef(new Set<string>());
const activeWorkers = useRef(0);
const runDownloadRef = useRef(runDownload);
runDownloadRef.current = runDownload;
const pumpRef = useRef<() => void>(() => undefined);

const pump = useCallback(() => {
  while (
    activeWorkers.current < MAX_PARALLEL_DOWNLOADS &&
    downloadQueue.current.length > 0
  ) {
    const job = downloadQueue.current.shift();
    if (job === undefined) {
      break;
    }
    activeWorkers.current += 1;
    void runDownloadRef.current(job.youtubeId, job.kind)
      .then(
        () => job.resolve(),
        (error: unknown) =>
          job.reject(error instanceof Error ? error : new Error('The download failed.')),
      )
      .finally(() => {
        activeWorkers.current -= 1;
        pendingDownloadIds.current.delete(job.youtubeId);
        pumpRef.current();
      });
  }
  setActiveDownloadCount(activeWorkers.current + downloadQueue.current.length);
}, []);
pumpRef.current = pump;

