package expo.modules.newpipe

import expo.modules.kotlin.Promise
import expo.modules.kotlin.exception.CodedException
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition
import okhttp3.OkHttpClient
import okhttp3.RequestBody.Companion.toRequestBody
import org.schabi.newpipe.extractor.MediaFormat
import org.schabi.newpipe.extractor.NewPipe
import org.schabi.newpipe.extractor.ServiceList
import org.schabi.newpipe.extractor.downloader.Downloader
import org.schabi.newpipe.extractor.downloader.Request
import org.schabi.newpipe.extractor.downloader.Response
import org.schabi.newpipe.extractor.exceptions.ReCaptchaException
import org.schabi.newpipe.extractor.localization.ContentCountry
import org.schabi.newpipe.extractor.localization.Localization
import org.schabi.newpipe.extractor.stream.StreamInfo
import java.io.File
import java.io.FileOutputStream
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

private const val USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; rv:91.0) Gecko/20100101 Firefox/91.0"

/**
 * googlevideo paces adaptive (audio-only) streams to roughly playback speed
 * when they are fetched in a single request. Asking for explicit byte ranges
 * makes each chunk transfer at full line speed, which is what yt-dlp and the
 * NewPipe app both do.
 */
private const val CHUNK_SIZE = 4L * 1024 * 1024
private const val PROGRESS_INTERVAL_BYTES = 512L * 1024

private class OkHttpDownloader : Downloader() {
  private val client = OkHttpClient.Builder()
    .connectTimeout(30, TimeUnit.SECONDS)
    .readTimeout(30, TimeUnit.SECONDS)
    .build()

  override fun execute(request: Request): Response {
    val body = request.dataToSend()?.toRequestBody(null, 0)
    val builder = okhttp3.Request.Builder()
      .method(request.httpMethod(), body)
      .url(request.url())
      .addHeader("User-Agent", USER_AGENT)

    for ((name, values) in request.headers()) {
      builder.removeHeader(name)
      for (value in values) {
        builder.addHeader(name, value)
      }
    }

    client.newCall(builder.build()).execute().use { response ->
      if (response.code == 429) {
        throw ReCaptchaException("reCaptcha Challenge requested", request.url())
      }
      return Response(
        response.code,
        response.message,
        response.headers.toMultimap(),
        response.body?.string(),
        response.request.url.toString(),
      )
    }
  }
}

private class StreamResolutionException(message: String) :
  CodedException("ERR_NEWPIPE_RESOLVE", message, null)

private class StreamDownloadException(message: String) :
  CodedException("ERR_NEWPIPE_DOWNLOAD", message, null)

class NewPipeModule : Module() {
  override fun definition() = ModuleDefinition {
    Name("NewPipe")

    Events("onDownloadProgress")

    AsyncFunction("resolveStream") { videoId: String, kind: String ->
      ensureInitialized()
      val info = try {
        StreamInfo.getInfo(ServiceList.YouTube, "https://www.youtube.com/watch?v=$videoId")
      } catch (error: Exception) {
        throw StreamResolutionException(error.message ?: "The video could not be resolved.")
      }

      if (kind == "audio") {
        val best = info.audioStreams
          .filter { it.isUrl && it.format == MediaFormat.M4A }
          .maxByOrNull { it.averageBitrate }
          ?: throw StreamResolutionException(
            "No downloadable audio track is available for this video.",
          )

        mapOf(
          "url" to best.content,
          "quality" to "${best.averageBitrate} kbps",
          "title" to info.name,
          "durationSeconds" to info.duration.toInt(),
        )
      } else {
        val best = info.videoStreams
          .filter { it.isUrl && !it.isVideoOnly() && it.format == MediaFormat.MPEG_4 }
          .maxByOrNull { parseHeight(it.getResolution()) }
          ?: throw StreamResolutionException(
            "No progressive MP4 stream is available for this video.",
          )

        mapOf(
          "url" to best.content,
          "quality" to best.getResolution(),
          "title" to info.name,
          "durationSeconds" to info.duration.toInt(),
        )
      }
    }

    AsyncFunction("downloadToFile") { url: String, destination: String, id: String, promise: Promise ->
      // Each transfer gets its own thread so several downloads really do run at
      // the same time instead of taking turns on the module queue.
      downloadExecutor.execute {
        val target = File(destination.removePrefix("file://"))
        try {
          cancelled.remove(id)
          val bytes = downloadRanged(url, target, id)
          promise.resolve(mapOf("uri" to "file://${target.absolutePath}", "bytes" to bytes))
        } catch (error: Exception) {
          target.delete()
          promise.reject(
            StreamDownloadException(
              error.message ?: "The file could not be saved to this device.",
            ),
          )
        } finally {
          cancelled.remove(id)
        }
      }
    }

    Function("cancelDownload") { id: String ->
      cancelled.add(id)
    }
  }

  private fun downloadRanged(url: String, target: File, id: String): Long {
    target.parentFile?.mkdirs()
    if (target.exists()) {
      target.delete()
    }

    var position = 0L
    var total = -1L
    var lastReported = 0L

    FileOutputStream(target).use { output ->
      while (true) {
        if (cancelled.contains(id)) {
          throw StreamDownloadException("The download was cancelled.")
        }

        val chunkStart = position
        val end = position + CHUNK_SIZE - 1
        val request = okhttp3.Request.Builder()
          .url(url)
          .header("User-Agent", USER_AGENT)
          .header("Range", "bytes=$position-$end")
          .build()

        httpClient.newCall(request).execute().use { response ->
          if (!response.isSuccessful) {
            throw StreamDownloadException("YouTube refused the transfer (${response.code}).")
          }
          val body = response.body
            ?: throw StreamDownloadException("YouTube returned an empty response.")

          if (total < 0) {
            total = contentRangeTotal(response.header("Content-Range"))
              ?: body.contentLength().takeIf { it > 0 }
              ?: -1L
          }

          val buffer = ByteArray(64 * 1024)
          body.byteStream().use { input ->
            while (true) {
              val read = input.read(buffer)
              if (read == -1) {
                break
              }
              output.write(buffer, 0, read)
              position += read

              if (position - lastReported >= PROGRESS_INTERVAL_BYTES) {
                lastReported = position
                sendEvent(
                  "onDownloadProgress",
                  mapOf("id" to id, "written" to position.toDouble(), "total" to total.toDouble()),
                )
              }
            }
          }

          // A server that ignores Range answers 200 with the whole file.
          if (response.code != 206) {
            total = position
          }
        }

        // Stop on a completed file, an unknown length, or a chunk that added
        // nothing, so a misbehaving server can never spin this loop forever.
        if (total in 1..position || total < 0 || position == chunkStart) {
          break
        }
      }
    }

    sendEvent(
      "onDownloadProgress",
      mapOf("id" to id, "written" to position.toDouble(), "total" to position.toDouble()),
    )
    return position
  }

  companion object {
    @Volatile
    private var initialized = false

    private val httpClient = OkHttpClient.Builder()
      .connectTimeout(30, TimeUnit.SECONDS)
      .readTimeout(60, TimeUnit.SECONDS)
      .build()

    private val downloadExecutor = Executors.newFixedThreadPool(4)
    private val cancelled = ConcurrentHashMap.newKeySet<String>()

    @Synchronized
    private fun doInitialize() {
      if (!initialized) {
        NewPipe.init(OkHttpDownloader(), Localization("en", "US"), ContentCountry("US"))
        initialized = true
      }
    }

    fun ensureInitialized() = doInitialize()

    fun parseHeight(resolution: String): Int =
      Regex("(\\d+)").find(resolution)?.value?.toIntOrNull() ?: 0

    /** Reads the total size out of a `Content-Range: bytes 0-4194303/12345678` header. */
    fun contentRangeTotal(header: String?): Long? =
      header?.substringAfter('/', "")?.toLongOrNull()
  }
}
